/*
 * OCR B GCSE Biology (J257) Twenty First Century Science — Exam Practice Question Bank
 * 40 written/exam-style questions per sub-topic, 1–6 marks, with full mark schemes.
 * Questions that require a diagram set needsDiagram: true so the practice UI shows a drawing pane.
 */

const BIOLOGY_OCR_B_GCSE_PRACTICE = {

  /* ─────────────────────────────── B1.1 What is the genome and what does it do? */
  'B1.1': {
    name: 'What is the genome and what does it do?',
    questions: [
      { q: 'Define the term "gene".', marks: 2, command: 'Define', markScheme: `• A short section of DNA (1)\n• that codes for a particular sequence of amino acids / a protein (1).` },
      { q: 'Define the term "genome".', marks: 2, command: 'Define', markScheme: `• The entire genetic material / DNA of an organism (1)\n• Includes all genes and non-coding sequences (1).` },
      { q: 'State the four bases found in DNA.', marks: 2, command: 'State', markScheme: `• Adenine (A), Thymine (T), Cytosine (C), Guanine (G) (2 — all four for full marks; 1 for any two).` },
      { q: 'State the base pairing rules in DNA.', marks: 2, command: 'State', markScheme: `• A pairs with T (1)\n• C pairs with G (1).` },
      { q: 'State the shape of a DNA molecule.', marks: 1, command: 'State', markScheme: `• Double helix (1).` },
      { q: 'State where DNA is found in a eukaryotic cell.', marks: 2, command: 'State', markScheme: `• In the nucleus, packaged into chromosomes (1)\n• Some DNA is also found in mitochondria / chloroplasts (1).` },
      { q: 'How many chromosomes are in a normal human body cell?', marks: 1, command: 'State', markScheme: `• 46 / 23 pairs (1).` },
      { q: 'How many pairs of chromosomes are in a human body cell?', marks: 1, command: 'State', markScheme: `• 23 pairs (1).` },
      { q: 'State the two sex chromosomes of a typical human male and a typical human female.', marks: 2, command: 'State', markScheme: `• Female: XX (1)\n• Male: XY (1).` },
      { q: 'Draw a labelled diagram of the structure of DNA, showing two complementary base pairs.', marks: 4, command: 'Draw', needsDiagram: true, markScheme: `• Two strands forming a double helix (1)\n• Sugar–phosphate backbone labelled (1)\n• Base pairing A–T (with two H-bonds shown) (1)\n• Base pairing C–G (with three H-bonds shown) (1).` },
      { q: 'Describe how the order of bases in a gene determines a protein.', marks: 3, command: 'Describe', markScheme: `• The bases are read in groups of three (triplets/codons) (1)\n• Each triplet codes for a specific amino acid (1)\n• The order of bases therefore determines the order of amino acids in the protein (1).` },
      { q: 'Explain why two strands of a DNA molecule are described as complementary.', marks: 2, command: 'Explain', markScheme: `• The bases pair specifically: A always with T and C always with G (1)\n• So the sequence on one strand determines the sequence on the other (1).` },
      { q: 'A section of one DNA strand reads: A-T-G-C-G-T. Write the complementary base sequence on the other strand.', marks: 2, command: 'State', markScheme: `• T-A-C (1)\n• G-C-A (1).` },
      { q: 'A short gene contains 90 bases. Calculate the maximum number of amino acids the gene could code for.', marks: 2, command: 'Calculate', markScheme: `• 3 bases code for 1 amino acid (1)\n• 90 ÷ 3 = 30 amino acids (1).` },
      { q: 'State two functions of proteins in cells.', marks: 2, command: 'State', markScheme: `Any 2 of: enzymes; structural proteins (e.g. collagen); transport proteins (e.g. haemoglobin); hormones e.g. insulin; antibodies (1 each).` },
      { q: 'Define the term "mutation".', marks: 1, command: 'Define', markScheme: `• A random change in the base sequence of DNA (1).` },
      { q: 'State two factors that can increase the rate of mutation.', marks: 2, command: 'State', markScheme: `Any 2 of: ionising radiation (UV/X-rays/gamma); certain chemicals (carcinogens); some viruses (1 each).` },
      { q: 'Explain why most mutations have no effect on an organism.', marks: 3, command: 'Explain', markScheme: `• Most mutations occur in non-coding DNA which does not directly code for proteins (1)\n• Some mutations are silent — code for the same amino acid because the genetic code has redundancy (1)\n• If the protein produced is similar enough, no functional change occurs (1).` },
      { q: 'Suggest one reason why a mutation in a gene that codes for an enzyme could be harmful.', marks: 2, command: 'Suggest', markScheme: `• A change to the amino acid sequence may alter the active site / shape of the enzyme (1)\n• So substrate no longer fits and the enzyme can no longer catalyse its reaction (1).` },
      { q: 'Compare a haploid cell and a diploid cell. Give one example of each in humans.', marks: 3, command: 'Compare', markScheme: `• Diploid: two sets of chromosomes / 46 in humans, e.g. body/skin cell (1)\n• Haploid: one set of chromosomes / 23 in humans, e.g. sperm or egg (1)\n• Diploid is from mitosis; haploid is from meiosis (1).` },
      { q: 'Define the term "allele".', marks: 1, command: 'Define', markScheme: `• A different version / form of the same gene (1).` },
      { q: 'A gene has two alleles, B and b. State the three possible genotypes.', marks: 2, command: 'State', markScheme: `• BB and bb (1)\n• Bb (1).` },
      { q: 'State what is meant by a "carrier" of a recessive genetic disorder.', marks: 2, command: 'State', markScheme: `• Carrier is heterozygous for the gene / has one normal and one faulty allele (1)\n• They do not show the disorder but can pass the faulty allele to children (1).` },
      { q: 'Suggest two reasons why scientists wanted to sequence the human genome.', marks: 2, command: 'Suggest', markScheme: `Any 2 of: identify genes linked to disease; understand human evolution; develop personalised medicine; identify gene-environment interactions; provide a reference for medical research (1 each).` },
      { q: 'Suggest two ethical or social concerns about widespread genome sequencing.', marks: 2, command: 'Suggest', markScheme: `Any 2 of: privacy of genetic information; possible discrimination by insurers/employers; psychological impact of learning of risks; cost and unequal access (1 each).` },
      { q: 'Watson and Crick are credited with describing the structure of DNA in 1953. Suggest one piece of evidence they used.', marks: 1, command: 'Suggest', markScheme: `• X-ray diffraction images from Rosalind Franklin (Photo 51) showing a helical pattern (1) (also accept: Chargaff\'s base ratios).` },
      { q: 'Explain how DNA replication produces two identical molecules from one.', marks: 4, command: 'Explain', markScheme: `• The two strands separate / unwind (1)\n• Each strand acts as a template (1)\n• Free nucleotides join by complementary base pairing (A–T, C–G) (1)\n• Two daughter molecules are produced, each with one original and one new strand (semi-conservative) (1).` },
      { q: 'Suggest why it is important that DNA replication is highly accurate.', marks: 2, command: 'Suggest', markScheme: `• So that daughter cells receive a complete and identical copy of the genetic information (1)\n• Errors could produce mutations leading to faulty proteins / disease (1).` },
      { q: 'Genome sequencing has revealed that humans share around 96% of their DNA with chimpanzees. Suggest what this tells us.', marks: 2, command: 'Suggest', markScheme: `• Humans and chimpanzees share a recent common ancestor (1)\n• Because protein-coding regions are largely conserved between closely related species (1).` },
      { q: 'Explain why a gene mutation in a body cell may affect only that person, but a mutation in a gamete may affect descendants.', marks: 3, command: 'Explain', markScheme: `• Body cell mutations are not passed on to offspring (1)\n• Gamete mutations are inherited by the offspring formed from that gamete (1)\n• They can be passed to subsequent generations through reproduction (1).` },
      { q: 'A scientist sequences DNA from a tumour and finds many mutations not present in the patient\'s healthy cells. Suggest how this information could be useful.', marks: 3, command: 'Suggest', markScheme: `• Identify driver mutations responsible for cancer (1)\n• Choose targeted drugs / personalised treatment (1)\n• Predict prognosis or response to therapy (1).` },
      { q: 'Compare a chromosome with a plasmid.', marks: 3, command: 'Compare', markScheme: `Any 3 of: chromosomes are linear (in eukaryotes) / single loop (in prokaryotes); plasmids are small circular DNA found in bacteria (1); chromosomes contain most of an organism\'s genes; plasmids contain extra genes e.g. antibiotic resistance (1); chromosomes are present in all body cells; plasmids can be exchanged between bacteria (1); chromosomes are larger; plasmids are smaller (1).` },
      { q: 'Draw a simple diagram of a chromosome and label the location of a single gene.', marks: 2, command: 'Draw', needsDiagram: true, markScheme: `• Diagram clearly shows X-shape or rod-shape with two chromatids (1)\n• A small region labelled "gene" with an arrow (1).` },
      { q: 'A gene codes for the protein haemoglobin. State the relationship between the order of bases in the gene and the function of haemoglobin.', marks: 3, command: 'State', markScheme: `• The base order determines the order of amino acids in the polypeptide (1)\n• The amino acid sequence determines the protein\'s 3D shape / folding (1)\n• The shape determines the protein\'s ability to bind oxygen / function correctly (1).` },
      { q: 'Suggest why a mutation that produces a "stop" codon early in a gene is likely to be very harmful.', marks: 3, command: 'Suggest', markScheme: `• Translation stops earlier than it should (1)\n• A short, truncated polypeptide is produced (1)\n• It is unlikely to fold correctly so the protein is non-functional (1).` },
      { q: 'A scientist measures the percentage of A, T, C and G in a sample of DNA. The values were: A 30%, T 30%, C 20%, G 20%. Explain what these values show.', marks: 2, command: 'Explain', markScheme: `• %A = %T and %C = %G — Chargaff\'s rule (1)\n• Consistent with complementary base pairing in a double-stranded DNA molecule (1).` },
      { q: 'Calculate the percentages of bases in a DNA molecule containing 18% adenine.', marks: 3, command: 'Calculate', markScheme: `• Thymine = 18% (A pairs with T) (1)\n• C + G total = 100 − 36 = 64% (1)\n• So C = G = 32% each (1).` },
      { q: 'A genome study finds that two species share 99.9% of their DNA. State and justify whether this is strong evidence for a recent common ancestor.', marks: 3, command: 'State', markScheme: `• Yes — high similarity suggests very few sequence changes since divergence (1)\n• Closely related species would share more DNA than distantly related ones (1)\n• Other evidence (fossils, anatomy) should also be considered (1).` },
      { q: 'Discuss the benefits and risks of patients having access to direct-to-consumer genetic test kits.', marks: 6, command: 'Discuss', markScheme: `Benefits: greater awareness of inherited risks (1); may motivate healthier lifestyles or early screening (1); useful for ancestry/identity (1).\nRisks: results without genetic counsellor support may cause anxiety (1); tests may be inaccurate or misinterpreted (1); privacy concerns about how data is stored/sold (1).\nConclusion: useful but should ideally be combined with professional support and clear regulation (1) (max 6).` },
      { q: 'A new mutation arises in a single sperm cell that fertilises an egg. Suggest the likely consequences.', marks: 3, command: 'Suggest', markScheme: `• The zygote will carry the mutation in every cell as it divides (1)\n• The mutation will be present in all body cells of the resulting individual (1)\n• It can be inherited by their children if it is in the germ line (1).` },
    ],
  },

  /* ─────────────────────────────── B1.2 How is genetic information inherited? */
  'B1.2': {
    name: 'How is genetic information inherited?',
    questions: [
      { q: 'Define the term "genotype".', marks: 1, command: 'Define', markScheme: `• The combination of alleles an organism has for a particular gene (1).` },
      { q: 'Define the term "phenotype".', marks: 1, command: 'Define', markScheme: `• The observable characteristics produced by the genotype (and the environment) (1).` },
      { q: 'State what is meant by a "homozygous" individual.', marks: 1, command: 'State', markScheme: `• Has two identical alleles of a gene (e.g. BB or bb) (1).` },
      { q: 'State what is meant by a "heterozygous" individual.', marks: 1, command: 'State', markScheme: `• Has two different alleles of a gene (e.g. Bb) (1).` },
      { q: 'Compare a dominant allele and a recessive allele.', marks: 2, command: 'Compare', markScheme: `• Dominant: only one copy needed to be expressed in the phenotype (1)\n• Recessive: both alleles must be the recessive form for the phenotype to appear (1).` },
      { q: 'In humans, sex is determined by chromosomes. State the male and female sex chromosomes.', marks: 2, command: 'State', markScheme: `• Female: XX (1)\n• Male: XY (1).` },
      { q: 'Explain how the sex of a baby is determined at fertilisation.', marks: 3, command: 'Explain', markScheme: `• All eggs carry an X chromosome (1)\n• Sperm carry either an X or a Y (1)\n• X-sperm + egg → female (XX); Y-sperm + egg → male (XY) (1).` },
      { q: 'A man (Bb) and woman (bb) have a child. Construct a Punnett square to show the possible genotypes of the child.', marks: 3, command: 'Construct', needsDiagram: true, markScheme: `Punnett:        B    b\n            b   Bb   bb\n            b   Bb   bb\n• Parental gametes correctly placed (1)\n• Offspring genotypes correct (1)\n• 50% Bb, 50% bb (1).` },
      { q: 'Use a Punnett square to predict the offspring of two heterozygous parents (Bb × Bb). Give the genotype and phenotype ratios.', marks: 4, command: 'Predict', needsDiagram: true, markScheme: `Punnett:        B    b\n            B   BB   Bb\n            b   Bb   bb\n• Correct gametes from each parent (1)\n• Correct offspring genotypes BB, Bb, Bb, bb (1)\n• Genotype ratio 1 BB : 2 Bb : 1 bb (1)\n• Phenotype ratio 3 dominant : 1 recessive (1).` },
      { q: 'In a cross between heterozygous parents (Bb × Bb) producing 80 offspring, how many would be expected to show the recessive phenotype?', marks: 2, command: 'Calculate', markScheme: `• 1/4 are bb (1)\n• 80 ÷ 4 = 20 (1).` },
      { q: 'A breeder crosses a homozygous brown (BB) cow with a homozygous white (bb) bull. State the genotype and phenotype of all F1 offspring.', marks: 2, command: 'State', markScheme: `• All offspring are Bb / heterozygous (1)\n• All show the dominant brown phenotype (1).` },
      { q: 'Describe what is meant by a "carrier" of a genetic disorder, using cystic fibrosis as an example.', marks: 3, command: 'Describe', markScheme: `• Cystic fibrosis (CF) is caused by a recessive allele (1)\n• A carrier is heterozygous (Cc) — has one normal and one faulty allele (1)\n• Carriers do not have CF themselves but can pass the faulty allele to their children (1).` },
      { q: 'Two carriers (Cc) of cystic fibrosis have a child. Use a Punnett square to find the probability the child has CF.', marks: 3, command: 'Calculate', needsDiagram: true, markScheme: `Punnett:        C    c\n            C   CC   Cc\n            c   Cc   cc\n• Correct gametes (1)\n• Offspring genotypes correct (1)\n• Probability = 1/4 / 25% the child is cc / has CF (1).` },
      { q: 'Compare continuous and discontinuous variation. Give one example of each.', marks: 4, command: 'Compare', markScheme: `• Continuous: a range of values forming a normal distribution (1) e.g. height/mass (1)\n• Discontinuous: distinct categories with no intermediates (1) e.g. blood group/eye colour (1).` },
      { q: 'Suggest two reasons why two siblings can look very different despite sharing the same parents.', marks: 2, command: 'Suggest', markScheme: `Any 2 of: random mixing of alleles in gametes (independent assortment); crossing over in meiosis; environmental influences (e.g. diet); each child inherits a unique combination of alleles (1 each).` },
      { q: 'Describe one example of how environment can influence a phenotype.', marks: 2, command: 'Describe', markScheme: `Any sensible answer with both factors: skin tanning in response to UV light (1); height affected by diet/nutrition (1); accents/spoken language influenced by upbringing (1) (max 2).` },
      { q: 'Explain why some traits are described as "polygenic".', marks: 2, command: 'Explain', markScheme: `• They are influenced by more than one gene / many genes acting together (1)\n• Often combined with environmental factors, leading to continuous variation (1).` },
      { q: 'Define the term "gamete" and state how many chromosomes a human gamete contains.', marks: 2, command: 'Define', markScheme: `• Gamete: a sex cell / haploid cell that fuses at fertilisation (1)\n• Contains 23 chromosomes in humans (1).` },
      { q: 'Explain why meiosis is needed in sexual reproduction.', marks: 3, command: 'Explain', markScheme: `• Meiosis halves the chromosome number from diploid to haploid (1)\n• So that fertilisation restores the diploid number (46 in humans) (1)\n• Without meiosis the chromosome number would double each generation (1).` },
      { q: 'Describe two ways meiosis produces genetically different gametes.', marks: 4, command: 'Describe', markScheme: `• Independent assortment — homologous chromosomes line up randomly so each gamete gets a different combination (2)\n• Crossing over — sections of homologous chromosomes are exchanged so combinations of alleles vary (2).` },
      { q: 'Compare mitosis and meiosis (give three differences).', marks: 3, command: 'Compare', markScheme: `Any 3: mitosis produces 2 daughter cells / meiosis 4 (1); mitosis daughters diploid / meiosis haploid (1); mitosis genetically identical / meiosis varied (1); mitosis for growth/repair / meiosis for gametes (1).` },
      { q: 'A pedigree shows that a trait skips a generation and appears in roughly a quarter of children of unaffected parents. Suggest the most likely inheritance pattern.', marks: 2, command: 'Suggest', markScheme: `• Autosomal recessive (1) — both parents are carriers, ~25% of offspring affected (1).` },
      { q: 'A pedigree shows the trait appearing in every generation, in roughly half the children of an affected parent. Suggest the most likely inheritance pattern.', marks: 2, command: 'Suggest', markScheme: `• Autosomal dominant (1) — affected parent passes the dominant allele to ~50% of children (1).` },
      { q: 'Haemophilia is X-linked recessive. A man with haemophilia (XʰY) has children with a non-carrier woman (XᴴXᴴ). Describe the predicted phenotypes of the children.', marks: 4, command: 'Describe', markScheme: `• All daughters inherit XʰXᴴ — they are unaffected carriers (2)\n• All sons inherit XᴴY — they are unaffected non-carriers (2).` },
      { q: 'A carrier woman (XᴴXʰ) has a child with an unaffected man (XᴴY). Calculate the probability that the child is an affected son.', marks: 3, command: 'Calculate', markScheme: `• Sons inherit Y from father and X from mother (1)\n• 1/2 of sons inherit Xʰ → affected (1)\n• Probability of affected son = 1/2 × 1/2 = 1/4 / 25% (1).` },
      { q: 'Two cats have offspring with a 1:1:1:1 ratio of black short hair, black long hair, white short hair and white long hair. Suggest the parents\' genotypes for two unlinked genes.', marks: 3, command: 'Suggest', markScheme: `• 1:1:1:1 indicates a test cross with one heterozygous parent (1)\n• e.g. BbSs × bbss (1)\n• Punnett square / explanation correctly maps to 4 phenotypes (1).` },
      { q: 'Explain why blood group is an example of discontinuous variation.', marks: 2, command: 'Explain', markScheme: `• Blood group falls into distinct categories (A, B, AB, O) (1)\n• With no intermediate values; controlled by a single gene with multiple alleles (1).` },
      { q: 'Calculate the probability that two heterozygous parents (Bb × Bb) have three children all with the recessive phenotype.', marks: 3, command: 'Calculate', markScheme: `• P(bb) for one child = 1/4 (1)\n• Independent events: 1/4 × 1/4 × 1/4 (1)\n• = 1/64 ≈ 1.6% (1).` },
      { q: 'Suggest why a cross between heterozygous parents may not produce exactly a 3:1 ratio in a real family.', marks: 2, command: 'Suggest', markScheme: `• Small sample size means actual numbers vary from predicted ratios (1)\n• Each fertilisation is an independent event with a 1/4 chance, not guaranteed (1).` },
      { q: 'Explain how identical twins are produced and why they share the same genome.', marks: 3, command: 'Explain', markScheme: `• A single fertilised egg / zygote splits into two embryos (1)\n• Both embryos develop from cells with the same DNA (1)\n• They are genetically identical with the same genome (and same sex) (1).` },
      { q: 'Identical twins raised apart sometimes differ in body mass. Explain why.', marks: 3, command: 'Explain', markScheme: `• Their genomes are identical (1)\n• Different environments — diet, exercise, lifestyle — affect phenotype (1)\n• Body mass is a polygenic, environmentally influenced trait (1).` },
      { q: 'Down syndrome is caused by an extra copy of chromosome 21. Suggest a method that could be used to diagnose this in an unborn child.', marks: 2, command: 'Suggest', markScheme: `• Karyotyping: count and arrange chromosomes from a sample (1)\n• Sample obtained by chorionic villus sampling or amniocentesis (1).` },
      { q: 'Explain how a karyotype shows the sex of an individual.', marks: 2, command: 'Explain', markScheme: `• Karyotype displays the chromosomes paired and ordered by size (1)\n• The 23rd pair shows two Xs (female) or one X and one Y (male) (1).` },
      { q: 'A scientist suggests "behaviour is determined entirely by genes". Evaluate this claim.', marks: 4, command: 'Evaluate', markScheme: `• Genes do influence many behaviours (twin/family studies) (1)\n• But environment and learning play a major role (1)\n• Identical twins raised apart show different behaviours (1)\n• Conclusion: nature AND nurture interact — claim is too simple (1).` },
      { q: 'Compare the genetic outcome of asexual reproduction with sexual reproduction.', marks: 3, command: 'Compare', markScheme: `• Asexual: offspring genetically identical to parent — clones (1)\n• Sexual: offspring genetically different — combination of two parents\' alleles (1)\n• Sexual reproduction creates variation, useful for evolution; asexual is faster (1).` },
      { q: 'Describe what is meant by a "test cross".', marks: 2, command: 'Describe', markScheme: `• Crossing an individual with the dominant phenotype with a homozygous recessive partner (1)\n• If any offspring show the recessive trait, the unknown parent must be heterozygous (1).` },
      { q: 'Use a Punnett square to perform a test cross of an unknown brown-coat cow with a white (recessive) bull. Predict outcomes for both possible genotypes of the cow.', marks: 4, command: 'Predict', needsDiagram: true, markScheme: `Case BB × bb:        B    B\n                  b   Bb   Bb\n                  b   Bb   Bb\n• All offspring brown (Bb) (1)\nCase Bb × bb:        B    b\n                  b   Bb   bb\n                  b   Bb   bb\n• 50% brown / 50% white (1)\n• If any offspring are white, mother is Bb (1); otherwise mother could be BB (1).` },
      { q: 'A family with cystic fibrosis seeks genetic counselling. Suggest two pieces of information a counsellor could provide.', marks: 2, command: 'Suggest', markScheme: `Any 2 of: probability that future children are affected; probability that healthy children are carriers; testing options (PGD, prenatal); support groups; ethical considerations (1 each).` },
      { q: 'Explain why selective abortion based on genetic test results is ethically controversial.', marks: 4, command: 'Explain', markScheme: `Any 4: respects parental autonomy / informed choice (1); avoids suffering for a child with severe disease (1); but raises disability-rights concerns — implies disabled life less valuable (1); slippery slope to "designer baby" decisions (1); equality of access — only some can afford testing (1) (max 4).` },
      { q: 'A new genetic test detects 30 risk alleles linked to type 2 diabetes. Discuss the usefulness and limitations of such a test.', marks: 6, command: 'Discuss', markScheme: `Useful: identifies people with higher risk (1); enables early lifestyle change / screening (1); supports research into the disease (1).\nLimits: T2 diabetes is multifactorial — environment plays a big role (1); risk alleles raise probability but do not predict disease (1); may cause unnecessary anxiety (1); might fail to find rare alleles or epigenetic factors (1).\nConclusion: useful as guidance, not a diagnosis; should be combined with lifestyle and family history (1) (max 6).` },
    ],
  },

  /* ─────────────────────────────── B1.3 How can and should gene technology be used? */
  'B1.3': {
    name: 'How can and should gene technology be used?',
    questions: [
      { q: 'Define the term "genetic engineering".', marks: 2, command: 'Define', markScheme: `• Deliberately modifying the DNA / genome of an organism (1)\n• by inserting, removing or editing one or more specific genes (1).` },
      { q: 'State what GMO stands for.', marks: 1, command: 'State', markScheme: `• Genetically modified organism (1).` },
      { q: 'Name the type of enzyme used to cut DNA at specific sequences.', marks: 1, command: 'Name', markScheme: `• Restriction enzymes (endonucleases) (1).` },
      { q: 'Name the enzyme that joins DNA fragments together.', marks: 1, command: 'Name', markScheme: `• DNA ligase (1).` },
      { q: 'State what is meant by a "vector" in genetic engineering.', marks: 2, command: 'State', markScheme: `• A carrier of DNA into a host cell (1)\n• Examples: plasmids, viruses (1).` },
      { q: 'Describe how restriction enzymes produce "sticky ends".', marks: 2, command: 'Describe', markScheme: `• Restriction enzymes cut DNA at specific recognition sequences (1)\n• Producing short single-stranded overhangs that can pair with complementary overhangs on another DNA fragment (1).` },
      { q: 'Describe how the human insulin gene is inserted into a bacterial plasmid.', marks: 5, command: 'Describe', markScheme: `• The same restriction enzyme cuts the human DNA and the plasmid (1)\n• Producing complementary sticky ends on both (1)\n• Sticky ends pair up by complementary base pairing (1)\n• DNA ligase joins the gene into the plasmid (1)\n• The recombinant plasmid is inserted into a bacterium by transformation (1).` },
      { q: 'Explain how genetically modified bacteria are used to produce human insulin on an industrial scale.', marks: 4, command: 'Explain', markScheme: `• GM bacteria with the insulin gene are grown in a fermenter under controlled conditions (1)\n• Bacteria multiply rapidly, transcribing and translating the gene to make human insulin (1)\n• The product is harvested and purified (1)\n• Process is faster, cheaper and produces large quantities of human-sequence insulin (1).` },
      { q: 'Suggest one advantage of using GM bacteria to produce insulin compared to extracting it from animal pancreases.', marks: 2, command: 'Suggest', markScheme: `Any 1 of: produces unlimited supply; identical to human insulin so fewer immune reactions; no animals are slaughtered; cheaper per unit (1); plus 1 mark for explanation (1).` },
      { q: 'Suggest two ethical concerns about extracting insulin from animals.', marks: 2, command: 'Suggest', markScheme: `Any 2 of: welfare/killing of animals; religious objections; risk of disease transmission; allergic reactions in humans (1 each).` },
      { q: 'Define the term "selective breeding" and give one example.', marks: 2, command: 'Define', markScheme: `• Choosing parents with desired characteristics to breed together (1)\n• Example: high-yield dairy cows / disease-resistant wheat (1).` },
      { q: 'Describe the process of selective breeding.', marks: 4, command: 'Describe', markScheme: `• Identify individuals with the desired characteristic (1)\n• Breed them together (1)\n• From the offspring, select those that show the desired trait most strongly (1)\n• Continue this process over many generations until the trait is fixed (1).` },
      { q: 'Compare selective breeding and genetic engineering.', marks: 4, command: 'Compare', markScheme: `• Selective breeding mixes whole genomes via reproduction; genetic engineering transfers specific gene(s) (1)\n• Selective breeding takes many generations; genetic engineering can be done in a single generation (1)\n• Selective breeding limited to traits already present in the species; engineering can transfer genes between species (1)\n• Selective breeding is widely accepted; engineering is more controversial (1).` },
      { q: 'Explain why selective breeding can lead to inbreeding problems.', marks: 3, command: 'Explain', markScheme: `• Repeatedly breeding closely related individuals reduces genetic variation (1)\n• Recessive harmful alleles become more likely to come together in offspring (1)\n• So genetic disorders / health issues become more common (1).` },
      { q: 'Suggest two examples of GM crops and the advantage each provides.', marks: 4, command: 'Suggest', markScheme: `Any 2 with explanation: Bt maize — produces toxin lethal to specific insects, reducing pesticide use (2); golden rice — produces beta-carotene (vitamin A precursor), helps prevent vitamin A deficiency (2); Roundup Ready soy — herbicide-resistant, makes weed control easier (2) (max 4).` },
      { q: 'Suggest two potential risks or concerns about GM crops.', marks: 2, command: 'Suggest', markScheme: `Any 2: gene flow to wild relatives; reduction in biodiversity; long-term health effects unknown; cost / patenting concentrating power in seed companies; emergence of resistant pests/weeds (1 each).` },
      { q: 'A farmer using a single Bt-maize variety finds increasing pest damage after 6 years. Explain what has likely happened.', marks: 3, command: 'Explain', markScheme: `• Strong selection pressure favours pests with mutations resistant to the Bt toxin (1)\n• Resistant pests survive and reproduce, passing on resistance alleles (1)\n• Over generations the resistant population grows / Bt becomes ineffective (1).` },
      { q: 'Describe how a farmer could reduce the rate at which Bt-resistance evolves.', marks: 3, command: 'Describe', markScheme: `• Plant non-Bt "refuge" areas alongside Bt crops so non-resistant pests can breed with resistant ones (1)\n• Rotate crops or use multiple resistance genes (gene stacking) (1)\n• Use integrated pest management — combine biological controls and chemicals carefully (1).` },
      { q: 'Define the term "gene therapy".', marks: 2, command: 'Define', markScheme: `• Treatment of a genetic disorder by introducing a working copy of the gene (1)\n• Into the patient\'s cells to compensate for the faulty allele (1).` },
      { q: 'Explain why gene therapy has had limited clinical success so far.', marks: 4, command: 'Explain', markScheme: `Any 4: difficult to deliver the gene to enough cells; immune reactions to viral vectors; effects often temporary as cells die and are replaced (1 each)\n• Risk of inserting the gene in the wrong place causing cancer (1)\n• Ethical and safety concerns slow approval (1) (max 4).` },
      { q: 'Suggest two ways the development of CRISPR-Cas9 could change medicine.', marks: 2, command: 'Suggest', markScheme: `Any 2: precise gene editing in patient cells; correction of inherited disorders; engineered immune cells for cancer therapy; rapid diagnostic tests (1 each).` },
      { q: 'Discuss one ethical objection to germline gene editing.', marks: 3, command: 'Discuss', markScheme: `• Changes to germline cells are inherited by future generations (1)\n• Future people cannot consent to changes that affect them (1)\n• Could lead to "designer babies" or social inequality if used for non-medical traits (1).` },
      { q: 'Define the term "clone".', marks: 1, command: 'Define', markScheme: `• An organism (or cell) that is genetically identical to its parent (1).` },
      { q: 'Describe the steps in plant cloning by tissue culture.', marks: 4, command: 'Describe', needsDiagram: false, markScheme: `• Take small samples of tissue (explants) from a parent plant (1)\n• Place them on sterile growth medium with plant hormones (1)\n• Cells divide forming a callus then differentiate into shoots and roots (1)\n• Plantlets are transferred to soil — all genetically identical to parent (1).` },
      { q: 'Suggest one benefit and one drawback of cloning a champion racehorse.', marks: 2, command: 'Suggest', markScheme: `Benefit: produces another animal with the same valuable genome (1).\nDrawback: identical genome doesn\'t guarantee same performance — environment matters (1) (also accept low cloning success rate; ethical concerns).` },
      { q: 'Explain why cloning rare animals could help conservation.', marks: 3, command: 'Explain', markScheme: `• Could increase numbers of endangered species (1)\n• When natural breeding is too slow / hard (1)\n• But low genetic diversity can leave the population vulnerable (limitation accepted) (1).` },
      { q: 'Describe one use of stem cells in research.', marks: 2, command: 'Describe', markScheme: `• Stem cells can differentiate into many cell types (1)\n• Used to investigate development / test drugs / model disease (1).` },
      { q: 'Suggest why embryonic stem cell use is controversial.', marks: 3, command: 'Suggest', markScheme: `• Use of human embryos raises ethical and religious concerns (1)\n• Some consider it the destruction of potential human life (1)\n• Acceptable to some only if embryos are surplus from IVF and used with consent (1).` },
      { q: 'Suggest why induced pluripotent stem (iPS) cells are of interest.', marks: 3, command: 'Suggest', markScheme: `• Made from adult cells (often skin) by reprogramming (1)\n• Avoid the ethical issues of using embryos (1)\n• Patient-specific iPS cells reduce risk of immune rejection (1).` },
      { q: 'A patient\'s damaged heart muscle is treated with stem cells from a donor. Explain why immunosuppressive drugs may be needed.', marks: 2, command: 'Explain', markScheme: `• Donor cells have different proteins on their surface (1)\n• So the immune system may recognise them as foreign and reject them (1).` },
      { q: 'Describe how DNA fingerprinting can be used in forensic science.', marks: 4, command: 'Describe', markScheme: `• DNA is extracted from a sample (e.g. hair, blood) (1)\n• Cut into fragments using restriction enzymes (1)\n• Fragments are separated by electrophoresis to give a banding pattern (1)\n• The pattern is compared with samples from suspects to find a match (1).` },
      { q: 'Explain how the chance of a coincidental match in DNA fingerprinting is very small.', marks: 2, command: 'Explain', markScheme: `• DNA profiles use multiple highly variable (polymorphic) regions of the genome (1)\n• The probability of two unrelated people sharing the same combination is extremely low / typically < 1 in a billion (1).` },
      { q: 'Suggest two limitations of using DNA fingerprinting in court.', marks: 2, command: 'Suggest', markScheme: `Any 2: risk of contamination; sample degradation; identical twins share DNA; risk of error in lab procedures; doesn\'t prove how DNA arrived at the scene (1 each).` },
      { q: 'A patient is diagnosed with a single-gene recessive disorder. Outline how a gene therapy might in principle treat them.', marks: 4, command: 'Outline', markScheme: `• A working copy of the gene is inserted into a viral vector (1)\n• Vector delivers the gene to target cells e.g. lung cells in CF (1)\n• Cells then express the working gene producing functional protein (1)\n• Treatment may need to be repeated as cells turn over (1).` },
      { q: 'Suggest why genetic engineering of human beings raises greater ethical concerns than genetic engineering of bacteria.', marks: 3, command: 'Suggest', markScheme: `• Humans cannot consent on behalf of future descendants if germ-line edited (1)\n• Possible long-term health effects of edits are uncertain (1)\n• Risk of misuse for non-medical traits or social inequality (1).` },
      { q: 'Discuss the benefits and concerns of using GM mosquitoes engineered to reduce malaria transmission.', marks: 6, command: 'Discuss', markScheme: `Benefits: could reduce malaria deaths globally (1); cheaper than long-term drug/vaccine campaigns (1); precise targeting of vector species (1).\nConcerns: ecological effects of removing a species are unpredictable (1); gene-drive systems spread quickly and irreversibly (1); long-term safety unknown; consent/social acceptance issues in affected regions (1).\nConclusion: potentially powerful but needs careful trials and international consensus (1) (max 6).` },
      { q: 'Explain how a "knockout" mouse could be used to investigate gene function.', marks: 4, command: 'Explain', markScheme: `• A specific gene is disabled (knocked out) in the mouse genome (1)\n• Phenotype of the knockout is compared to a normal (wild-type) mouse (1)\n• Differences suggest what the gene normally does (1)\n• Useful for modelling human genetic diseases and testing therapies (1).` },
      { q: 'Suggest two uses of genetic testing for adults.', marks: 2, command: 'Suggest', markScheme: `Any 2 of: identify carrier status before having children; assess inherited disease risk e.g. BRCA breast cancer; choose preventive treatment; guide drug choice (pharmacogenomics) (1 each).` },
      { q: 'Discuss the risks of genetic data being shared with insurance companies.', marks: 4, command: 'Discuss', markScheme: `Any 4: risk of discrimination — higher premiums or refused cover for those with genetic risk (1); breach of privacy (1); could discourage people from getting tested (1); legal protections vary between countries (1); could disadvantage relatives sharing some DNA (1) (max 4).` },
      { q: 'Evaluate the use of genetic engineering to address world food security.', marks: 6, command: 'Evaluate', markScheme: `Strengths: can produce higher yields, drought/pest resistant crops, vitamin-enhanced food (1; 1; 1).\nLimits: gene flow to wild plants; reduced biodiversity in farmed land (1); ethical / equitable access concerns (1); pesticide resistance can still evolve (1).\nConclusion: GM is a useful tool when combined with sustainable farming and fair distribution; not a single solution (1) (max 6).` },
    ],
  },

  /* ─────────────────────────────── B2.1 Causes of disease */
  'B2.1': { name: 'What are the causes of disease?', questions: [
    { q: 'Define the term "disease".', marks: 1, command: 'Define', markScheme: `• Any condition that disrupts the normal functioning of the body or mind (1).` },
    { q: 'State two examples of communicable diseases and two examples of non-communicable diseases.', marks: 4, command: 'State', markScheme: `Communicable: TB, measles, malaria, HIV, cholera, influenza (any 2).\nNon-communicable: CVD, type 2 diabetes, lung cancer, asthma (any 2). 1 mark each.` },
    { q: 'Define the term "pathogen".', marks: 1, command: 'Define', markScheme: `• A microorganism that causes infectious / communicable disease (1).` },
    { q: 'Name the four groups of pathogen.', marks: 2, command: 'Name', markScheme: `• Bacteria, viruses (1)\n• Fungi, protists (1).` },
    { q: 'State a disease caused by each pathogen group.', marks: 4, command: 'State', markScheme: `Bacteria: TB / cholera / Salmonella (1)\nViruses: influenza / measles / HIV (1)\nFungi: athlete\'s foot / rose black spot (1)\nProtists: malaria (1).` },
    { q: 'Describe two routes by which pathogens can spread between people.', marks: 4, command: 'Describe', markScheme: `Any 2 from: airborne droplets in coughs/sneezes (2); direct contact with body fluids (2); contaminated water/food (2); vectors e.g. mosquitoes (2). 2 marks each: identification + example.` },
    { q: 'Explain why a virus inside a cell can damage that cell.', marks: 3, command: 'Explain', markScheme: `• Virus enters cell and uses cell machinery to replicate (1)\n• Cell bursts releasing new virus particles (1)\n• This destroys the host cell and releases pathogens to infect more cells (1).` },
    { q: 'Bacteria can cause illness through two main mechanisms. State both.', marks: 2, command: 'State', markScheme: `• Damage to body cells/tissues (1)\n• Producing toxins that affect cell function (1).` },
    { q: 'Suggest why food poisoning often involves stomach pain and diarrhoea.', marks: 3, command: 'Suggest', markScheme: `• Bacteria (e.g. Salmonella) multiply in the gut (1)\n• Release toxins damaging gut wall (1)\n• Body responds with diarrhoea/vomiting to expel the pathogen (1).` },
    { q: 'Define the term "vector" in the context of disease.', marks: 2, command: 'Define', markScheme: `• An organism that transmits a pathogen from one host to another (1)\n• Without itself necessarily becoming ill (1).` },
    { q: 'Describe the role of the Anopheles mosquito in malaria.', marks: 3, command: 'Describe', markScheme: `• Female mosquito feeds on blood of an infected person, picking up Plasmodium (1)\n• Plasmodium reproduces in mosquito gut/salivary glands (1)\n• When mosquito feeds on a new host, Plasmodium is transferred (1).` },
    { q: 'State two non-lifestyle risk factors for non-communicable disease.', marks: 2, command: 'State', markScheme: `Any 2 of: genetic factors / inherited alleles; age; sex; environmental factors (UV, pollution); occupational hazards (1 each).` },
    { q: 'Suggest three lifestyle factors that increase the risk of cardiovascular disease.', marks: 3, command: 'Suggest', markScheme: `Any 3: smoking; high saturated fat / cholesterol intake; high salt; lack of exercise; excessive alcohol; obesity (1 each).` },
    { q: 'Explain how smoking increases risk of lung cancer.', marks: 3, command: 'Explain', markScheme: `• Tobacco smoke contains carcinogens (e.g. tar) (1)\n• Carcinogens cause mutations in lung cell DNA (1)\n• Mutations in tumour-suppressor or proto-oncogenes lead to uncontrolled cell division → cancer (1).` },
    { q: 'A study finds that people who eat little fibre have higher rates of bowel cancer. Explain why correlation is not the same as causation here.', marks: 3, command: 'Explain', markScheme: `• Correlation only shows two things vary together (1)\n• Other factors (e.g. processed meat, exercise, genetics) may be the real cause (1)\n• Need controlled studies, dose-response, biological mechanism to establish causation (1).` },
    { q: 'Suggest two ways disease can interact with another disease.', marks: 2, command: 'Suggest', markScheme: `Any 2: HIV reduces immunity allowing TB to develop; long-term illness causes depression; obesity increases CVD and diabetes risk together; severe stress weakens immunity (1 each).` },
    { q: 'Define the term "epidemic".', marks: 1, command: 'Define', markScheme: `• An outbreak of a disease affecting many people in a region at the same time (1).` },
    { q: 'Compare an epidemic and a pandemic.', marks: 2, command: 'Compare', markScheme: `• Epidemic: many cases in one region/country (1)\n• Pandemic: epidemic spreading across multiple countries / globally (1).` },
    { q: 'State two reasons why some pathogens (e.g. influenza) cause regular outbreaks.', marks: 2, command: 'State', markScheme: `Any 2: high mutation rate creates new strains escape existing immunity; spread by airborne droplets in crowded settings; short generation time (1 each).` },
    { q: 'Explain why HIV is sometimes called an immunodeficiency virus.', marks: 3, command: 'Explain', markScheme: `• HIV infects T-helper lymphocytes (1)\n• Reduces the immune response (1)\n• Person becomes more vulnerable to other infections — leads to AIDS (1).` },
    { q: 'Describe how genetic factors can increase the risk of disease, with one example.', marks: 3, command: 'Describe', markScheme: `• Some alleles inherited from parents increase risk of disease (1)\n• e.g. BRCA1/2 alleles → increased risk of breast/ovarian cancer (1)\n• Familial hypercholesterolaemia → high cholesterol → CVD (1) (any one example for full marks).` },
    { q: 'State two ways the environment can cause disease.', marks: 2, command: 'State', markScheme: `Any 2: UV exposure → skin cancer; air pollution → asthma/lung disease; asbestos → mesothelioma; radon gas → lung cancer (1 each).` },
    { q: 'Suggest why obesity is sometimes described as both a lifestyle and a multi-disease risk factor.', marks: 3, command: 'Suggest', markScheme: `• Caused largely by lifestyle (excess calories, low activity) (1)\n• Increases risk of type 2 diabetes (1)\n• Increases risk of CVD and some cancers (1).` },
    { q: 'Calculate the BMI of a person who has a mass of 80 kg and a height of 1.75 m. Show your working.', marks: 3, command: 'Calculate', markScheme: `• BMI = mass ÷ height² (1)\n• = 80 ÷ (1.75 × 1.75) = 80 ÷ 3.0625 (1)\n• = 26.1 (kg m⁻²) — slightly overweight (1).` },
    { q: 'Suggest two reasons why the same dose of alcohol affects two people differently.', marks: 2, command: 'Suggest', markScheme: `Any 2: body mass; sex (women have less alcohol-dehydrogenase); food in stomach; genetic differences; tolerance (1 each).` },
    { q: 'Explain why some people with diabetes may also be more likely to suffer cardiovascular disease.', marks: 3, command: 'Explain', markScheme: `• High blood glucose damages artery linings (1)\n• Increases atherosclerosis (1)\n• Diabetes is often linked to obesity which is itself a CVD risk factor (1).` },
    { q: 'A patient has a fever, cough and shortness of breath. Suggest two pathogens that could cause these symptoms.', marks: 2, command: 'Suggest', markScheme: `Any 2 of: influenza virus; SARS-CoV-2 (COVID-19); TB bacterium; pneumonia bacteria (Streptococcus) (1 each).` },
    { q: 'Suggest one reason why pathogens that cause childhood diseases often spread quickly in schools.', marks: 1, command: 'Suggest', markScheme: `• Close contact between many children allows airborne droplets / direct contact spread (1).` },
    { q: 'Describe how poor sanitation can spread cholera.', marks: 3, command: 'Describe', markScheme: `• Cholera bacteria spread in contaminated water (1)\n• If sewage contaminates drinking water, bacteria are ingested (1)\n• Bacteria multiply in the gut, causing severe diarrhoea (1).` },
    { q: 'Explain why some bacterial diseases (e.g. tetanus) are caused by a toxin rather than the bacteria themselves.', marks: 2, command: 'Explain', markScheme: `• Tetanus bacteria release a toxin (1)\n• Toxin disrupts nerve-muscle signalling causing muscle spasm even after few bacteria are present (1).` },
    { q: 'State two body sites that have a normal microbial community.', marks: 2, command: 'State', markScheme: `Any 2 of: gut, skin, mouth, vagina (1 each).` },
    { q: 'Suggest why broad-spectrum antibiotics can sometimes cause diarrhoea.', marks: 2, command: 'Suggest', markScheme: `• They kill the helpful gut bacteria as well as harmful ones (1)\n• Disturbs digestion / allows opportunistic bacteria like C. difficile to take over (1).` },
    { q: 'A scientist suspects an outbreak is caused by a virus rather than a bacterium. Suggest one piece of evidence that could support this.', marks: 2, command: 'Suggest', markScheme: `Any 2: very small (filterable through 0.2 μm); not killed by antibiotics; short incubation time; replicates inside host cells; visible only with electron microscope (any 2 for 2 marks).` },
    { q: 'Explain why mental health conditions are considered part of overall health.', marks: 2, command: 'Explain', markScheme: `• Health is not just physical — WHO definition includes mental and social well-being (1)\n• Mental and physical health interact: each can worsen the other (1).` },
    { q: 'Suggest two reasons why elderly patients are often more vulnerable to communicable disease.', marks: 2, command: 'Suggest', markScheme: `Any 2: weaker immune response with age; co-existing chronic disease; reduced lung function; less mobility / care environment exposes them to pathogens (1 each).` },
    { q: 'State one reason why washing hands before food preparation reduces disease.', marks: 1, command: 'State', markScheme: `• Removes pathogens picked up from contaminated surfaces, preventing transfer to food (1).` },
    { q: 'Explain why very young children are often given multiple vaccines on a schedule.', marks: 3, command: 'Explain', markScheme: `• Their immune systems develop and need stimulating to make memory cells (1)\n• Each vaccine targets a different pathogen / antigen (1)\n• Coordinated schedule maximises protection during years of greatest vulnerability (1).` },
    { q: 'Suggest two reasons why a healthy lifestyle reduces risk of multiple diseases at once.', marks: 2, command: 'Suggest', markScheme: `Any 2: reduced obesity → less type 2 diabetes / CVD / some cancers (1); good immunity through diet / exercise → less communicable disease (1); shared mechanisms across diseases (e.g. inflammation) (1).` },
    { q: 'Discuss the relative importance of genetic, lifestyle and environmental factors in causing non-communicable disease.', marks: 6, command: 'Discuss', markScheme: `Any 6: most NCDs have multiple causes (1); genes set susceptibility but lifestyle often determines whether the disease develops (1); e.g. type 2 diabetes — strong lifestyle component (1); some diseases highly genetic (cystic fibrosis) (1); environment (pollution, UV) is significant for some cancers (1); interactions between factors (e.g. genes + diet) are complex (1); conclusion: combined approach to prevention is most effective (1).` },
    { q: 'A scientist studies populations in two countries — country X has rising rates of type 2 diabetes; country Y\'s rates are stable. Suggest two factors that might explain the difference.', marks: 4, command: 'Suggest', markScheme: `Any 2 with explanation: diet differences (more processed food in X) — increases obesity (2); activity levels (Y more active lifestyle) (2); genetic factors (different allele frequencies) (2); healthcare and screening differences (2); economic factors (food costs) (2). Max 4.` },
  ]},

  /* ─────────────────────────────── B2.2 Defending against pathogens */
  'B2.2': { name: 'How do organisms protect themselves against pathogens?', questions: [
    { q: 'State two physical barriers in humans that prevent pathogen entry.', marks: 2, command: 'State', markScheme: `Any 2: skin (intact); mucus + cilia in airways; tears; intact blood clots over wounds (1 each).` },
    { q: 'Describe how the trachea/airways protect against pathogens.', marks: 3, command: 'Describe', markScheme: `• Goblet cells produce sticky mucus that traps pathogens (1)\n• Cilia on epithelial cells beat in waves (1)\n• Mucus + trapped pathogens move up to the throat to be swallowed (1).` },
    { q: 'Explain how stomach acid kills pathogens.', marks: 2, command: 'Explain', markScheme: `• Hydrochloric acid produced by stomach wall (1)\n• Low pH (~2) denatures pathogen enzymes / proteins → kills bacteria (1).` },
    { q: 'Name the enzyme in tears and saliva that destroys bacteria.', marks: 1, command: 'Name', markScheme: `• Lysozyme (1).` },
    { q: 'Describe how blood clotting prevents pathogen entry.', marks: 3, command: 'Describe', markScheme: `• Platelets gather at the wound (1)\n• Trigger formation of fibrin mesh trapping red blood cells (1)\n• Clot dries and forms a scab — physical barrier until skin heals (1).` },
    { q: 'Define the term "antigen".', marks: 1, command: 'Define', markScheme: `• A unique protein/molecule on the surface of a pathogen recognised by the immune system (1).` },
    { q: 'Define the term "antibody".', marks: 1, command: 'Define', markScheme: `• A Y-shaped protein produced by lymphocytes that has a specific shape complementary to one antigen (1).` },
    { q: 'Describe phagocytosis.', marks: 4, command: 'Describe', markScheme: `• Phagocyte detects pathogen (1)\n• Engulfs the pathogen by surrounding it with its membrane (1)\n• Encloses in a vacuole; lysosomes release digestive enzymes (1)\n• Pathogen is broken down (1).` },
    { q: 'Explain how lymphocytes produce antibodies and why this is "specific".', marks: 4, command: 'Explain', markScheme: `• Each lymphocyte has receptors complementary to one antigen (1)\n• When it meets that antigen it divides rapidly (clonal selection) (1)\n• Daughter cells secrete antibodies with the matching shape (1)\n• Each antibody binds to its specific antigen — like lock and key (1).` },
    { q: 'Describe two ways antibodies help destroy pathogens.', marks: 2, command: 'Describe', markScheme: `Any 2: bind & clump pathogens together (agglutination) for phagocytes; neutralise toxins; mark pathogens for destruction (1 each).` },
    { q: 'Define the term "memory cell".', marks: 2, command: 'Define', markScheme: `• A long-lived lymphocyte that remains after an infection (1)\n• Allows rapid antibody production on a second exposure to the same antigen (1).` },
    { q: 'Explain why the secondary immune response is faster and stronger than the primary response.', marks: 4, command: 'Explain', markScheme: `• Memory cells already exist for that antigen (1)\n• They rapidly divide and produce antibodies (1)\n• Larger amounts of antibody produced (1)\n• Pathogen destroyed before it can multiply enough to cause symptoms (1).` },
    { q: 'Describe how a vaccine works in 4 steps.', marks: 4, command: 'Describe', markScheme: `• Vaccine contains weakened/dead pathogen or antigens (1)\n• Lymphocytes recognise antigens and produce antibodies (1)\n• Memory cells are produced (1)\n• On real infection, secondary response is fast — destroys pathogen before symptoms (1).` },
    { q: 'Explain how herd immunity protects unvaccinated people.', marks: 3, command: 'Explain', markScheme: `• If a high % of population is immune, the pathogen has too few susceptible hosts (1)\n• Pathogen cannot spread effectively (1)\n• Even unvaccinated (e.g. very young, immunocompromised) are protected (1).` },
    { q: 'Suggest one reason why some people cannot be vaccinated.', marks: 1, command: 'Suggest', markScheme: `Any 1 of: immunocompromised; allergic to vaccine ingredient; too young; pregnant in some cases (1).` },
    { q: 'Discuss two arguments for and two against compulsory vaccination.', marks: 4, command: 'Discuss', markScheme: `For: protects population (herd immunity) (1); reduces healthcare costs (1).\nAgainst: ethical concerns about bodily autonomy (1); potential side-effects/risks (1) (max 4).` },
    { q: 'Suggest two reasons why measles can still spread despite a vaccine being available.', marks: 2, command: 'Suggest', markScheme: `Any 2: vaccine uptake below herd immunity threshold; vaccine hesitancy; supply / access in some regions; pockets of unvaccinated communities (1 each).` },
    { q: 'Define monoclonal antibody.', marks: 2, command: 'Define', markScheme: `• A single type of antibody (1)\n• Produced from a clone of a single B-lymphocyte (or hybridoma cell) (1).` },
    { q: 'Describe two body defences in plants.', marks: 2, command: 'Describe', markScheme: `Any 2: tough waxy cuticle; cellulose cell walls; bark / dead cells outer layer; antibacterial chemicals (mint); thorns/hairs (1 each).` },
    { q: 'Explain why the cellulose cell wall is described as a passive defence in plants.', marks: 2, command: 'Explain', markScheme: `• It is a permanent physical barrier (1)\n• It does not respond actively to pathogens — just blocks entry (1).` },
    { q: 'Suggest one chemical defence used by plants.', marks: 1, command: 'Suggest', markScheme: `Any 1 of: antibacterial chemicals (mint, witch hazel); poisons (foxglove); insect repellents (1).` },
    { q: 'A scientist measures antibody concentration in a person\'s blood after two doses of a vaccine. Sketch the expected graph.', marks: 3, command: 'Sketch', needsDiagram: true, markScheme: `• Small slow rise after first dose, then decline (1)\n• Larger faster rise after second dose (memory cells respond) (1)\n• Higher peak and longer-lasting antibody (1).` },
    { q: 'Compare passive and active immunity.', marks: 4, command: 'Compare', markScheme: `Passive: antibodies given directly (e.g. via placenta or injection); fast; short-lived; no memory cells (2).\nActive: own immune system makes antibodies after infection or vaccination; slower; long-lasting; memory cells made (2).` },
    { q: 'Suggest why a baby has some immunity in the first months of life.', marks: 2, command: 'Suggest', markScheme: `• Receives antibodies passively across the placenta and/or in breast milk (1)\n• Provides protection until baby\'s own immune system develops (1).` },
    { q: 'Describe how the lymphatic system supports immunity.', marks: 3, command: 'Describe', markScheme: `• Lymph nodes filter lymph fluid trapping pathogens (1)\n• B and T lymphocytes mature in lymph tissues (1)\n• Where pathogens are presented to lymphocytes for the immune response (1).` },
    { q: 'A patient with HIV has a low T-cell count. Suggest why they are more vulnerable to other infections.', marks: 3, command: 'Suggest', markScheme: `• T-cells coordinate the immune response (1)\n• Low T-cells means weaker antibody production and fewer effective phagocytosis signals (1)\n• Person more susceptible to opportunistic infections that healthy people fight off easily (1).` },
    { q: 'Suggest two ethical objections to using mice in vaccine development.', marks: 2, command: 'Suggest', markScheme: `• Animal welfare / suffering (1)\n• Moral question of using animals for human benefit (1) (also accept: results may not transfer to humans).` },
    { q: 'Describe what happens in inflammation.', marks: 3, command: 'Describe', markScheme: `• Damaged cells release chemicals (e.g. histamine) (1)\n• Blood vessels dilate → more blood flow → redness, heat, swelling (1)\n• Phagocytes attracted to the site to destroy pathogens (1).` },
    { q: 'Explain why a high temperature (fever) is part of the body\'s response to infection.', marks: 3, command: 'Explain', markScheme: `• Hypothalamus raises set point in response to chemicals from infection (1)\n• Higher temperature speeds up immune cell activity (1)\n• Inhibits some pathogen growth (1).` },
    { q: 'Suggest why "fever-reducing" drugs may not always be helpful.', marks: 2, command: 'Suggest', markScheme: `• Reducing fever may slow the body\'s natural fight against infection (1)\n• So medication is used mainly for comfort or when fever becomes dangerously high (1).` },
    { q: 'A vaccine contains the surface protein of a virus rather than the whole virus. Suggest why.', marks: 2, command: 'Suggest', markScheme: `• The protein is enough to trigger antibody production (1)\n• Avoids any chance of causing the disease — safer (1).` },
    { q: 'Suggest why some viruses (e.g. flu) need a new vaccine each year.', marks: 3, command: 'Suggest', markScheme: `• Flu virus mutates rapidly, changing its surface antigens (1)\n• Memory cells from last year\'s vaccine no longer recognise new strain (1)\n• So a new vaccine matched to the current strain is needed annually (1).` },
    { q: 'Describe how white blood cells reach a site of infection in the skin.', marks: 3, command: 'Describe', markScheme: `• Inflammation widens blood vessels → more blood flow (1)\n• White blood cells squeeze out of capillary walls into tissue (1)\n• Move toward chemical signals released by pathogens / damaged cells (1).` },
    { q: 'Explain one limitation of using antibodies for therapy in humans.', marks: 2, command: 'Explain', markScheme: `• Mouse-derived antibodies can trigger immune response when given to humans (1)\n• So humanised antibodies are used; even these can have side-effects (1).` },
    { q: 'A 6-month-old baby is vaccinated against meningitis. Predict whether they will respond to a second dose later.', marks: 3, command: 'Predict', markScheme: `• Yes — first dose primes the immune system, producing memory cells (1)\n• Second dose acts as a booster, producing a faster, larger antibody response (1)\n• Long-lasting protection against the pathogen (1).` },
    { q: 'Suggest why a long course of antibiotics may not protect against re-infection by the same bacteria a year later.', marks: 2, command: 'Suggest', markScheme: `• Antibiotics kill bacteria but don\'t make memory cells (1)\n• So if exposed again, the body has no faster immunity than before (1).` },
    { q: 'Explain why vaccinated mothers can pass some immunity to newborns.', marks: 2, command: 'Explain', markScheme: `• Antibodies cross the placenta into the fetal circulation (1)\n• Or are transferred via breast milk after birth (1).` },
    { q: 'A patient is given monoclonal antibodies as treatment. Suggest one advantage and one disadvantage.', marks: 2, command: 'Suggest', markScheme: `Advantage: highly specific — targets only the disease-causing protein (1).\nDisadvantage: side-effects can be severe / expensive to produce (1).` },
    { q: 'Describe how plants in a forest may protect themselves from insect attack.', marks: 3, command: 'Describe', markScheme: `Any 3: tough cuticle / cell walls (1); produce bitter / toxic chemicals (1); thorns or stinging hairs (1); release volatiles to attract insect predators (1).` },
    { q: 'Discuss the use of vaccination in eradicating a global disease such as smallpox.', marks: 6, command: 'Discuss', markScheme: `Any 6: smallpox declared eradicated 1980 thanks to global vaccination (1); requires high coverage to stop transmission (1); herd immunity prevents reservoirs (1); needs international cooperation, funding, surveillance (1); challenges: cold chain, hesitancy, conflict areas (1); polio is similar candidate but harder due to environmental persistence (1); conclusion: vaccination is highly effective when combined with public health (1) (max 6).` },
  ]},

  /* ─────────────────────────────── B2.3 Preventing the spread */
  'B2.3': { name: 'How can we prevent the spread of infections?', questions: [
    { q: 'State four public-health measures that reduce the spread of communicable disease.', marks: 4, command: 'State', markScheme: `Any 4 of: hand washing; covering coughs/sneezes; safe disposal of waste; clean drinking water; quarantine; vector control; safer sex; cooking food thoroughly (1 each).` },
    { q: 'Explain how hand washing with soap reduces disease spread.', marks: 3, command: 'Explain', markScheme: `• Removes pathogens physically from skin (1)\n• Soap disrupts membranes of bacteria/viruses (1)\n• Reduces transfer of pathogens to mouth/eyes/nose or to surfaces (1).` },
    { q: 'Suggest two ways the spread of cholera can be reduced in a community.', marks: 2, command: 'Suggest', markScheme: `Any 2: provide clean drinking water; treat sewage; vaccinate; good hand hygiene before food prep; isolate cases (1 each).` },
    { q: 'Describe how vaccines can lead to "herd immunity".', marks: 3, command: 'Describe', markScheme: `• If a high enough % of population is immune (1)\n• Pathogen cannot find enough susceptible hosts to spread (1)\n• Even unvaccinated people are protected (1).` },
    { q: 'Suggest a percentage of vaccinated people typically required for measles herd immunity, and why.', marks: 2, command: 'Suggest', markScheme: `• ~95% (1)\n• Because measles is highly infectious (R₀ ~ 12-18) so a very high level is needed to break transmission (1).` },
    { q: 'State the year smallpox was officially declared eradicated.', marks: 1, command: 'State', markScheme: `• 1980 (1).` },
    { q: 'Suggest two reasons why polio has not yet been eradicated despite an effective vaccine.', marks: 2, command: 'Suggest', markScheme: `Any 2: pockets of low coverage (conflict areas); vaccine hesitancy; oral polio virus can revert to virulence in rare cases; surveillance gaps (1 each).` },
    { q: 'Define "antibiotic".', marks: 1, command: 'Define', markScheme: `• A drug that kills or inhibits the growth of bacteria (1).` },
    { q: 'Explain why antibiotics do not work against viruses.', marks: 3, command: 'Explain', markScheme: `• Antibiotics target structures unique to bacteria (e.g. cell walls, ribosomes) (1)\n• Viruses lack these structures and live inside host cells (1)\n• So antibiotics have no target — antiviral drugs are needed instead (1).` },
    { q: 'Describe how antibiotic resistance evolves in a bacterial population.', marks: 5, command: 'Describe', markScheme: `• Random mutations produce a few resistant bacteria (1)\n• Antibiotic kills susceptible bacteria (1)\n• Resistant bacteria survive and reproduce (1)\n• Resistance allele passed to offspring (1)\n• Plasmids can transfer resistance gene to other species, accelerating spread (1).` },
    { q: 'Suggest three things doctors and patients can do to slow antibiotic resistance.', marks: 3, command: 'Suggest', markScheme: `Any 3: only prescribe when bacterial infection confirmed; complete the full course; not use antibiotics for viral infection; use specific (narrow-spectrum) antibiotics; restrict use in agriculture (1 each).` },
    { q: 'Suggest why over-use of antibiotics in farm animals is concerning.', marks: 3, command: 'Suggest', markScheme: `• Provides constant selection pressure (1)\n• Resistant bacteria evolve in animals (1)\n• Resistance can spread to human pathogens via the food chain (1).` },
    { q: 'A patient is told to "complete the course of antibiotics even if you feel better." Explain why.', marks: 3, command: 'Explain', markScheme: `• If treatment stops early, less-susceptible bacteria may survive (1)\n• They could reproduce and re-establish the infection (1)\n• Risk of selecting for resistance (1).` },
    { q: 'Define the term "MRSA".', marks: 1, command: 'Define', markScheme: `• Methicillin-resistant Staphylococcus aureus — a strain of bacteria resistant to many antibiotics (1).` },
    { q: 'Suggest two strategies hospitals use to control MRSA.', marks: 2, command: 'Suggest', markScheme: `Any 2: hand hygiene; isolation of infected patients; screening on admission; minimising antibiotic use; deep-cleaning wards (1 each).` },
    { q: 'Outline the main stages of drug development before approval.', marks: 5, command: 'Outline', markScheme: `• Discovery — screen candidate molecules in lab (1)\n• Pre-clinical — tested on cells then animals for safety (1)\n• Phase 1 — small group of healthy volunteers; safety/dose (1)\n• Phase 2/3 — large groups of patients; efficacy and side-effects (1)\n• Approval and ongoing safety monitoring (1).` },
    { q: 'Explain why a placebo is used in drug trials.', marks: 3, command: 'Explain', markScheme: `• A treatment with no active drug given to a control group (1)\n• Compares the real drug against any psychological "placebo effect" (1)\n• Allows scientists to see if the drug has a real effect (1).` },
    { q: 'Describe what is meant by a double-blind trial.', marks: 3, command: 'Describe', markScheme: `• Neither the patient nor the doctor knows who has the real drug (1)\n• Removes bias on both sides (1)\n• Increases reliability of results (1).` },
    { q: 'Suggest two ethical concerns about giving a placebo when an effective drug exists.', marks: 2, command: 'Suggest', markScheme: `• Patients on placebo deny themselves an effective treatment (1)\n• Researcher must balance scientific validity with duty of care (1).` },
    { q: 'A new antiviral drug is shown to reduce flu duration by 12 hours but costs £100 per course. Discuss whether the NHS should adopt it.', marks: 6, command: 'Discuss', markScheme: `Any 6: small benefit per patient; cost vs benefit per QALY; high-risk groups may benefit more; healthcare resources are finite; ethical to ration; patients\' choice; alternatives (vaccination cheaper); conclusion balanced. Max 6.` },
    { q: 'Suggest two reasons why developing a new antibiotic is expensive.', marks: 2, command: 'Suggest', markScheme: `Any 2: long trial time (10+ years); high regulatory standards; many candidate molecules fail; small market window before resistance arises (1 each).` },
    { q: 'Explain why eradicating diseases via vaccination is harder for animals than for humans.', marks: 3, command: 'Explain', markScheme: `• Animal reservoirs of disease (e.g. zoonoses) (1)\n• Difficult to vaccinate every animal in the wild (1)\n• Some diseases cross species — eradication needs cooperation across veterinary and human medicine (1).` },
    { q: 'Describe one example of how vector control reduces malaria.', marks: 3, command: 'Describe', markScheme: `• Spraying insecticide kills adult mosquitoes (1)\n• Insecticide-treated bed nets prevent biting at night (1)\n• Draining standing water reduces mosquito breeding sites (1) (any 3 for 3 marks).` },
    { q: 'Suggest two non-medical actions that can reduce respiratory virus spread.', marks: 2, command: 'Suggest', markScheme: `Any 2: ventilation of indoor spaces; mask wearing; physical distancing; reducing crowding; covering coughs (1 each).` },
    { q: 'A new variant of a flu virus arises every year. Explain how this affects vaccine design.', marks: 3, command: 'Explain', markScheme: `• Surface antigens change due to mutation (1)\n• Existing memory cells less effective (1)\n• Vaccine must be reformulated each year to match circulating strain (1).` },
    { q: 'Describe two ways a drug could be tested in animals.', marks: 2, command: 'Describe', markScheme: `Any 2: cells in culture (in vitro); whole animal in vivo studies for absorption / side-effects; long-term toxicity studies (1 each).` },
    { q: 'Suggest why some drugs that work in lab animals fail in humans.', marks: 3, command: 'Suggest', markScheme: `• Different species have different metabolism and physiology (1)\n• Side effects in humans may not appear in animals (1)\n• Drug may need different dose / formulation in humans (1).` },
    { q: 'A clinical trial reports drug X reduced symptoms in 60% of patients vs 50% on placebo. Evaluate the size of this effect.', marks: 3, command: 'Evaluate', markScheme: `• Difference 10 percentage points (1)\n• Need to consider sample size and statistical significance (1)\n• Could be clinically meaningful but modest — further study needed (1).` },
    { q: 'Suggest two reasons a person might refuse a vaccine.', marks: 2, command: 'Suggest', markScheme: `Any 2: religious objection; concern over side-effects; fear of needles; misinformation; personal autonomy (1 each).` },
    { q: 'Discuss two reasons why public-health campaigns target young children for vaccination programmes.', marks: 4, command: 'Discuss', markScheme: `• Young children develop strong immune memory from vaccines (2)\n• Reduces transmission to vulnerable groups (e.g. grandparents) (2)\n• School-based delivery is efficient and reaches many children (2). Max 4.` },
    { q: 'A drug company patents a new antibiotic for 20 years. Explain how this can both encourage and limit access to medicine.', marks: 4, command: 'Explain', markScheme: `Encourages: rewards investment in research; allows recovery of development costs (2).\nLimits: high price during patent; restricts generic competition; limits access in poorer countries (2).` },
    { q: 'A government considers banning antibiotics in animal feed. Suggest one reason for and one reason against.', marks: 2, command: 'Suggest', markScheme: `For: reduces selection pressure for resistance, protects human medicine (1).\nAgainst: animal welfare / productivity may fall, food cost rises (1).` },
    { q: 'Explain why isolation rooms are used in hospitals for infectious patients.', marks: 3, command: 'Explain', markScheme: `• Prevents pathogen spread to other patients (1)\n• Reduces airborne / contact transmission (1)\n• Allows targeted infection-control procedures (1).` },
    { q: 'Suggest one ethical issue with mandatory quarantine.', marks: 2, command: 'Suggest', markScheme: `• Restricts personal freedom (1)\n• Has to be balanced against public health benefit (1).` },
    { q: 'A scientist tries a new candidate drug in cell cultures and finds it kills the bacterium but also damages human cells. Suggest the next step.', marks: 2, command: 'Suggest', markScheme: `• Reject this candidate / modify chemical structure to reduce toxicity (1)\n• Look for an alternative target unique to the bacterium (1).` },
    { q: 'Outline two reasons why developing a vaccine for HIV has been difficult.', marks: 2, command: 'Outline', markScheme: `Any 2: HIV mutates very rapidly; surface antigens vary; HIV hides in T-cells; immune system itself is a target; multiple subtypes globally (1 each).` },
    { q: 'Describe how a sample taken from a patient could be used to identify the bacteria causing an infection.', marks: 3, command: 'Describe', markScheme: `• Swab streaked onto agar and incubated (1)\n• Bacterial colonies identified by shape, colour, Gram stain (1)\n• Sensitivity tested by disc diffusion to choose effective antibiotic (1).` },
    { q: 'Suggest one reason why measles outbreaks have re-emerged in some high-income countries.', marks: 2, command: 'Suggest', markScheme: `• Vaccine coverage has fallen below the herd-immunity threshold (1)\n• Often due to vaccine hesitancy / misinformation (1).` },
    { q: 'Explain why surveillance is key to controlling outbreaks.', marks: 3, command: 'Explain', markScheme: `• Tracks where and how cases occur in real time (1)\n• Allows early intervention (e.g. quarantine, vaccination) (1)\n• Stops local outbreaks becoming epidemics (1).` },
    { q: 'Discuss the relative importance of vaccination, antibiotics and public-health measures in controlling communicable disease.', marks: 6, command: 'Discuss', markScheme: `Any 6: vaccination prevents disease before it occurs and creates herd immunity (1); antibiotics treat bacterial infection but resistance is rising (1); public health measures (clean water, sanitation, hygiene) had biggest historical impact on infection rates (1); each is needed for different stages — prevention, treatment, control (1); no single tool is enough; interact as a portfolio (1); judgement: combining all three is most effective (1).` },
  ]},

  /* B2.4 – B6.3 — see corresponding notes pages for full content; question banks for these sub-topics in production */
  /* ─────────────────────────────── B2.4 Identifying the cause of an infection */
  'B2.4': { name: 'How can we identify the cause of an infection?', questions: [
    { q: 'State why it is important to identify the pathogen causing a communicable disease.', marks: 2, command: 'State', markScheme: `• Different pathogens need different treatments / antibiotics only work on bacteria (1)\n• So the correct treatment can be chosen and the disease controlled / spread prevented (1).` },
    { q: 'Name two types of sample that could be taken from a patient to identify a pathogen.', marks: 2, command: 'Name', markScheme: `Any 2 of: blood; urine; faeces; saliva/sputum; a tissue biopsy; a throat/wound swab (1 each).` },
    { q: 'Describe two ways a doctor can begin to identify a disease without laboratory equipment.', marks: 2, command: 'Describe', markScheme: `• Observe the symptoms shown by the patient (1)\n• Ask about recent travel / contact with infected people / medical history (1).` },
    { q: 'Explain why observing symptoms alone is often not enough to identify a pathogen.', marks: 3, command: 'Explain', markScheme: `• Many different pathogens produce very similar symptoms, e.g. fever and cough (1)\n• Some infections are symptomless in early stages (1)\n• A laboratory test is needed to confirm which pathogen is present (1).` },
    { q: 'Describe how a light microscope is used to observe microorganisms in a sample.', marks: 4, command: 'Describe', markScheme: `• Place the sample on a slide, add a stain and lower a coverslip to avoid air bubbles (1)\n• Clip the slide to the stage and select the lowest power objective lens (1)\n• Use the coarse focus to bring the specimen into view, then the fine focus to sharpen it (1)\n• Change to a higher power objective and refocus using the fine focus only (1).` },
    { q: 'Explain why a stain is used when observing bacteria under a light microscope.', marks: 2, command: 'Explain', markScheme: `• Bacterial cells are transparent / colourless and have low contrast against the background (1)\n• The stain colours the cells or their structures so they can be seen clearly (1).` },
    { q: 'A microscope has a x10 eyepiece lens and a x40 objective lens. Calculate the total magnification.', marks: 2, command: 'Calculate', markScheme: `• Total magnification = eyepiece x objective (1)\n• 10 x 40 = x400 (1).` },
    { q: 'Explain why an electron microscope, rather than a light microscope, is needed to see a virus.', marks: 3, command: 'Explain', markScheme: `• Viruses are far smaller than bacteria (tens of nanometres across) (1)\n• A light microscope does not have high enough resolution / cannot resolve objects smaller than about 200 nm (1)\n• An electron microscope has much higher resolution and magnification so virus particles can be seen (1).` },
    { q: 'Define the term "aseptic technique".', marks: 2, command: 'Define', markScheme: `• A set of procedures used when culturing microorganisms (1)\n• That prevents unwanted microorganisms from contaminating the culture, or the culture escaping into the environment (1).` },
    { q: 'Describe three aseptic techniques used when transferring bacteria to an agar plate.', marks: 3, command: 'Describe', markScheme: `Any 3 of: sterilise the inoculating loop by passing it through a Bunsen flame until red hot and allow it to cool (1); work close to a lit Bunsen burner so the updraught carries airborne microbes away (1); lift the lid of the Petri dish only slightly and at an angle (1); use pre-sterilised agar plates and sterilised glassware (1); tape the lid on after inoculating but do not seal it completely (1).` },
    { q: 'Explain why an inoculating loop is passed through a flame before it is used.', marks: 2, command: 'Explain', markScheme: `• The heat kills any microorganisms already on the loop (1)\n• So the culture is not contaminated with unwanted species, which would make the results invalid (1).` },
    { q: 'Explain why the lid of an inoculated Petri dish is taped on but not sealed all the way round.', marks: 3, command: 'Explain', markScheme: `• The tape stops the lid falling off and stops airborne microorganisms entering (1)\n• Leaving gaps allows oxygen to enter the dish (1)\n• This prevents the growth of harmful anaerobic bacteria, such as those causing food poisoning (1).` },
    { q: 'Explain why school cultures of microorganisms are incubated at 25 °C rather than 37 °C.', marks: 2, command: 'Explain', markScheme: `• 37 °C is human body temperature, so pathogens that infect humans would grow well at it (1)\n• Incubating at 25 °C reduces the risk of culturing microorganisms that are harmful to people (1).` },
    { q: 'Describe how agar jelly supports the growth of a bacterial culture.', marks: 2, command: 'Describe', markScheme: `• Agar is a solid medium containing the nutrients bacteria need, such as carbohydrate, minerals and sometimes proteins (1)\n• Bacteria can be spread on its surface and grow into visible colonies (1).` },
    { q: 'A circular bacterial colony has a diameter of 8 mm. Calculate its cross-sectional area. Give your answer to 1 decimal place.', marks: 3, command: 'Calculate', markScheme: `• radius = 8 / 2 = 4 mm (1)\n• Area = πr² = 3.142 x 4 x 4 (1)\n• = 50.3 mm² (1).` },
    { q: 'An antibiotic disc produces a clear zone of radius 6.0 mm. Calculate the cross-sectional area of the clear zone. Give your answer to 1 decimal place.', marks: 2, command: 'Calculate', markScheme: `• Area = πr² = 3.142 x 6.0 x 6.0 (1)\n• = 113.1 mm² (1).` },
    { q: 'Explain what a clear zone around an antibiotic disc on an agar plate shows.', marks: 2, command: 'Explain', markScheme: `• The antibiotic has diffused out of the disc into the agar and killed the bacteria / stopped them growing (1)\n• So no colonies are visible in that region (1).` },
    { q: 'Antibiotic A produces a clear zone of area 78 mm² and antibiotic B a zone of area 113 mm² on the same plate. Explain which antibiotic is more effective against this bacterium.', marks: 3, command: 'Explain', markScheme: `• Antibiotic B (1)\n• It produced the larger clear zone / larger area of killed bacteria (1)\n• A larger zone means the antibiotic killed or inhibited bacteria over a greater distance, so it is more effective (1).` },
    { q: 'Suggest why the clear zones should be measured as areas rather than compared by eye.', marks: 2, command: 'Suggest', markScheme: `• Measuring gives quantitative data that can be compared objectively / repeated by others (1)\n• Comparing by eye is subjective and small differences would be missed (1).` },
    { q: 'Describe how a disc soaked in sterile water should be used in an antibiotic investigation.', marks: 2, command: 'Describe', markScheme: `• It acts as a control / negative control (1)\n• It shows that any clear zone is caused by the antibiotic and not by the disc itself or the water (1).` },
    { q: 'Explain why the same species and concentration of bacteria must be used on every plate in an antibiotic investigation.', marks: 2, command: 'Explain', markScheme: `• These are control variables (1)\n• If they varied, differences in zone size could be caused by the bacteria rather than the antibiotic, making the comparison invalid (1).` },
    { q: 'Describe two ways in which a plant disease can be identified in the field.', marks: 2, command: 'Describe', markScheme: `Any 2 of: observing the symptoms, e.g. discoloured leaves, stunted growth, spots, rot, growths (1); using a gardening manual or website to match the symptoms (1); using a testing kit containing monoclonal antibodies (1).` },
    { q: 'State three visible symptoms that might suggest a plant is diseased.', marks: 3, command: 'State', markScheme: `Any 3 of: stunted growth; spots on leaves; areas of decay/rot; abnormal growths; malformed stems or leaves; discolouration/yellowing; visible pests (1 each).` },
    { q: 'Describe how isolation and reinfection can be used to identify the pathogen causing a plant disease.', marks: 4, command: 'Describe', markScheme: `• The pathogen is isolated from the diseased plant and grown in pure culture (1)\n• The cultured pathogen is used to infect a healthy plant (1)\n• If the same symptoms appear, the pathogen is the cause (1)\n• The pathogen is isolated again from the second plant and shown to be the same organism (1).` },
    { q: 'Explain why a healthy control plant is needed when testing a suspected plant pathogen by reinfection.', marks: 2, command: 'Explain', markScheme: `• The control plant is treated in the same way but not given the pathogen (1)\n• If only the infected plant develops symptoms, the pathogen must be the cause rather than the growing conditions (1).` },
    { q: 'Define the term "antigen".', marks: 2, command: 'Define', markScheme: `• A molecule, usually a protein, found on the surface of a cell or pathogen (1)\n• That is recognised as foreign by the immune system and triggers antibody production (1).` },
    { q: 'Describe how monoclonal antibodies are produced.', marks: 4, command: 'Describe', markScheme: `• The chosen antigen is injected into an animal, e.g. a mouse (1)\n• Antibody-producing cells (lymphocytes) are taken from the animal (1)\n• The cells producing the correct antibody are selected (1)\n• These cells are cultured/cloned so they divide to produce large amounts of identical antibody (1).` },
    { q: 'Explain why all the antibodies produced by a clone of cells are identical.', marks: 2, command: 'Explain', markScheme: `• All the cells in the clone are genetically identical, having come from one selected cell (1)\n• So they all make the same antibody, which binds to the same antigen (1).` },
    { q: 'Explain what is meant by saying that a monoclonal antibody is "specific".', marks: 2, command: 'Explain', markScheme: `• It binds to only one particular antigen (1)\n• Because the shape of its binding site is complementary to the shape of that antigen only (1).` },
    { q: 'Describe how a monoclonal antibody can be used in a pregnancy test.', marks: 4, command: 'Describe', markScheme: `• Urine is applied to the test strip, which carries mobile antibodies with a coloured bead attached (1)\n• If the hormone HCG is present in the urine it binds to these antibodies (1)\n• The hormone-antibody complex moves along the strip and is trapped by a second, immobilised antibody in the test window (1)\n• The coloured beads collect there, producing a visible line that shows a positive result (1).` },
    { q: 'Describe two uses of monoclonal antibodies in diagnostic tests other than pregnancy testing.', marks: 2, command: 'Describe', markScheme: `Any 2 of: detecting a specific pathogen in a blood or tissue sample (1); measuring the level of a hormone or other chemical in blood (1); detecting cancer cells by binding to a tumour antigen, with a dye or radioactive label so the tumour shows on a scan (1); identifying plant pathogens in a field testing kit (1).` },
    { q: 'Explain why a monoclonal antibody test can identify a pathogen more quickly than culturing a sample.', marks: 3, command: 'Explain', markScheme: `• The antibody binds directly to the pathogen antigen and produces a visible result in minutes (1)\n• Culturing requires bacteria to divide many times to form visible colonies, which takes hours or days (1)\n• So treatment decisions can be made much sooner (1).` },
    { q: 'Explain what is meant by the sensitivity of a diagnostic test.', marks: 2, command: 'Explain', markScheme: `• How good the test is at correctly detecting the disease when it is present (1)\n• A more sensitive test detects smaller amounts of the antigen / gives fewer false negatives (1).` },
    { q: 'A new test gives a positive result for 5 patients who do not actually have the disease. State what these results are called and suggest one consequence for those patients.', marks: 3, command: 'State', markScheme: `• They are false positives (1)\n• Consequence, any 1: unnecessary anxiety (1); unnecessary further tests or treatment that may have side effects (1); wasted healthcare resources (1).` },
    { q: 'Suggest two reasons why faster, more accurate diagnostic tests benefit a patient.', marks: 4, command: 'Suggest', markScheme: `Any 2, 2 marks each: treatment can start sooner, so the patient recovers faster and is less likely to become seriously ill (2); the correct medicine is chosen first time, avoiding ineffective treatment and unnecessary side effects (2); the patient can be isolated sooner, reducing spread to others (2).` },
    { q: 'Explain how accurate identification of a pathogen helps to slow the development of antibiotic resistance.', marks: 3, command: 'Explain', markScheme: `• It shows whether the infection is bacterial, so antibiotics are not prescribed for viral infections (1)\n• The specific antibiotic that works against that bacterium can be chosen rather than a broad-spectrum one (1)\n• Less unnecessary antibiotic use means fewer opportunities for resistant bacteria to be selected for (1).` },
    { q: 'Suggest one ethical issue raised by producing monoclonal antibodies.', marks: 2, command: 'Suggest', markScheme: `• Animals, usually mice, are injected with antigen and cells are taken from them (1)\n• Some people object to the use of animals in this way, and it must be weighed against the medical benefits to patients (1).` },
    { q: 'A doctor sends a wound swab to a laboratory. Describe the steps the laboratory would take to identify the bacterium and choose an antibiotic.', marks: 5, command: 'Describe', markScheme: `• The swab is used to inoculate a sterile agar plate using aseptic technique (1)\n• The plate is incubated so the bacteria grow into visible colonies (1)\n• The colonies are examined, e.g. by staining and light microscopy, to identify the bacterium (1)\n• Discs of different antibiotics are placed on a plate spread with that bacterium (1)\n• After incubation the antibiotic giving the largest clear zone is chosen for treatment (1).` },
    { q: 'Discuss whether monoclonal antibody testing kits should replace laboratory culture for identifying infections.', marks: 6, command: 'Discuss', markScheme: `Any 6: antibody kits give results in minutes rather than days (1); they can be used in the field or at the bedside without laboratory facilities (1); they are highly specific, so give few false positives (1); however each kit detects only one antigen, so the pathogen must be suspected in advance (1); culture can reveal an unexpected pathogen (1); culture also allows antibiotic sensitivity testing, which antibody kits cannot do (1); kits may be expensive per test while culture uses cheap materials (1); conclusion: the two are complementary, kits for rapid screening and culture for confirmation and treatment choice (1).` },
    { q: 'A scientist claims a new rapid test is "better" than the existing laboratory test. Suggest three pieces of evidence needed before that claim can be accepted.', marks: 3, command: 'Suggest', markScheme: `Any 3: data on sensitivity, i.e. the proportion of true cases it detects (1); data on specificity, i.e. how often it gives false positives (1); results from a large sample of patients so the data are reliable (1); comparison with the existing test on the same samples (1); peer review of the results by other scientists (1).` },
  ]},
  /* ─────────────────────────────── B2.5 Lifestyle, genes and the environment */
  'B2.5': { name: 'How can lifestyle, genes, and the environment affect health?', questions: [
    { q: 'Define the term "non-communicable disease".', marks: 2, command: 'Define', markScheme: `• A disease that cannot be passed from one person to another (1)\n• It is not caused by a pathogen, e.g. cardiovascular disease, cancer, type 2 diabetes (1).` },
    { q: 'State three examples of non-communicable disease.', marks: 3, command: 'State', markScheme: `Any 3 of: cardiovascular disease; any named cancer; type 2 diabetes; liver cirrhosis; emphysema/COPD; asthma (1 each).` },
    { q: 'Name three groups of factors that together determine whether a person develops a non-communicable disease.', marks: 3, command: 'Name', markScheme: `• Genetic factors / inherited genetic variants (1)\n• Lifestyle factors (1)\n• Environmental factors (1).` },
    { q: 'Explain what is meant by a "risk factor" for a disease.', marks: 2, command: 'Explain', markScheme: `• Something that increases the chance of a person developing a particular disease (1)\n• It does not mean the person will definitely get the disease (1).` },
    { q: 'Explain how genetic and lifestyle factors can interact to change the risk of disease.', marks: 3, command: 'Explain', markScheme: `• Inherited genetic variants can make a person more or less susceptible to a disease (1)\n• Lifestyle choices can then increase or decrease that inherited risk (1)\n• For example, someone with a family history of type 2 diabetes who exercises and eats well may never develop it (1).` },
    { q: 'State four lifestyle factors that increase the risk of cardiovascular disease.', marks: 4, command: 'State', markScheme: `Any 4 of: smoking; a diet high in saturated fat; a diet high in salt; lack of exercise; excessive alcohol intake; obesity (1 each).` },
    { q: 'Explain how a diet high in saturated fat increases the risk of cardiovascular disease.', marks: 3, command: 'Explain', markScheme: `• It raises the level of cholesterol in the blood (1)\n• Cholesterol is deposited as fatty plaques in the walls of the coronary arteries (1)\n• The arteries narrow, reducing blood flow to the heart muscle, which can cause a heart attack (1).` },
    { q: 'Explain how a diet high in salt increases the risk of cardiovascular disease.', marks: 2, command: 'Explain', markScheme: `• Salt causes the body to retain water, increasing blood volume and blood pressure (1)\n• High blood pressure damages artery walls and makes plaque formation and strokes more likely (1).` },
    { q: 'Explain two ways in which regular exercise reduces the risk of cardiovascular disease.', marks: 4, command: 'Explain', markScheme: `Any 2, 2 marks each: exercise helps to maintain a healthy body mass, reducing obesity-linked risk (2); it strengthens the heart muscle so the heart pumps more efficiently at a lower resting rate (2); it lowers blood pressure and improves the balance of blood cholesterol (2).` },
    { q: 'Explain how smoking increases the risk of lung cancer.', marks: 3, command: 'Explain', markScheme: `• Tobacco smoke contains carcinogens such as tar (1)\n• These cause mutations in the DNA of lung cells (1)\n• The mutated cells lose control of cell division and divide uncontrollably to form a tumour (1).` },
    { q: 'Describe two effects of smoking on the gas exchange system other than cancer.', marks: 4, command: 'Describe', markScheme: `Any 2, 2 marks each: smoke paralyses and destroys cilia so mucus is not cleared, leading to smoker\'s cough and more chest infections (2); alveolar walls break down in emphysema, reducing surface area for gas exchange and causing breathlessness (2); the airways become inflamed and narrowed in bronchitis, restricting air flow (2).` },
    { q: 'Explain why carbon monoxide in cigarette smoke is dangerous.', marks: 3, command: 'Explain', markScheme: `• Carbon monoxide binds to haemoglobin in red blood cells far more strongly than oxygen does (1)\n• This reduces the amount of oxygen the blood can carry (1)\n• Less oxygen reaches respiring tissues, so the heart must work harder, raising cardiovascular risk (1).` },
    { q: 'Explain how excessive alcohol intake can cause liver disease.', marks: 3, command: 'Explain', markScheme: `• Alcohol is toxic and is broken down in the liver (1)\n• Repeated exposure kills liver cells, which are replaced by scar tissue (cirrhosis) (1)\n• The scarred liver can no longer carry out its functions, such as removing toxins from the blood (1).` },
    { q: 'Explain why obesity is a risk factor for type 2 diabetes.', marks: 3, command: 'Explain', markScheme: `• Excess body fat, particularly around the abdomen, makes body cells less sensitive to insulin (1)\n• The pancreas produces more insulin to compensate but cells stop responding to it (1)\n• Blood glucose concentration then stays high, which is type 2 diabetes (1).` },
    { q: 'Calculate the body mass index (BMI) of a person of mass 92 kg and height 1.80 m. Give your answer to 1 decimal place.', marks: 3, command: 'Calculate', markScheme: `• BMI = mass ÷ height² (1)\n• = 92 ÷ (1.80 × 1.80) = 92 ÷ 3.24 (1)\n• = 28.4 (kg m⁻²) (1).` },
    { q: 'A person has a BMI of 33 kg m⁻². State what this indicates and suggest two diseases for which their risk is increased.', marks: 3, command: 'State', markScheme: `• A BMI above 30 indicates obesity (1)\n• Any 2 of: type 2 diabetes; cardiovascular disease; some cancers; high blood pressure (1 each, max 2).` },
    { q: 'Suggest two limitations of using BMI to assess the health risk of an individual.', marks: 4, command: 'Suggest', markScheme: `Any 2, 2 marks each: BMI does not distinguish fat from muscle, so a very muscular athlete can be classed as obese despite low body fat (2); it does not show where fat is stored, and abdominal fat carries more risk than fat elsewhere (2); the same thresholds are applied to people of different ages and body types, which may not be appropriate (2).` },
    { q: 'Describe how you could investigate the effect of exercise on pulse rate and recovery rate.', marks: 5, command: 'Describe', markScheme: `• Measure resting pulse rate by counting beats at the wrist or neck for 1 minute (1)\n• Carry out a set period of standardised exercise, e.g. step-ups for 3 minutes (1)\n• Measure pulse rate immediately after exercise (1)\n• Continue measuring pulse rate each minute until it returns to the resting value, and record this recovery time (1)\n• Repeat for several people, or repeat and mean, keeping the type and duration of exercise the same (1).` },
    { q: 'Explain why recovery rate is a better measure of fitness than resting pulse rate alone.', marks: 3, command: 'Explain', markScheme: `• Recovery rate measures how quickly the heart returns to its resting rate after exercise (1)\n• A fitter person\'s circulatory system removes lactic acid and repays the oxygen debt faster (1)\n• So a shorter recovery time indicates greater fitness, whereas resting rate alone can be affected by anxiety or caffeine (1).` },
    { q: 'A student measures the pulse rate of one person only. Explain why this makes the conclusion unreliable.', marks: 2, command: 'Explain', markScheme: `• One person is too small a sample and may not be typical (1)\n• Results could be affected by that individual\'s age, fitness or health, so they cannot be generalised (1).` },
    { q: 'Explain what is meant by a correlation between two variables.', marks: 2, command: 'Explain', markScheme: `• A relationship in which a change in one variable is linked to a change in the other (1)\n• The correlation may be positive, negative, or absent (1).` },
    { q: 'Explain why a correlation between two variables does not prove that one causes the other.', marks: 3, command: 'Explain', markScheme: `• Both variables could be caused by a third, confounding factor (1)\n• The correlation could arise by chance, especially in a small sample (1)\n• A causal link needs a plausible biological mechanism and controlled studies as well as the correlation (1).` },
    { q: 'State two features of evidence that would strengthen the case that a factor causes a disease.', marks: 2, command: 'State', markScheme: `Any 2 of: a dose-response relationship, where more exposure gives greater risk (1); a known biological mechanism linking factor and disease (1); the correlation is found repeatedly in large independent studies (1); removing the factor reduces the incidence of the disease (1).` },
    { q: 'Describe what a scatter diagram would look like if there were a strong positive correlation between daily sugar intake and body mass.', marks: 2, command: 'Describe', markScheme: `• The points would rise from bottom left to top right, so body mass increases as sugar intake increases (1)\n• The points would lie close to a straight line of best fit (1).` },
    { q: 'Explain the principle of sampling as applied to a study of disease in a population.', marks: 3, command: 'Explain', markScheme: `• A sample is a smaller group selected to represent the whole population, because studying everyone is impractical (1)\n• The sample must be large enough and chosen randomly to avoid bias (1)\n• Conclusions from the sample can then be applied to the wider population (1).` },
    { q: 'Suggest why a study of smoking and heart disease that used only men aged 50-60 could give misleading conclusions.', marks: 3, command: 'Suggest', markScheme: `• The sample is not representative of the whole population (1)\n• Results may not apply to women, or to younger or older people, whose risk differs (1)\n• Age itself is a risk factor for heart disease, so the effect of smoking cannot be separated from age (1).` },
    { q: 'In a town of 40 000 people, 480 are diagnosed with type 2 diabetes. Calculate the percentage of the population affected.', marks: 2, command: 'Calculate', markScheme: `• (480 ÷ 40 000) × 100 (1)\n• = 1.2 % (1).` },
    { q: 'Country A has 220 cases of lung cancer per 100 000 people and country B has 88 per 100 000. Calculate how many times greater the rate is in country A.', marks: 2, command: 'Calculate', markScheme: `• 220 ÷ 88 (1)\n• = 2.5 times greater (1).` },
    { q: 'Suggest three reasons why the incidence of lung cancer may differ between two countries.', marks: 3, command: 'Suggest', markScheme: `Any 3 of: different proportions of the population smoke (1); different levels of air pollution or occupational exposure (1); different age structures of the populations (1); different rates of diagnosis and reporting (1); different genetic variation between populations (1).` },
    { q: 'Suggest two reasons why the number of people with type 2 diabetes has risen in many countries over the last 50 years.', marks: 4, command: 'Suggest', markScheme: `Any 2, 2 marks each: diets have changed to include more processed food, sugar and fat, so more people are obese (2); people are less physically active because of changes in work and transport, reducing energy use (2); populations are living longer and risk increases with age (2); better screening means more cases are diagnosed (2).` },
    { q: 'Explain what is meant by the statement that different types of disease can interact.', marks: 2, command: 'Explain', markScheme: `• Having one disease can change the risk of developing or contracting another (1)\n• For example, one disease may damage a body system that then makes a second disease more likely (1).` },
    { q: 'Explain how infection with HIV can lead to a person developing tuberculosis.', marks: 3, command: 'Explain', markScheme: `• HIV infects and destroys T-helper lymphocytes (1)\n• This weakens the immune system so it cannot control infections (1)\n• TB bacteria that would normally be kept in check are able to multiply and cause disease (1).` },
    { q: 'Describe two other examples of interactions between different types of disease.', marks: 4, command: 'Describe', markScheme: `Any 2, 2 marks each: infection by some viruses, e.g. HPV, triggers changes in cells that can lead to cervical cancer (2); physical illness or disability can cause depression and other mental illness (2); immune reactions to a pathogen can trigger allergies such as asthma or eczema (2); severe physical illness can weaken the immune system and allow further infections (2).` },
    { q: 'Explain why ultraviolet radiation from sunlight is an environmental risk factor for skin cancer.', marks: 3, command: 'Explain', markScheme: `• UV radiation is absorbed by DNA in skin cells (1)\n• It causes mutations in genes controlling cell division (1)\n• Cells divide uncontrollably to form a tumour (1).` },
    { q: 'State two environmental risk factors for lung disease other than smoking.', marks: 2, command: 'State', markScheme: `Any 2 of: air pollution from vehicles or industry; asbestos fibres; radon gas; dust in mining or textile work (1 each).` },
    { q: 'Explain why doctors describe non-communicable diseases as having "multiple causes".', marks: 3, command: 'Explain', markScheme: `• Several factors act together rather than one single cause (1)\n• Genetic, lifestyle and environmental factors each contribute to the overall risk (1)\n• This is why two people with the same lifestyle may not both develop the disease (1).` },
    { q: 'Suggest two reasons why a government might target smoking rather than genetic factors when trying to reduce lung cancer.', marks: 4, command: 'Suggest', markScheme: `Any 2, 2 marks each: smoking is a lifestyle factor that people can change, whereas inherited genes cannot be changed (2); smoking accounts for a very large proportion of cases, so reducing it prevents most deaths (2); measures such as taxation and advertising bans are relatively cheap compared with genetic screening or treatment (2).` },
    { q: 'Evaluate the use of a national screening programme for type 2 diabetes.', marks: 6, command: 'Evaluate', markScheme: `Any 6: screening detects the disease early, before symptoms appear (1); early treatment and lifestyle change can prevent complications such as blindness and kidney failure (1); it identifies people at high risk who can be given advice (1); however screening is expensive and uses NHS resources (1); false positives cause anxiety and unnecessary follow-up (1); false negatives may give false reassurance (1); not everyone invited will attend, so at-risk groups may be missed (1); conclusion: worthwhile if targeted at high-risk groups rather than the whole population (1).` },
    { q: 'A study reports that people who drink more coffee have a lower rate of liver disease. Discuss whether this shows that coffee protects the liver.', marks: 6, command: 'Discuss', markScheme: `Any 6: the study shows a correlation, not necessarily causation (1); a third factor could explain it, e.g. heavy coffee drinkers may drink less alcohol (1); coffee drinkers may differ in wealth, diet or exercise (1); the sample size and how participants were chosen affect reliability (1); a dose-response relationship would strengthen the case (1); a biological mechanism would be needed to support a causal claim (1); the study should be repeated independently and peer reviewed (1); conclusion: the evidence is suggestive but insufficient to claim coffee protects the liver (1).` },
    { q: 'Discuss the relative importance of genetic and lifestyle factors in determining whether a person develops cardiovascular disease.', marks: 6, command: 'Discuss', markScheme: `Any 6: inherited variants such as those causing familial hypercholesterolaemia strongly raise risk (1); most people\'s genetic risk is spread across many genes, each with a small effect (1); lifestyle factors such as smoking, diet and exercise have large, well-evidenced effects (1); lifestyle can be changed whereas genes cannot (1); the two interact, so a person with high genetic risk benefits most from a healthy lifestyle (1); environmental factors such as air pollution also contribute (1); evidence comes from large population studies comparing groups (1); conclusion: for most people lifestyle is the more modifiable factor, but genetic risk determines how much benefit a change brings (1).` },
  ]},
  /* ─────────────────────────────── B2.6 Treating disease */
  'B2.6': { name: 'How can we treat disease?', questions: [
    { q: 'State the difference between a medicine that treats symptoms and one that cures a disease.', marks: 2, command: 'State', markScheme: `• A medicine that treats symptoms reduces pain or discomfort but leaves the cause of the disease present (1)\n• A cure removes or destroys the cause of the disease, e.g. an antibiotic killing bacteria (1).` },
    { q: 'Explain why antibiotics are effective against bacteria but not against viruses.', marks: 3, command: 'Explain', markScheme: `• Antibiotics damage structures or processes found only in bacterial cells, e.g. the cell wall (1)\n• Viruses have no cell wall, cytoplasm or metabolism of their own (1)\n• Viruses replicate inside host cells, so a drug that killed them would also damage human cells (1).` },
    { q: 'Explain why a doctor should not prescribe antibiotics for a common cold.', marks: 3, command: 'Explain', markScheme: `• A cold is caused by a virus, so antibiotics will have no effect (1)\n• The patient would gain no benefit but may suffer side effects (1)\n• Unnecessary use increases the selection pressure for antibiotic-resistant bacteria (1).` },
    { q: 'Explain how antibiotic-resistant bacteria arise in a population.', marks: 4, command: 'Explain', markScheme: `• A random mutation in the DNA of a bacterium makes it resistant to the antibiotic (1)\n• When the antibiotic is used, non-resistant bacteria are killed (1)\n• The resistant bacterium survives and reproduces, passing on the resistance allele (1)\n• Over generations the proportion of resistant bacteria increases, so the antibiotic becomes less effective (1).` },
    { q: 'State two things patients can do to help slow the spread of antibiotic resistance.', marks: 2, command: 'State', markScheme: `Any 2 of: complete the full course of antibiotics even when feeling better (1); do not ask for antibiotics for viral illnesses (1); never use antibiotics prescribed for someone else or left over from before (1).` },
    { q: 'Explain why a patient should finish a course of antibiotics even after the symptoms have gone.', marks: 3, command: 'Explain', markScheme: `• Some bacteria survive after the symptoms disappear (1)\n• Stopping early allows these bacteria to multiply again (1)\n• The survivors are the least susceptible to the antibiotic, so resistant strains are selected for (1).` },
    { q: 'Describe how the effectiveness of two antibiotics against the same bacterium can be compared on an agar plate.', marks: 4, command: 'Describe', markScheme: `• Spread the bacterium evenly over a sterile agar plate using aseptic technique (1)\n• Place a disc of each antibiotic, and a control disc soaked in sterile water, on the agar (1)\n• Incubate at 25 °C for 24-48 hours (1)\n• Measure the diameter of the clear zone around each disc and calculate its area; the larger zone shows the more effective antibiotic (1).` },
    { q: 'A clear zone around an antibiotic disc has a radius of 7.0 mm. Calculate its cross-sectional area. Give your answer to the nearest whole number.', marks: 2, command: 'Calculate', markScheme: `• Area = πr² = 3.142 × 7.0 × 7.0 (1)\n• = 154 mm² (1).` },
    { q: 'Explain why the area of a clear zone, rather than its diameter, is used to compare antibiotics.', marks: 2, command: 'Explain', markScheme: `• Area is proportional to the square of the radius, so it reflects the full region in which bacteria were killed (1)\n• It makes the difference between two antibiotics clearer than comparing diameters (1).` },
    { q: 'State three ways in which cardiovascular disease can be treated or its risk reduced.', marks: 3, command: 'State', markScheme: `Any 3 of: lifestyle changes such as diet, exercise and stopping smoking (1); medicines such as statins (1); surgical insertion of a stent (1); coronary bypass surgery (1); a heart transplant or artificial heart (1).` },
    { q: 'Describe how a statin reduces the risk of cardiovascular disease.', marks: 3, command: 'Describe', markScheme: `• Statins reduce the amount of cholesterol produced by the liver (1)\n• This lowers the level of low-density lipoprotein cholesterol in the blood (1)\n• Less cholesterol is deposited in the coronary arteries, so plaques build up more slowly (1).` },
    { q: 'Describe two disadvantages of treating cardiovascular disease with statins.', marks: 4, command: 'Describe', markScheme: `Any 2, 2 marks each: they must be taken for life, and patients may forget doses so protection is lost (2); they can cause side effects such as muscle pain, liver damage or headaches (2); the effect is not immediate, so they do not help someone already having a heart attack (2); long-term prescribing to millions of people is expensive for the health service (2).` },
    { q: 'Describe how a stent treats a narrowed coronary artery.', marks: 3, command: 'Describe', markScheme: `• A stent is a wire mesh tube inserted into the narrowed artery (1)\n• It is expanded to push the artery wall open (1)\n• Blood flow to the heart muscle is restored, relieving symptoms and reducing the risk of a heart attack (1).` },
    { q: 'Compare the use of a stent with the use of statins to treat coronary heart disease.', marks: 4, command: 'Compare', markScheme: `• A stent gives an immediate improvement in blood flow, whereas statins act slowly over months or years (1)\n• A stent treats one blocked artery, whereas statins lower cholesterol throughout the whole circulation (1)\n• A stent requires surgery with risks of infection, bleeding and blood clots (1)\n• Statins avoid surgery but must be taken for life and may cause side effects (1).` },
    { q: 'Suggest two risks of inserting a stent.', marks: 2, command: 'Suggest', markScheme: `Any 2 of: infection from the surgery (1); a blood clot forming at the stent (thrombosis) (1); damage to the blood vessel during the procedure (1); the artery narrowing again over time (1).` },
    { q: 'Explain why lifestyle changes are often recommended before drugs or surgery for cardiovascular disease.', marks: 3, command: 'Explain', markScheme: `• Lifestyle changes such as stopping smoking, exercising and improving diet tackle the causes of the disease (1)\n• They carry no surgical risk and have no drug side effects (1)\n• They are much cheaper than drugs or surgery and improve health in other ways as well (1).` },
    { q: 'Suggest two reasons why a heart transplant is only used as a last resort.', marks: 4, command: 'Suggest', markScheme: `Any 2, 2 marks each: donor hearts are scarce so many patients wait a long time or die waiting (2); major surgery carries a high risk of death, bleeding and infection (2); the patient must take immunosuppressant drugs for life to prevent rejection, which leaves them vulnerable to infection (2).` },
    { q: 'Explain why a transplant patient must take immunosuppressant drugs.', marks: 3, command: 'Explain', markScheme: `• The donor organ carries antigens the recipient\'s immune system recognises as foreign (1)\n• Without treatment, lymphocytes would attack and destroy the transplanted organ (rejection) (1)\n• Immunosuppressants reduce this immune response so the organ survives (1).` },
    { q: 'Explain the drawback of taking immunosuppressant drugs for life.', marks: 2, command: 'Explain', markScheme: `• The immune system is less able to respond to pathogens (1)\n• So the patient is more likely to catch infections and finds them harder to fight off (1).` },
    { q: 'Describe how scientists find substances that might become new medicines.', marks: 3, command: 'Describe', markScheme: `• The genomes and proteins of the pathogen or host cell are studied to suggest a target (1)\n• Large libraries of substances are screened to find any that affect the target (1)\n• Promising substances are then chemically modified and tested further to improve them (1).` },
    { q: 'Explain why it is unlikely that a perfect medicine will be found during initial screening.', marks: 2, command: 'Explain', markScheme: `• A substance that affects the target may still be poorly absorbed, toxic or quickly broken down in the body (1)\n• So it must be modified and retested many times before it is suitable to use (1).` },
    { q: 'State the two main stages of testing a new medicine before it is made available.', marks: 2, command: 'State', markScheme: `• Preclinical testing (1)\n• Clinical testing / clinical trials (1).` },
    { q: 'Describe what happens during preclinical testing of a new medicine.', marks: 3, command: 'Describe', markScheme: `• The substance is tested on cultured human cells and tissues (1)\n• It is then tested on animals (1)\n• These tests check for toxicity and whether the substance is effective before it is given to people (1).` },
    { q: 'Describe the stages of clinical testing of a new medicine.', marks: 4, command: 'Describe', markScheme: `• The medicine is first given to a small number of healthy volunteers (1)\n• This tests for safety and side effects and finds a safe dose (1)\n• It is then given to patients who have the disease (1)\n• This tests both safety and effectiveness, and determines the optimum dose (1).` },
    { q: 'Explain why a new medicine is first tested on healthy volunteers rather than on patients.', marks: 2, command: 'Explain', markScheme: `• The main purpose of the first stage is to check the medicine is safe and find the side effects (1)\n• Healthy people are not already ill, so any harmful effects can be attributed to the medicine (1).` },
    { q: 'Define the term "placebo".', marks: 2, command: 'Define', markScheme: `• A substance that looks identical to the medicine but contains no active drug (1)\n• It is given to a control group so the effect of the medicine itself can be identified (1).` },
    { q: 'Explain the difference between a blind trial and a double-blind trial.', marks: 3, command: 'Explain', markScheme: `• In a blind trial the patients do not know whether they receive the medicine or the placebo (1)\n• In a double-blind trial neither the patients nor the doctors assessing them know (1)\n• A double-blind trial removes bias from the doctors\' judgement as well as the patients\' (1).` },
    { q: 'Explain why a double-blind trial gives more valid results than an open-label trial.', marks: 3, command: 'Explain', markScheme: `• Patients who know they are receiving a real drug may report feeling better even if it has no effect (1)\n• Doctors who know which group a patient is in may interpret symptoms more favourably (1)\n• Keeping both groups unaware removes both sources of bias, so any difference is due to the drug (1).` },
    { q: 'Suggest an ethical objection to giving a placebo to patients with a serious disease.', marks: 3, command: 'Suggest', markScheme: `• Patients in the placebo group receive no active treatment (1)\n• Their condition may worsen or they may die during the trial (1)\n• This has to be weighed against the benefit of knowing reliably whether the new medicine works (1).` },
    { q: 'Suggest why a trial should use a large number of patients rather than a few.', marks: 3, command: 'Suggest', markScheme: `• A large sample reduces the effect of individual variation between patients (1)\n• Rare side effects are more likely to be detected (1)\n• Any difference between the treatment and placebo groups is less likely to be due to chance (1).` },
    { q: 'Explain why the results of a clinical trial are published and peer reviewed before the medicine is licensed.', marks: 3, command: 'Explain', markScheme: `• Other scientists check the methods and the conclusions drawn from the data (1)\n• This detects errors, bias or exaggerated claims (1)\n• It gives doctors and regulators confidence that the medicine is safe and effective (1).` },
    { q: 'State two factors a doctor must consider when deciding whether to prescribe a particular treatment.', marks: 2, command: 'State', markScheme: `Any 2 of: how effective the treatment is likely to be for that patient (1); the risk of adverse reactions or side effects (1); the cost to the health service (1); the benefits and risks to other people, e.g. antibiotic resistance (1).` },
    { q: 'Explain what is meant by an "adverse reaction" to a medicine.', marks: 2, command: 'Explain', markScheme: `• An unwanted and harmful effect caused by the medicine (1)\n• It occurs in addition to the intended therapeutic effect, e.g. nausea, rash or liver damage (1).` },
    { q: 'Explain why radiotherapy and chemotherapy for cancer often cause severe side effects.', marks: 3, command: 'Explain', markScheme: `• These treatments target cells that are dividing rapidly (1)\n• They cannot distinguish cancer cells from healthy cells that also divide quickly, such as those in hair follicles, the gut lining and bone marrow (1)\n• Damage to these healthy cells causes hair loss, nausea and a weakened immune system (1).` },
    { q: 'Describe how monoclonal antibodies can be used to treat cancer.', marks: 4, command: 'Describe', markScheme: `• Monoclonal antibodies are produced that are specific to an antigen on the cancer cell (1)\n• The antibodies are injected into the patient\'s blood (1)\n• They bind to the cancer cells, tagging them for attack by white blood cells (1)\n• A radioactive or toxic substance can be attached to the antibody so it is delivered directly to the cancer cells (1).` },
    { q: 'Explain why monoclonal antibody treatment causes fewer side effects than conventional chemotherapy.', marks: 3, command: 'Explain', markScheme: `• The antibody binds only to the antigen found on the cancer cells (1)\n• So the drug or radiation is delivered to the tumour and not to healthy tissue (1)\n• Healthy dividing cells elsewhere in the body are left undamaged (1).` },
    { q: 'Suggest two reasons why monoclonal antibody treatments are expensive.', marks: 2, command: 'Suggest', markScheme: `Any 2 of: producing and culturing the antibody-producing cells is complex and slow (1); a different antibody must be developed for each cancer antigen (1); extensive clinical testing is needed for each new antibody (1); production must take place under strict sterile conditions (1).` },
    { q: 'Explain why preventing cardiovascular disease is generally better than treating it later.', marks: 4, command: 'Explain', markScheme: `• Prevention by lifestyle change stops plaques forming in the first place (1)\n• Damage to arteries and heart muscle, once it has happened, is often permanent (1)\n• Prevention avoids the risks of surgery and the side effects of long-term medication (1)\n• It is much cheaper for the health service than surgery or lifelong drug treatment (1).` },
    { q: 'Evaluate whether a health service should fund an expensive new cancer medicine that extends life by an average of three months.', marks: 6, command: 'Evaluate', markScheme: `Any 6: the medicine gives patients extra time with family and may improve quality of life (1); it may work much better in a subgroup of patients than the average suggests (1); funding new medicines encourages further research and development (1); however the money could treat many more patients if spent on other treatments (1); three months is a short extension and the side effects may reduce quality of life (1); the average hides wide variation between individuals (1); decisions must be consistent and not depend on where a patient lives (1); conclusion: a reasoned judgement, e.g. fund it for the subgroup who benefit most (1).` },
    { q: 'Discuss the benefits and risks of developing new medicines through animal testing.', marks: 6, command: 'Discuss', markScheme: `Any 6: animal testing shows how a substance behaves in a whole living body, which cultured cells cannot (1); it detects toxicity before humans are exposed, so lives are saved (1); it is a legal requirement before clinical trials in many countries (1); however animals may suffer or be killed during testing (1); animals differ physiologically from humans, so results do not always transfer (1); alternatives such as cell cultures and computer models are improving (1); some people hold that using animals in this way is always wrong (1); conclusion: a justified judgement referring to weighing animal welfare against human benefit (1).` },
  ]},
  /* ─────────────────────────────── B3.1 Photosynthesis */
  'B3.1': { name: 'What happens during photosynthesis?', questions: [
    { q: 'Write the word equation for photosynthesis.', marks: 2, command: 'State', markScheme: `• carbon dioxide + water → glucose + oxygen (1)\n• Light and chlorophyll shown as a requirement above the arrow (1).` },
    { q: 'Write the balanced symbol equation for photosynthesis.', marks: 2, command: 'State', markScheme: `• 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ (1)\n• Correctly balanced with light/chlorophyll indicated (1).` },
    { q: 'Explain why photosynthesis is described as an endothermic reaction.', marks: 2, command: 'Explain', markScheme: `• Energy is transferred from the surroundings to the reacting chemicals (1)\n• Light energy is absorbed and stored in the chemical bonds of glucose (1).` },
    { q: 'Describe the two main stages of photosynthesis.', marks: 4, command: 'Describe', markScheme: `• In the first stage, light energy absorbed by chlorophyll splits water molecules into hydrogen and oxygen (1)\n• Oxygen is released as a waste product (1)\n• The hydrogen is passed to the second stage (1)\n• In the second stage, hydrogen combines with carbon dioxide to make glucose (1).` },
    { q: 'State which stage of photosynthesis requires light and explain why.', marks: 2, command: 'State', markScheme: `• The first stage (1)\n• Light energy is needed to split the water molecules (1).` },
    { q: 'Name the green pigment that absorbs light for photosynthesis and state where it is found.', marks: 2, command: 'Name', markScheme: `• Chlorophyll (1)\n• In the chloroplasts of plant cells (1).` },
    { q: 'Explain how the structure of a chloroplast is related to its function.', marks: 3, command: 'Explain', markScheme: `• Chloroplasts contain many internal membranes holding chlorophyll, giving a large surface area for absorbing light (1)\n• They contain the enzymes needed to catalyse the reactions of photosynthesis (1)\n• They are found in large numbers in palisade cells near the top of the leaf, where light intensity is greatest (1).` },
    { q: 'State three uses a plant makes of the glucose produced in photosynthesis.', marks: 3, command: 'State', markScheme: `Any 3 of: used as the fuel for cellular respiration (1); converted to starch for storage (1); used to make cellulose for cell walls (1); converted to lipids for storage in seeds (1); combined with nitrate to make amino acids and proteins (1).` },
    { q: 'Explain why plants store glucose as starch rather than as glucose.', marks: 3, command: 'Explain', markScheme: `• Starch is insoluble so it does not affect the water potential of the cell (1)\n• Water therefore does not move into the cell by osmosis and burst it (1)\n• Starch is compact and can be broken back down into glucose when needed (1).` },
    { q: 'Describe how you would test a leaf for the presence of starch.', marks: 4, command: 'Describe', markScheme: `• Boil the leaf in water to kill it and break down the cell membranes (1)\n• Heat the leaf in ethanol using a water bath to remove the chlorophyll (1)\n• Rinse the leaf in water to soften it (1)\n• Add iodine solution: a blue-black colour shows starch is present (1).` },
    { q: 'Explain why ethanol is heated in a water bath rather than directly with a Bunsen burner in the starch test.', marks: 2, command: 'Explain', markScheme: `• Ethanol is highly flammable (1)\n• A naked flame could set the ethanol vapour alight (1).` },
    { q: 'A plant is kept in the dark for 48 hours before a starch test investigation. Explain why.', marks: 2, command: 'Explain', markScheme: `• It destarches the plant, as stored starch is used up in respiration (1)\n• So any starch found afterwards must have been made during the investigation (1).` },
    { q: 'A leaf on a plant is wrapped in foil for 24 hours and then tested for starch. Predict the result and explain it.', marks: 3, command: 'Explain', markScheme: `• The leaf stays orange-brown / no blue-black colour, so no starch is present (1)\n• Light could not reach the leaf (1)\n• Without light the first stage of photosynthesis cannot occur, so no glucose and no starch are made (1).` },
    { q: 'A leaf is enclosed in a flask containing potassium hydroxide solution for 24 hours. Explain why this leaf tests negative for starch.', marks: 3, command: 'Explain', markScheme: `• Potassium hydroxide absorbs carbon dioxide from the air in the flask (1)\n• Carbon dioxide is a reactant in the second stage of photosynthesis (1)\n• Without it no glucose, and therefore no starch, can be made (1).` },
    { q: 'Define the term "catalyst".', marks: 2, command: 'Define', markScheme: `• A substance that speeds up the rate of a chemical reaction (1)\n• Without being used up or changed in the reaction (1).` },
    { q: 'Explain why enzymes are described as biological catalysts.', marks: 2, command: 'Explain', markScheme: `• They are proteins made by living cells (1)\n• They speed up the chemical reactions of metabolism without being changed themselves (1).` },
    { q: 'Describe the lock and key model of enzyme action.', marks: 4, command: 'Describe', markScheme: `• The enzyme has a region called the active site with a specific shape (1)\n• Only a substrate with a complementary shape can fit into the active site, like a key in a lock (1)\n• The substrate binds to form an enzyme-substrate complex (1)\n• The reaction takes place and the products leave, freeing the active site for another substrate (1).` },
    { q: 'Explain why each enzyme catalyses only one reaction.', marks: 2, command: 'Explain', markScheme: `• The shape of the active site is complementary to only one substrate (1)\n• Other substrates cannot fit into the active site, so are not catalysed (1).` },
    { q: 'Explain the effect of increasing temperature from 10 °C to 40 °C on the rate of an enzyme-controlled reaction.', marks: 3, command: 'Explain', markScheme: `• The rate increases (1)\n• Enzyme and substrate molecules have more kinetic energy and move faster (1)\n• So there are more frequent successful collisions between substrate and active site (1).` },
    { q: 'Explain why the rate of an enzyme-controlled reaction falls sharply above about 45 °C.', marks: 3, command: 'Explain', markScheme: `• The high temperature makes the enzyme molecule vibrate, breaking the bonds holding its shape (1)\n• The active site changes shape, so the enzyme is denatured (1)\n• The substrate can no longer bind, so no enzyme-substrate complexes form and the reaction stops (1).` },
    { q: 'Explain why a denatured enzyme cannot recover when the temperature is lowered again.', marks: 2, command: 'Explain', markScheme: `• The bonds holding the enzyme\'s three-dimensional shape have been permanently broken (1)\n• The active site cannot reform its complementary shape (1).` },
    { q: 'Explain the effect of changing pH away from the optimum on enzyme activity.', marks: 3, command: 'Explain', markScheme: `• The rate of reaction decreases (1)\n• Extremes of pH break the bonds holding the enzyme\'s shape (1)\n• The active site is no longer complementary to the substrate, so the enzyme is denatured (1).` },
    { q: 'Explain why increasing substrate concentration increases the rate of reaction, but only up to a point.', marks: 4, command: 'Explain', markScheme: `• At low concentrations more substrate means more collisions with active sites, so the rate rises (1)\n• Eventually every active site is occupied at any moment (1)\n• The enzymes are the limiting factor and are working at their maximum rate (1)\n• Adding more substrate then has no further effect, so the graph levels off (1).` },
    { q: 'Describe how you would investigate the effect of pH on the rate at which amylase breaks down starch.', marks: 5, command: 'Describe', markScheme: `• Add amylase and starch solution to a series of buffer solutions of different pH (1)\n• Keep the temperature constant using a water bath (1)\n• At regular time intervals remove a drop of the mixture and add it to iodine solution on a spotting tile (1)\n• Record the time taken for the iodine to stop turning blue-black, showing all the starch has been broken down (1)\n• Calculate rate as 1 ÷ time, and repeat each pH to obtain a mean (1).` },
    { q: 'In an enzyme experiment the reaction is complete after 40 s. Calculate the rate of reaction in s⁻¹.', marks: 2, command: 'Calculate', markScheme: `• Rate = 1 ÷ time (1)\n• = 1 ÷ 40 = 0.025 s⁻¹ (1).` },
    { q: 'Define the term "limiting factor".', marks: 2, command: 'Define', markScheme: `• The factor that is in shortest supply and so restricts the rate of a process (1)\n• Increasing it increases the rate, while increasing any other factor has no effect (1).` },
    { q: 'Name three factors that can limit the rate of photosynthesis.', marks: 3, command: 'Name', markScheme: `• Light intensity (1)\n• Carbon dioxide concentration (1)\n• Temperature (1).` },
    { q: 'Explain the shape of a graph of rate of photosynthesis against light intensity, which rises then levels off.', marks: 4, command: 'Explain', markScheme: `• At low light intensity, light is the limiting factor (1)\n• As light intensity rises, more energy is available to split water, so the rate increases (1)\n• The graph then levels off because something else has become limiting (1)\n• This is carbon dioxide concentration or temperature (1).` },
    { q: 'Explain why the rate of photosynthesis does not continue to increase as temperature rises above about 40 °C.', marks: 3, command: 'Explain', markScheme: `• The reactions of photosynthesis are catalysed by enzymes (1)\n• At high temperatures the enzymes are denatured and their active sites change shape (1)\n• So the rate of photosynthesis falls rapidly (1).` },
    { q: 'Describe how you would investigate the effect of light intensity on the rate of photosynthesis using pondweed.', marks: 5, command: 'Describe', markScheme: `• Place a piece of pondweed in a beaker of sodium hydrogencarbonate solution to supply carbon dioxide (1)\n• Place a lamp a measured distance from the beaker (1)\n• Leave the pondweed to acclimatise, then count the bubbles of oxygen released in one minute, or collect and measure the gas (1)\n• Repeat at a range of distances from the lamp (1)\n• Keep the temperature constant using a heat shield or water bath, and repeat each distance to find a mean (1).` },
    { q: 'Explain why a glass tank of water is placed between the lamp and the pondweed in a photosynthesis investigation.', marks: 2, command: 'Explain', markScheme: `• It absorbs heat from the lamp (1)\n• So temperature stays constant and only light intensity is changed, keeping the investigation valid (1).` },
    { q: 'State the inverse square law relating light intensity to distance from a light source.', marks: 2, command: 'State', markScheme: `• Light intensity is inversely proportional to the square of the distance from the source (1)\n• light intensity ∝ 1 ÷ d² (1).` },
    { q: 'A lamp is moved from 10 cm to 20 cm from a plant. Calculate how many times smaller the light intensity becomes.', marks: 2, command: 'Calculate', markScheme: `• Distance has doubled, so intensity falls by a factor of 2² (1)\n• Intensity is 4 times smaller (1).` },
    { q: 'A lamp is placed 25 cm from pondweed. Calculate the relative light intensity using 1 ÷ d². Give your answer to 4 decimal places.', marks: 2, command: 'Calculate', markScheme: `• 1 ÷ 25² = 1 ÷ 625 (1)\n• = 0.0016 (arbitrary units) (1).` },
    { q: 'Explain why moving a lamp twice as far away reduces the rate of photosynthesis by more than half.', marks: 3, command: 'Explain', markScheme: `• Light intensity follows the inverse square law (1)\n• Doubling the distance reduces the intensity to one quarter, not one half (1)\n• While light is the limiting factor, the rate of photosynthesis falls in proportion to the intensity (1).` },
    { q: 'A pondweed releases 72 bubbles in 3 minutes. Calculate the rate in bubbles per minute.', marks: 2, command: 'Calculate', markScheme: `• Rate = 72 ÷ 3 (1)\n• = 24 bubbles per minute (1).` },
    { q: 'Suggest two reasons why counting bubbles is a less accurate measure of photosynthesis than collecting the gas in a syringe.', marks: 4, command: 'Suggest', markScheme: `Any 2, 2 marks each: bubbles vary in size, so equal numbers do not represent equal volumes of gas (2); bubbles may be produced too quickly to count accurately by eye (2); some bubbles may stick to the plant or the sides of the tube and not be counted (2).` },
    { q: 'Explain why a greenhouse grower might burn a paraffin heater inside the greenhouse in winter.', marks: 4, command: 'Explain', markScheme: `• Burning paraffin releases carbon dioxide and heat (1)\n• Both carbon dioxide concentration and temperature can be limiting factors in winter (1)\n• Raising them increases the rate of photosynthesis (1)\n• So the plants make more glucose and grow faster, increasing the yield (1).` },
    { q: 'A greenhouse grower increases carbon dioxide concentration but the rate of photosynthesis does not change. Suggest and explain two reasons.', marks: 4, command: 'Suggest', markScheme: `Any 2, 2 marks each: light intensity is the limiting factor, so extra carbon dioxide cannot be used (2); the temperature is too low, so enzymes work slowly and cannot use the extra carbon dioxide (2); the temperature is so high that enzymes have been denatured (2).` },
    { q: 'Discuss whether it is worthwhile for a commercial grower to control light, temperature and carbon dioxide in a greenhouse.', marks: 6, command: 'Discuss', markScheme: `Any 6: controlling all three removes the limiting factors so the rate of photosynthesis is as high as possible (1); plants grow faster and produce a larger crop (1); crops can be grown out of season and sold at higher prices (1); however lighting and heating use large amounts of energy (1); this is expensive and increases carbon dioxide emissions from fuel use (1); there is an optimum beyond which extra input gives little extra yield (1); the grower must compare the extra income with the extra cost (1); conclusion: worthwhile only if the increase in crop value exceeds the running costs (1).` },
  ]},
  /* ─────────────────────────────── B3.2 Producer substances and transport */
  'B3.2': { name: 'How do producers get the substances they need?', questions: [
    { q: 'Name four substances that a plant must take in from its environment.', marks: 2, command: 'Name', markScheme: `• Carbon dioxide and water (1)\n• Oxygen and mineral ions such as nitrate (1).` },
    { q: 'Define the term "diffusion".', marks: 2, command: 'Define', markScheme: `• The net movement of particles from a region of higher concentration to a region of lower concentration (1)\n• Down a concentration gradient, and it is a passive process requiring no energy from the cell (1).` },
    { q: 'Define the term "osmosis".', marks: 3, command: 'Define', markScheme: `• The movement of water molecules (1)\n• From a dilute solution to a concentrated solution (1)\n• Through a partially permeable membrane (1).` },
    { q: 'Define the term "active transport".', marks: 3, command: 'Define', markScheme: `• The movement of substances across a cell membrane against a concentration gradient (1)\n• From a lower to a higher concentration (1)\n• Using energy released by respiration, transferred by ATP (1).` },
    { q: 'Compare diffusion and active transport.', marks: 4, command: 'Compare', markScheme: `• Diffusion moves substances down a concentration gradient; active transport moves them against it (1)\n• Diffusion is passive; active transport requires energy from respiration (1)\n• Diffusion needs no carrier proteins; active transport uses specific carrier proteins in the membrane (1)\n• Diffusion continues until concentrations are equal; active transport can continue beyond this point (1).` },
    { q: 'Explain how carbon dioxide reaches the photosynthesising cells inside a leaf.', marks: 3, command: 'Explain', markScheme: `• Carbon dioxide is used up in photosynthesis, so its concentration inside the leaf is lower than in the air (1)\n• It diffuses into the leaf through the stomata down this concentration gradient (1)\n• It then diffuses through the air spaces and across the cell membranes into the mesophyll cells (1).` },
    { q: 'Explain why a single-celled alga does not need a transport system.', marks: 3, command: 'Explain', markScheme: `• It has a large surface area to volume ratio (1)\n• Every part of the cell is close to the surface, so diffusion distances are short (1)\n• Diffusion alone is fast enough to supply its needs (1).` },
    { q: 'Explain why a cell membrane is described as partially permeable.', marks: 2, command: 'Explain', markScheme: `• It allows some substances, such as water and small gas molecules, to pass through freely (1)\n• But it does not allow others, such as nitrate ions and large molecules, to pass without a carrier protein (1).` },
    { q: 'Explain why plants absorb nitrate ions by active transport rather than diffusion.', marks: 3, command: 'Explain', markScheme: `• Nitrate concentration in the soil water is usually lower than inside the root hair cell (1)\n• So diffusion would move nitrate out of the cell, not into it (1)\n• Active transport uses energy from respiration to move nitrate against the concentration gradient (1).` },
    { q: 'Explain why a plant needs nitrate ions.', marks: 2, command: 'Explain', markScheme: `• Nitrate is used with glucose to make amino acids (1)\n• Amino acids are joined to form proteins, needed for growth and for enzymes (1).` },
    { q: 'Describe a symptom of nitrate deficiency in a plant and explain why it occurs.', marks: 3, command: 'Describe and explain', markScheme: `• The plant shows stunted growth and older leaves turn yellow (1)\n• Without nitrate the plant cannot make enough amino acids and proteins (1)\n• So it cannot make new cells or enough chlorophyll and enzymes (1).` },
    { q: 'Explain how the structure of a root hair cell is adapted for absorbing water.', marks: 3, command: 'Explain', markScheme: `• The long, thin extension gives a very large surface area in contact with soil water (1)\n• This increases the rate of osmosis into the cell (1)\n• It has a thin cell wall and membrane, giving a short diffusion pathway (1).` },
    { q: 'Explain why root hair cells contain many mitochondria.', marks: 2, command: 'Explain', markScheme: `• Mitochondria are the site of aerobic respiration, which releases energy as ATP (1)\n• This energy is needed for the active transport of mineral ions into the cell (1).` },
    { q: 'Explain why plant roots in waterlogged soil take up fewer mineral ions.', marks: 3, command: 'Explain', markScheme: `• Waterlogged soil contains little oxygen (1)\n• So the root cells cannot carry out aerobic respiration and make much ATP (1)\n• Active transport of mineral ions slows or stops without this energy (1).` },
    { q: 'Describe how you would investigate the effect of sugar concentration on osmosis using potato cylinders.', marks: 5, command: 'Describe', markScheme: `• Cut potato cylinders of equal length using a cork borer and blot them dry (1)\n• Measure and record the initial mass of each cylinder (1)\n• Place one cylinder into each of a range of sugar solution concentrations, including distilled water (1)\n• Leave for a set time, then remove, blot dry and reweigh each cylinder (1)\n• Calculate the percentage change in mass for each concentration and repeat to find a mean (1).` },
    { q: 'A potato cylinder of mass 4.0 g increases to 4.6 g in distilled water. Calculate the percentage change in mass.', marks: 3, command: 'Calculate', markScheme: `• Change in mass = 4.6 − 4.0 = 0.6 g (1)\n• Percentage change = (0.6 ÷ 4.0) × 100 (1)\n• = +15 % (1).` },
    { q: 'A potato cylinder of mass 5.0 g falls to 4.2 g in a concentrated sugar solution. Calculate the percentage change in mass.', marks: 2, command: 'Calculate', markScheme: `• (4.2 − 5.0) ÷ 5.0 × 100 (1)\n• = −16 % (1).` },
    { q: 'Explain why a potato cylinder gains mass in distilled water.', marks: 3, command: 'Explain', markScheme: `• The solution outside is more dilute than the cell contents (1)\n• Water moves into the cells by osmosis through the partially permeable membranes (1)\n• The cells become turgid, so the cylinder gains mass (1).` },
    { q: 'Explain why percentage change in mass, rather than change in mass, is used to compare potato cylinders.', marks: 2, command: 'Explain', markScheme: `• The cylinders do not all have exactly the same starting mass (1)\n• Percentage change allows a fair comparison between cylinders of different initial mass (1).` },
    { q: 'Explain why potato cylinders must be blotted dry before being reweighed.', marks: 2, command: 'Explain', markScheme: `• Surface liquid would add to the measured mass (1)\n• This would make the mass change appear larger than the water actually moved by osmosis (1).` },
    { q: 'Explain what happens to an animal cell placed in pure water.', marks: 3, command: 'Explain', markScheme: `• Water enters the cell by osmosis because the cytoplasm is more concentrated (1)\n• The cell swells as it has no cell wall to resist the pressure (1)\n• It may burst (lysis) (1).` },
    { q: 'Explain why a plant cell placed in pure water does not burst.', marks: 2, command: 'Explain', markScheme: `• The cellulose cell wall is strong and inelastic (1)\n• It resists further expansion once the cell is turgid, preventing the cell from bursting (1).` },
    { q: 'Name the tissue that transports water in a plant and state the direction of flow.', marks: 2, command: 'Name', markScheme: `• Xylem (1)\n• Water moves upwards from the roots to the leaves (1).` },
    { q: 'Explain how the structure of xylem is adapted to its function.', marks: 4, command: 'Explain', markScheme: `• Xylem vessels are made of dead cells with no end walls, forming continuous hollow tubes (1)\n• There is no cytoplasm, so water flows through with little resistance (1)\n• The walls are strengthened with lignin (1)\n• This supports the plant and stops the vessels collapsing under tension (1).` },
    { q: 'Explain how the structure of phloem is adapted to its function.', marks: 4, command: 'Explain', markScheme: `• Phloem is made of living cells joined end to end (1)\n• The end walls are perforated to form sieve plates, allowing solution to pass through (1)\n• Companion cells alongside contain many mitochondria (1)\n• These supply the ATP needed for loading sugars into the phloem by active transport (1).` },
    { q: 'Define the term "transpiration".', marks: 2, command: 'Define', markScheme: `• The evaporation of water from the surfaces of cells inside the leaf (1)\n• Followed by its diffusion out of the leaf through the stomata (1).` },
    { q: 'Define the term "translocation".', marks: 2, command: 'Define', markScheme: `• The movement of dissolved sugars through the phloem (1)\n• From photosynthetic tissues such as leaves to non-photosynthetic tissues such as roots, fruits and growing points (1).` },
    { q: 'Describe how sugars are moved along the phloem.', marks: 3, command: 'Describe', markScheme: `• Sugars are loaded into the phloem by active transport (1)\n• This makes the solution in the phloem concentrated, so water moves in from the xylem by osmosis (1)\n• The incoming water pushes the solution along the tube to where sugars are needed (1).` },
    { q: 'Describe the function of a stoma and the guard cells around it.', marks: 3, command: 'Describe', markScheme: `• A stoma is a pore, mainly on the lower surface of a leaf (1)\n• It allows carbon dioxide in and oxygen and water vapour out (1)\n• The two guard cells change shape to open and close the pore, controlling water loss (1).` },
    { q: 'Explain why most stomata are found on the lower surface of a leaf.', marks: 2, command: 'Explain', markScheme: `• The lower surface is shaded and cooler than the upper surface (1)\n• So less water evaporates from the stomata, reducing water loss (1).` },
    { q: 'Explain why a plant closes its stomata when short of water, and state the disadvantage of doing so.', marks: 3, command: 'Explain', markScheme: `• Closing the stomata prevents water vapour diffusing out, so the plant does not wilt (1)\n• However carbon dioxide can no longer diffuse into the leaf (1)\n• So the rate of photosynthesis falls and less glucose is made (1).` },
    { q: 'Describe how you could use a light microscope to observe stomata on a leaf.', marks: 4, command: 'Describe', markScheme: `• Paint two thin layers of clear nail varnish onto the lower surface of the leaf and allow to dry (1)\n• Place clear tape over the varnish, peel it off and stick it to a microscope slide (1)\n• Focus on low power first, then change to a higher power objective (1)\n• Count the stomata visible in the field of view (1).` },
    { q: 'Describe how a potometer is used to measure the rate of water uptake by a shoot.', marks: 4, command: 'Describe', markScheme: `• Cut the shoot under water and fit it into the potometer, ensuring no air bubbles enter (1)\n• Introduce a single air bubble into the capillary tube (1)\n• Measure the distance the bubble moves along the scale in a set time (1)\n• Repeat under the same conditions and calculate a mean rate (1).` },
    { q: 'Explain why a potometer measures water uptake rather than transpiration directly.', marks: 2, command: 'Explain', markScheme: `• Not all the water taken up is lost by transpiration (1)\n• A small amount is used in photosynthesis and retained in the cells (1).` },
    { q: 'Explain the effect of increasing air movement on the rate of transpiration.', marks: 3, command: 'Explain', markScheme: `• Moving air removes water vapour from around the stomata (1)\n• This maintains a steep concentration gradient between the inside of the leaf and the air (1)\n• So water vapour diffuses out faster and the rate of transpiration increases (1).` },
    { q: 'Explain the effect of increasing temperature on the rate of transpiration.', marks: 3, command: 'Explain', markScheme: `• Water molecules gain kinetic energy, so evaporation from the cell surfaces is faster (1)\n• Water vapour molecules also diffuse out through the stomata more quickly (1)\n• So the rate of transpiration increases (1).` },
    { q: 'Explain why the rate of water uptake increases when light intensity increases.', marks: 3, command: 'Explain', markScheme: `• Higher light intensity causes the stomata to open wider (1)\n• More water vapour can diffuse out through the open stomata (1)\n• The plant also photosynthesises faster, increasing its demand for water (1).` },
    { q: 'Explain the effect of high humidity on the rate of transpiration.', marks: 3, command: 'Explain', markScheme: `• Humid air already contains a high concentration of water vapour (1)\n• This reduces the concentration gradient between the air spaces in the leaf and the air outside (1)\n• So water vapour diffuses out more slowly and transpiration decreases (1).` },
    { q: 'In a potometer investigation an air bubble moves 60 mm in 4 minutes. Calculate the rate of water uptake in mm per minute.', marks: 2, command: 'Calculate', markScheme: `• Rate = 60 ÷ 4 (1)\n• = 15 mm per minute (1).` },
    { q: 'Explain how the adaptations of a cactus reduce water loss while still allowing photosynthesis.', marks: 6, command: 'Explain', markScheme: `Any 6: leaves are reduced to spines, giving a very small surface area for evaporation (1); the stem is green and photosynthesises instead (1); a thick waxy cuticle reduces evaporation from the surface (1); few stomata, so less water vapour diffuses out (1); stomata are sunken in pits, trapping humid air and reducing the concentration gradient (1); stomata open at night when it is cooler, reducing evaporation (1); a wide shallow root system absorbs water quickly after rain (1); water is stored in the fleshy stem for use between rainfalls (1).` },
  ]},
  /* ─────────────────────────────── B3.3 Interdependence in ecosystems */
  'B3.3': { name: 'How are organisms in an ecosystem interdependent?', questions: [
    { q: 'Define the term "ecosystem".', marks: 2, command: 'Define', markScheme: `• All the organisms living in a particular area (the community) (1)\n• Together with the non-living (abiotic) parts of their environment, and the interactions between them (1).` },
    { q: 'Describe the levels of organisation in an ecosystem, from an individual organism upwards.', marks: 4, command: 'Describe', markScheme: `• An individual organism is a single living thing (1)\n• A population is all the organisms of one species living in an area (1)\n• A community is all the populations of different species living in that area (1)\n• An ecosystem is the community together with the abiotic environment (1).` },
    { q: 'Define the term "producer" and give an example.', marks: 2, command: 'Define', markScheme: `• An organism that makes its own food by photosynthesis (1)\n• For example a green plant or an alga (1).` },
    { q: 'Explain why photosynthetic organisms are described as the main producers of biomass for life on Earth.', marks: 3, command: 'Explain', markScheme: `• They convert carbon dioxide and water into glucose using light energy (1)\n• This glucose is used to make all the other organic molecules that form their biomass (1)\n• All consumers obtain their biomass, directly or indirectly, by eating producers (1).` },
    { q: 'Name the small molecules that carbohydrates, lipids and proteins are built from.', marks: 3, command: 'Name', markScheme: `• Carbohydrates are built from sugars such as glucose (1)\n• Lipids are built from fatty acids and glycerol (1)\n• Proteins are built from amino acids (1).` },
    { q: 'Explain why a consumer must digest the biomass it eats.', marks: 3, command: 'Explain', markScheme: `• The large molecules in food are insoluble and too big to be absorbed (1)\n• Digestion breaks them down into small soluble molecules such as sugars and amino acids (1)\n• These can be absorbed into the blood and used to build the consumer\'s own biomass (1).` },
    { q: 'Describe the test for starch and the positive result.', marks: 2, command: 'Describe', markScheme: `• Add iodine solution to the sample (1)\n• It changes from orange-brown to blue-black if starch is present (1).` },
    { q: 'Describe the test for a reducing sugar such as glucose.', marks: 3, command: 'Describe', markScheme: `• Add Benedict\'s solution to the sample (1)\n• Heat in a water bath at about 80 °C for a few minutes (1)\n• A colour change from blue to green, yellow, orange or brick red shows reducing sugar is present (1).` },
    { q: 'Describe the test for protein and the positive result.', marks: 2, command: 'Describe', markScheme: `• Add biuret solution to the sample (1)\n• A colour change from blue to purple/lilac shows protein is present (1).` },
    { q: 'Describe the emulsion test for lipids.', marks: 3, command: 'Describe', markScheme: `• Add ethanol to the sample and shake to dissolve any lipid (1)\n• Pour the mixture into water in a clean test tube (1)\n• A cloudy white emulsion shows lipid is present (1).` },
    { q: 'Describe how you could investigate the breakdown of starch into sugars by amylase.', marks: 4, command: 'Describe', markScheme: `• Mix amylase with starch solution and keep at a constant temperature (1)\n• At regular intervals test a drop with iodine solution on a spotting tile (1)\n• Also test the mixture with a glucose test strip or Benedict\'s solution (1)\n• The iodine stops turning blue-black as starch disappears while the sugar test becomes positive (1).` },
    { q: 'Explain what a food web shows that a food chain does not.', marks: 3, command: 'Explain', markScheme: `• A food web shows several interconnected food chains in a community (1)\n• It shows that most consumers eat more than one type of food and are eaten by more than one predator (1)\n• So it shows how the populations in the community are interdependent (1).` },
    { q: 'Explain why a food web is described as a model.', marks: 2, command: 'Explain', markScheme: `• It is a simplified representation of the real feeding relationships (1)\n• It is used to explain interdependence and to predict the effects of change (1).` },
    { q: 'State two limitations of a food web as a model.', marks: 2, command: 'State', markScheme: `Any 2 of: it does not show the size of each population (1); it does not show how much biomass or energy is transferred (1); it does not show seasonal or age-related changes in diet (1); decomposers are often left out (1).` },
    { q: 'In a food web, the number of foxes falls sharply. Predict and explain the effect on the rabbit population.', marks: 3, command: 'Explain', markScheme: `• The rabbit population would increase (1)\n• Fewer rabbits are eaten because there are fewer predators (1)\n• The increase would eventually be limited by competition for food or by other predators (1).` },
    { q: 'Explain why removing one species from a food web can affect many other populations.', marks: 3, command: 'Explain', markScheme: `• The species is linked to several others as predator, prey or competitor (1)\n• Its prey would increase and its predators would decrease or switch to other food (1)\n• These changes then pass on through the web, affecting populations not directly linked to it (1).` },
    { q: 'Define the term "interdependence".', marks: 2, command: 'Define', markScheme: `• Organisms in a community rely on one another to survive (1)\n• For food, shelter, pollination, seed dispersal or the removal of waste (1).` },
    { q: 'State four resources that plants compete for.', marks: 2, command: 'State', markScheme: `• Light and water (1)\n• Space and mineral ions from the soil (1).` },
    { q: 'State four resources that animals compete for.', marks: 2, command: 'State', markScheme: `• Food and water (1)\n• Territory/shelter and mates (1).` },
    { q: 'Explain the importance of competition in a community.', marks: 3, command: 'Explain', markScheme: `• Resources are limited, so not every individual can obtain enough to survive and reproduce (1)\n• Better adapted individuals obtain more resources and are more likely to reproduce (1)\n• Competition therefore limits population sizes and drives natural selection (1).` },
    { q: 'Explain why a plant that flowers early in spring in a woodland may be at an advantage.', marks: 3, command: 'Explain', markScheme: `• It grows and flowers before the trees are in full leaf (1)\n• So it receives more light for photosynthesis, with less competition (1)\n• It can make more glucose and produce seeds before it is shaded out (1).` },
    { q: 'Define the term "trophic level".', marks: 2, command: 'Define', markScheme: `• A feeding level in a food chain (1)\n• For example producers are level 1, primary consumers level 2 and secondary consumers level 3 (1).` },
    { q: 'Describe what a pyramid of biomass represents.', marks: 3, command: 'Describe', markScheme: `• Each bar represents the total dry mass of organisms at one trophic level (1)\n• The width of the bar is proportional to the biomass (1)\n• Producers form the bottom bar, with each level above being narrower (1).` },
    { q: 'Explain why a pyramid of biomass almost always narrows towards the top.', marks: 3, command: 'Explain', markScheme: `• Not all of the biomass eaten is converted into the consumer\'s own biomass (1)\n• Some is lost in faeces, urine and as carbon dioxide and water from respiration (1)\n• So less biomass is available at each successive trophic level (1).` },
    { q: 'State three ways in which biomass is lost between trophic levels.', marks: 3, command: 'State', markScheme: `• Not all of the organism is eaten, e.g. bones, roots (1)\n• Indigestible material is egested as faeces, and waste is excreted as urine (1)\n• Glucose is used in respiration, releasing carbon dioxide and water (1).` },
    { q: 'A trophic level contains 8000 kJ of biomass and the level above contains 720 kJ. Calculate the percentage efficiency of the transfer.', marks: 2, command: 'Calculate', markScheme: `• (720 ÷ 8000) × 100 (1)\n• = 9 % (1).` },
    { q: 'Producers store 40 000 kJ m⁻² and the primary consumers store 3600 kJ m⁻². Calculate the biomass lost between these levels and express it as a percentage.', marks: 3, command: 'Calculate', markScheme: `• Biomass lost = 40 000 − 3600 = 36 400 kJ m⁻² (1)\n• (36 400 ÷ 40 000) × 100 (1)\n• = 91 % (1).` },
    { q: 'Explain why food chains rarely have more than four or five trophic levels.', marks: 3, command: 'Explain', markScheme: `• Only about 10 % of the biomass is transferred at each level (1)\n• After several levels there is too little biomass left to support another population (1)\n• There would not be enough food for a predator to gain more energy than it uses hunting (1).` },
    { q: 'Explain why there are usually fewer organisms at higher trophic levels.', marks: 3, command: 'Explain', markScheme: `• Less biomass is available at each successive level (1)\n• Predators tend to be larger individuals, so each needs a large amount of food (1)\n• Only a small number of individuals can therefore be supported (1).` },
    { q: 'Explain why eating plants rather than meat can feed more people from the same area of land.', marks: 4, command: 'Explain', markScheme: `• Eating plants makes humans primary consumers rather than secondary consumers (1)\n• Fewer biomass transfers take place between the crop and the human (1)\n• Less biomass is lost in faeces, urine and respiration by farm animals (1)\n• So more of the biomass produced by the crop reaches people (1).` },
    { q: 'Name two substances that cycle between the biotic and abiotic parts of an ecosystem.', marks: 2, command: 'Name', markScheme: `• Carbon (1)\n• Water (1).` },
    { q: 'Describe how carbon is removed from and returned to the atmosphere in the carbon cycle.', marks: 4, command: 'Describe', markScheme: `• Carbon dioxide is removed from the air by photosynthesis in producers (1)\n• Carbon passes along food chains as biomass when organisms are eaten (1)\n• Respiration by producers, consumers and decomposers returns carbon dioxide to the air (1)\n• Combustion of wood and fossil fuels also returns carbon dioxide to the air (1).` },
    { q: 'Describe the main processes of the water cycle.', marks: 4, command: 'Describe', markScheme: `• Water evaporates from oceans, lakes and land, and is lost from plants by transpiration (1)\n• Water vapour cools and condenses to form clouds (1)\n• It returns to the ground as precipitation such as rain or snow (1)\n• It then flows through streams and rivers, or drains through the soil, back to the sea (1).` },
    { q: 'Explain why the cycling of carbon is important to living organisms.', marks: 3, command: 'Explain', markScheme: `• Carbon is needed to build carbohydrates, lipids and proteins in all living things (1)\n• The supply of carbon on Earth is fixed and is not replaced from outside (1)\n• Cycling releases carbon locked in dead organisms so it can be reused by producers (1).` },
    { q: 'Explain the role of microorganisms in the cycling of substances through an ecosystem.', marks: 4, command: 'Explain', markScheme: `• Decomposers such as bacteria and fungi feed on dead organisms and waste (1)\n• They release enzymes onto the material, digesting it outside their cells (extracellular digestion) (1)\n• They absorb the soluble products and respire them, releasing carbon dioxide (1)\n• Mineral ions such as nitrate are released back into the soil for plants to absorb (1).` },
    { q: 'Describe how you could show that a microorganism releases an extracellular enzyme.', marks: 4, command: 'Describe', markScheme: `• Culture the microorganism on an agar plate containing starch, using aseptic technique (1)\n• Incubate the plate to allow the colonies to grow (1)\n• Flood the plate with iodine solution (1)\n• A clear zone around the colony, where the agar does not turn blue-black, shows starch has been digested by an enzyme released from the cells (1).` },
    { q: 'Explain the effect of increasing temperature on the rate of decomposition.', marks: 4, command: 'Explain', markScheme: `• Decomposition is catalysed by enzymes released by microorganisms (1)\n• Warmth increases the rate of enzyme-controlled reactions and microbial growth, so decay speeds up (1)\n• Above about 40 °C the enzymes begin to denature (1)\n• So the rate falls sharply at high temperatures (1).` },
    { q: 'Explain why decomposition is slow in a waterlogged, oxygen-poor soil.', marks: 3, command: 'Explain', markScheme: `• Most decomposers respire aerobically and need oxygen (1)\n• Without oxygen they cannot release enough energy to grow and reproduce quickly (1)\n• Only anaerobic decomposers are active, and they work more slowly (1).` },
    { q: 'Explain why landfill sites release methane and why this matters.', marks: 4, command: 'Explain', markScheme: `• Waste buried in landfill is compacted so little oxygen is present (1)\n• Anaerobic decomposition takes place instead of aerobic decomposition (1)\n• Anaerobic decomposers produce methane rather than carbon dioxide (1)\n• Methane is a much stronger greenhouse gas than carbon dioxide, so it contributes more to global warming per molecule (1).` },
    { q: 'A 250 g sample of leaf litter decays to 90 g over 12 weeks. Calculate the percentage of mass lost and the mean rate of decay in g per week.', marks: 4, command: 'Calculate', markScheme: `• Mass lost = 250 − 90 = 160 g (1)\n• Percentage lost = (160 ÷ 250) × 100 = 64 % (1)\n• Rate = 160 ÷ 12 (1)\n• = 13.3 g per week (1).` },
  ]},
  /* ─────────────────────────────── B3.4 Populations and ecosystem conditions */
  'B3.4': { name: 'How are populations affected by conditions in an ecosystem?', questions: [
    { q: 'Define the term "population".', marks: 2, command: 'Define', markScheme: `• All the organisms of the same species (1)\n• Living in the same area at the same time (1).` },
    { q: 'Explain the difference between an abiotic and a biotic factor.', marks: 2, command: 'Explain', markScheme: `• An abiotic factor is a non-living condition of the environment, e.g. temperature or light intensity (1)\n• A biotic factor involves other living organisms, e.g. predation, competition or disease (1).` },
    { q: 'State four abiotic factors that affect the distribution of organisms.', marks: 4, command: 'State', markScheme: `Any 4 of: temperature; light intensity; soil moisture/water availability; soil pH; mineral ion content of soil; oxygen concentration in water; wind intensity (1 each).` },
    { q: 'State three biotic factors that can affect the size of a population.', marks: 3, command: 'State', markScheme: `Any 3 of: availability of food; the number of predators; competition from other species; new pathogens causing disease (1 each).` },
    { q: 'Explain how a fall in soil moisture could reduce the population of a plant species.', marks: 3, command: 'Explain', markScheme: `• Less water is available to be absorbed by the roots (1)\n• The plants wilt and the rate of photosynthesis falls because stomata close (1)\n• Growth and reproduction are reduced, so fewer plants survive and the population falls (1).` },
    { q: 'Explain how the introduction of a new predator can change several populations in a community.', marks: 4, command: 'Explain', markScheme: `• The prey population falls because more individuals are eaten (1)\n• Species that compete with that prey may increase, as more resources become available (1)\n• Predators that already ate that prey have less food, so their numbers fall (1)\n• The changes pass through the food web, affecting populations not directly linked to the new predator (1).` },
    { q: 'Explain how the introduction of a new pathogen can affect a population that has never met it before.', marks: 3, command: 'Explain', markScheme: `• The population has no resistance or immunity to the pathogen (1)\n• Many individuals become infected and die, so the population falls rapidly (1)\n• Any individuals with a genetic variant giving resistance survive and reproduce (1).` },
    { q: 'Define the term "bioaccumulation".', marks: 2, command: 'Define', markScheme: `• The build-up of a substance, usually a toxic one, inside an organism (1)\n• Because it is taken in faster than it can be broken down or excreted (1).` },
    { q: 'Explain why a pesticide reaches its highest concentration in the top predator of a food chain.', marks: 4, command: 'Explain', markScheme: `• The pesticide is absorbed by organisms at the bottom of the food chain (1)\n• It is not broken down or excreted, so it stays in their tissues (1)\n• Each consumer eats many of the organisms below it, so the pesticide accumulates in its body (1)\n• The concentration therefore increases at each trophic level, being highest in the top predator (1).` },
    { q: 'Suggest why the use of DDT caused the eggshells of birds of prey to become thin.', marks: 3, command: 'Suggest', markScheme: `• DDT was sprayed on crops and entered food chains (1)\n• It bioaccumulated, reaching its highest concentration in the birds of prey at the top of the chain (1)\n• At this concentration it interfered with the birds\' metabolism, so the shells formed were too thin (1).` },
    { q: 'Describe how fertiliser run-off causes eutrophication of a river.', marks: 5, command: 'Describe', markScheme: `• Rain washes nitrate fertiliser off fields into the river (1)\n• The extra nitrate causes algae to grow rapidly, forming an algal bloom at the surface (1)\n• The bloom blocks light from reaching plants below, so they die (1)\n• Decomposers multiply as they feed on the dead plants and algae, and respire aerobically (1)\n• The oxygen concentration in the water falls, so fish and other aquatic animals suffocate and die (1).` },
    { q: 'Suggest two ways a farmer could reduce the risk of eutrophication.', marks: 4, command: 'Suggest', markScheme: `Any 2, 2 marks each: apply only the amount of fertiliser the crop needs, so less is left to be washed away (2); avoid spreading fertiliser just before heavy rain or on waterlogged soil (2); leave an unfertilised buffer strip of vegetation next to watercourses to absorb run-off (2).` },
    { q: 'Explain why eutrophication is described as an unintended consequence of human activity.', marks: 2, command: 'Explain', markScheme: `• Fertiliser is used with the intention of increasing crop yield (1)\n• The damage to river ecosystems is an unplanned side effect that was not foreseen when the practice began (1).` },
    { q: 'Define the term "indicator species".', marks: 2, command: 'Define', markScheme: `• A species whose presence or absence indicates the level of pollution in an environment (1)\n• Because it is only found where conditions are within a particular range (1).` },
    { q: 'Name one indicator species for clean water and one for polluted water, and explain what each shows.', marks: 4, command: 'Name', markScheme: `• Mayfly nymph or stonefly nymph indicates clean water (1)\n• Because it needs a high concentration of dissolved oxygen to survive (1)\n• Bloodworm or sludgeworm indicates polluted water (1)\n• Because it can tolerate low oxygen concentrations that other species cannot (1).` },
    { q: 'Explain how lichens can be used to indicate air quality.', marks: 3, command: 'Explain', markScheme: `• Many lichens are damaged by sulfur dioxide in polluted air (1)\n• Bushy lichens are the most sensitive and grow only where the air is clean (1)\n• So a wide variety of lichens on trees indicates clean air, while bare bark indicates pollution (1).` },
    { q: 'State two advantages of using indicator species rather than instruments to assess pollution.', marks: 2, command: 'State', markScheme: `Any 2 of: it is cheap and requires no expensive equipment (1); it shows the effect of pollution over a long period rather than at a single instant (1); it shows the biological impact on the ecosystem, not just a chemical concentration (1).` },
    { q: 'State two disadvantages of using indicator species to assess pollution.', marks: 2, command: 'State', markScheme: `Any 2 of: it does not give a numerical concentration of the pollutant (1); the species may be absent for another reason, e.g. disease or temperature (1); it may not identify which pollutant is present (1).` },
    { q: 'Describe how an identification key is used in a field investigation.', marks: 2, command: 'Describe', markScheme: `• A series of paired questions about visible features is worked through (1)\n• Each answer leads to another question or to the name of the organism (1).` },
    { q: 'Describe how a quadrat is used to estimate the number of dandelions in a field.', marks: 5, command: 'Describe', markScheme: `• Use random numbers as coordinates to place the quadrat, to avoid bias (1)\n• Count the number of dandelions inside the quadrat (1)\n• Repeat for a large number of quadrats across the field (1)\n• Calculate the mean number per quadrat (1)\n• Multiply the mean by the total area of the field divided by the quadrat area (1).` },
    { q: 'Ten quadrats of 0.25 m² give a mean of 6 daisies per quadrat. Calculate the estimated number of daisies in a field of 800 m².', marks: 3, command: 'Calculate', markScheme: `• Density = 6 ÷ 0.25 = 24 daisies per m² (1)\n• Total = 24 × 800 (1)\n• = 19 200 daisies (1).` },
    { q: 'Explain why quadrats must be placed randomly rather than chosen by the investigator.', marks: 3, command: 'Explain', markScheme: `• Choosing where to put the quadrat introduces bias, e.g. picking patches with many plants (1)\n• Random placement means every part of the area has an equal chance of being sampled (1)\n• So the sample is more likely to represent the whole area (1).` },
    { q: 'Explain why a larger number of quadrats gives a more reliable estimate.', marks: 2, command: 'Explain', markScheme: `• It reduces the effect of any unusual quadrats on the mean (1)\n• A larger sample is more representative of the whole area, so the estimate is closer to the true value (1).` },
    { q: 'Explain the difference between a quadrat survey and a transect.', marks: 3, command: 'Explain', markScheme: `• A quadrat survey uses random placement to estimate abundance across a whole area (1)\n• A transect is a line along which quadrats are placed at regular intervals (1)\n• A transect is used to show how distribution changes along an environmental gradient, e.g. from the shore inland (1).` },
    { q: 'Describe how you would use a transect to investigate how plant distribution changes from a footpath into a field.', marks: 4, command: 'Describe', markScheme: `• Lay a tape measure in a straight line from the footpath into the field (1)\n• Place a quadrat at regular intervals along the tape, e.g. every 2 m (1)\n• At each point record the species present and their percentage cover or number (1)\n• Also measure abiotic factors such as light intensity and soil moisture at each point (1).` },
    { q: 'Suggest why plants growing on a well-used footpath are often smaller and fewer in number.', marks: 3, command: 'Suggest', markScheme: `• Trampling damages the leaves and stems, reducing photosynthesis (1)\n• The soil is compacted so it contains less air and water and roots cannot grow well (1)\n• Only species adapted to withstand trampling survive, so both size and number fall (1).` },
    { q: 'Explain what percentage cover means and when it is used instead of counting individuals.', marks: 3, command: 'Explain', markScheme: `• It is the proportion of the quadrat area covered by a species, estimated using the grid squares (1)\n• It is used for plants such as grasses and mosses (1)\n• Because individual plants are hard to tell apart and cannot easily be counted (1).` },
    { q: 'Describe the capture-mark-release-recapture method for estimating an animal population.', marks: 5, command: 'Describe', markScheme: `• Capture a sample of the animals and count them (1)\n• Mark each one in a way that does not harm it or make it more visible to predators (1)\n• Release them and allow time for them to mix back into the population (1)\n• Capture a second sample and count how many are marked (1)\n• Estimate the population as (number in first sample × number in second sample) ÷ number marked in second sample (1).` },
    { q: '60 woodlice are captured and marked. In a second sample of 80 woodlice, 15 are marked. Calculate the estimated population size.', marks: 3, command: 'Calculate', markScheme: `• Population = (first sample × second sample) ÷ number marked in second sample (1)\n• = (60 × 80) ÷ 15 = 4800 ÷ 15 (1)\n• = 320 woodlice (1).` },
    { q: '40 snails are marked and released. A second sample of 50 contains 8 marked snails. Calculate the estimated population size.', marks: 2, command: 'Calculate', markScheme: `• (40 × 50) ÷ 8 (1)\n• = 250 snails (1).` },
    { q: 'State three assumptions made when using the capture-mark-release-recapture method.', marks: 3, command: 'State', markScheme: `Any 3 of: the marked animals mix randomly back into the population (1); no animals are born, die, enter or leave between samples (1); the marking does not affect survival or behaviour (1); the mark does not rub off (1).` },
    { q: 'Suggest why the estimate would be too high if the marking made animals easier for predators to see.', marks: 3, command: 'Suggest', markScheme: `• More marked animals would be eaten between the two samples (1)\n• So fewer marked animals would be recaptured in the second sample (1)\n• Dividing by a smaller number gives a larger estimate than the true population (1).` },
    { q: 'Name two instruments used to measure abiotic factors in a field investigation and state what each measures.', marks: 4, command: 'Name', markScheme: `Any 2, 2 marks each: a light meter measures light intensity (2); a thermometer measures air or soil temperature (2); a moisture meter measures soil water content (2); a pH meter or probe measures soil pH (2).` },
    { q: 'Explain why abiotic factors should be measured at the same time of day at each point along a transect.', marks: 2, command: 'Explain', markScheme: `• Factors such as light intensity and temperature change during the day (1)\n• Measuring at the same time keeps these variables controlled, so differences are due to position rather than time (1).` },
    { q: 'The numbers of limpets in five quadrats are 12, 9, 15, 11 and 13. Calculate the mean.', marks: 2, command: 'Calculate', markScheme: `• Total = 12 + 9 + 15 + 11 + 13 = 60 (1)\n• Mean = 60 ÷ 5 = 12 limpets per quadrat (1).` },
    { q: 'A quadrat of 1 m² is divided into 100 squares and a moss covers 35 of them. State the percentage cover and the fraction of the quadrat covered.', marks: 2, command: 'State', markScheme: `• 35 % cover (1)\n• 35/100, which simplifies to 7/20 (1).` },
    { q: 'A woodland beetle population falls from 2400 to 1560 in one year. Calculate the percentage decrease.', marks: 3, command: 'Calculate', markScheme: `• Decrease = 2400 − 1560 = 840 (1)\n• (840 ÷ 2400) × 100 (1)\n• = 35 % decrease (1).` },
    { q: 'Suggest why the number of organisms of one species varies between quadrats placed in the same field.', marks: 3, command: 'Suggest', markScheme: `• Organisms are not distributed evenly across the field (1)\n• Abiotic factors such as light, moisture and soil depth vary from place to place (1)\n• Biotic factors such as grazing and competition also vary, so some patches support more individuals (1).` },
    { q: 'Explain why a scientist would repeat a field investigation in the same place in a different season.', marks: 3, command: 'Explain', markScheme: `• Abiotic factors such as temperature and light change with the seasons (1)\n• Many species are only present, or only visible, at certain times of year (1)\n• Repeating shows how the community changes over time rather than at a single moment (1).` },
    { q: 'A factory begins discharging warm water into a river. Discuss the possible effects on the populations living downstream.', marks: 6, command: 'Discuss', markScheme: `Any 6: warm water holds less dissolved oxygen (1); species needing high oxygen, such as mayfly nymphs and trout, decline or move away (1); species tolerant of low oxygen, such as bloodworms, may increase (1); higher temperature raises the metabolic rate of organisms, so they need more oxygen just as less is available (1); algal growth may increase, altering the food web (1); life cycles such as breeding and hatching may be triggered at the wrong time of year (1); the overall biodiversity downstream is likely to fall (1); the effect depends on the volume and temperature of the discharge relative to the river flow (1).` },
  ]},
  /* ─────────────────────────────── B4.1 Cellular respiration */
  'B4.1': { name: 'What happens during cellular respiration?', questions: [
    { q: 'Define the term "cellular respiration".', marks: 2, command: 'Define', markScheme: `• A series of chemical reactions in cells that break down glucose (1)\n• To transfer energy to molecules of ATP (1).` },
    { q: 'Write the word equation for aerobic respiration.', marks: 2, command: 'State', markScheme: `• glucose + oxygen → carbon dioxide + water (1)\n• Correct reactants and products with no additional substances (1).` },
    { q: 'Write the balanced symbol equation for aerobic respiration.', marks: 2, command: 'State', markScheme: `• C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O (1)\n• Correctly balanced (1).` },
    { q: 'Explain why cellular respiration is described as an exothermic reaction.', marks: 2, command: 'Explain', markScheme: `• Energy is transferred from the chemicals to the surroundings (1)\n• This is why respiring organisms release heat and mammals can maintain a body temperature above that of their surroundings (1).` },
    { q: 'Explain why respiration occurs continuously in all living cells.', marks: 3, command: 'Explain', markScheme: `• Cells constantly need energy for processes essential to life (1)\n• ATP cannot be stored in large amounts, so it must be made continuously (1)\n• If respiration stopped, these processes would stop and the cell would die (1).` },
    { q: 'Name three processes in a cell that require ATP.', marks: 3, command: 'Name', markScheme: `Any 3 of: the synthesis of large molecules from smaller ones (1); the breakdown of molecules (1); active transport across membranes (1); muscle contraction (1); maintaining a constant body temperature in mammals and birds (1).` },
    { q: 'Explain the role of ATP in a cell.', marks: 3, command: 'Explain', markScheme: `• ATP is the molecule that stores and transfers energy within the cell (1)\n• Energy released in respiration is used to make ATP (1)\n• ATP is broken down where energy is needed, releasing it for that process (1).` },
    { q: 'State where in a cell aerobic respiration takes place.', marks: 2, command: 'State', markScheme: `• The reactions begin in the cytoplasm (1)\n• They are completed in the mitochondria (1).` },
    { q: 'Explain how the structure of a mitochondrion is related to its function.', marks: 3, command: 'Explain', markScheme: `• It has a folded inner membrane, giving a large surface area (1)\n• The enzymes for aerobic respiration are attached to these membranes (1)\n• So many reactions can occur at once, releasing energy quickly (1).` },
    { q: 'Explain why muscle cells contain many more mitochondria than fat cells.', marks: 3, command: 'Explain', markScheme: `• Muscle cells contract, which requires a great deal of energy (1)\n• More mitochondria allow a higher rate of aerobic respiration (1)\n• So more ATP is produced to supply the contracting muscle fibres (1).` },
    { q: 'State where anaerobic respiration takes place in a cell.', marks: 1, command: 'State', markScheme: `• In the cytoplasm only (1).` },
    { q: 'Write the word equation for anaerobic respiration in human muscle cells.', marks: 1, command: 'State', markScheme: `• glucose → lactic acid (1).` },
    { q: 'Write the word equation for anaerobic respiration in yeast.', marks: 2, command: 'State', markScheme: `• glucose → ethanol + carbon dioxide (1)\n• Both products named correctly (1).` },
    { q: 'State the name given to anaerobic respiration in yeast and one use humans make of it.', marks: 2, command: 'State', markScheme: `• Fermentation (1)\n• Used in brewing to produce ethanol, or in baking where carbon dioxide makes bread rise (1).` },
    { q: 'Compare aerobic and anaerobic respiration in terms of their inputs and outputs.', marks: 4, command: 'Compare', markScheme: `• Both use glucose as the substrate (1)\n• Aerobic respiration requires oxygen; anaerobic respiration does not (1)\n• Aerobic respiration produces carbon dioxide and water (1)\n• Anaerobic respiration produces lactic acid in animals, or ethanol and carbon dioxide in yeast and plants (1).` },
    { q: 'Explain why aerobic respiration releases far more ATP per glucose molecule than anaerobic respiration.', marks: 3, command: 'Explain', markScheme: `• In aerobic respiration glucose is broken down completely to carbon dioxide and water (1)\n• In anaerobic respiration the breakdown is only partial (1)\n• The products, lactic acid or ethanol, still contain a large amount of unreleased chemical energy (1).` },
    { q: 'State two conditions in the human body under which anaerobic respiration occurs.', marks: 2, command: 'State', markScheme: `Any 2 of: during vigorous exercise when oxygen cannot be delivered fast enough (1); at the start of intense exercise before breathing and heart rate increase (1); in tissues where blood supply is restricted (1).` },
    { q: 'State two situations outside the human body in which anaerobic respiration occurs.', marks: 2, command: 'State', markScheme: `Any 2 of: in plant root cells in waterlogged soil (1); in bacteria in a deep puncture wound (1); in yeast in a sealed fermentation vessel (1); in decomposers in a landfill site (1).` },
    { q: 'Explain why the breathing rate and heart rate increase during exercise.', marks: 4, command: 'Explain', markScheme: `• Muscles respire faster and need more glucose and oxygen (1)\n• A faster breathing rate takes more oxygen into the blood and removes carbon dioxide (1)\n• A faster heart rate pumps blood around the body more quickly (1)\n• So oxygen and glucose are delivered to the muscles, and waste removed, at a greater rate (1).` },
    { q: 'Explain why a person continues to breathe deeply for several minutes after finishing hard exercise.', marks: 4, command: 'Explain', markScheme: `• Anaerobic respiration during exercise produced lactic acid in the muscles (1)\n• Extra oxygen is needed to break the lactic acid down, called the oxygen debt (1)\n• Deep breathing continues to take in this extra oxygen (1)\n• The blood carries the lactic acid to the liver, where it is converted back to glucose (1).` },
    { q: 'Explain why muscles become fatigued and painful during vigorous exercise.', marks: 3, command: 'Explain', markScheme: `• Oxygen cannot be supplied fast enough, so muscle cells respire anaerobically (1)\n• Lactic acid builds up in the muscle tissue (1)\n• This lowers the pH, which affects enzymes and causes pain, and the muscle contracts less efficiently (1).` },
    { q: 'Explain why a trained athlete recovers from exercise more quickly than an untrained person.', marks: 3, command: 'Explain', markScheme: `• Training increases the efficiency of the heart and lungs and the density of capillaries in the muscles (1)\n• Oxygen is delivered to the muscles more quickly (1)\n• So lactic acid is broken down faster and the oxygen debt is repaid sooner (1).` },
    { q: 'Explain why plants need to respire even though they photosynthesise.', marks: 3, command: 'Explain', markScheme: `• Photosynthesis makes glucose but does not release energy in a usable form (1)\n• Respiration is needed to transfer the energy in glucose to ATP (1)\n• ATP is needed for processes such as active transport and building proteins, including at night when there is no light (1).` },
    { q: 'Describe how you could investigate the effect of different substrates on the rate of respiration in yeast.', marks: 5, command: 'Describe', markScheme: `• Mix yeast with a solution of one sugar, e.g. glucose, in a boiling tube (1)\n• Seal the tube and connect it by a delivery tube to a gas syringe or inverted measuring cylinder over water (1)\n• Place the tube in a water bath at a set temperature and allow to equilibrate (1)\n• Record the volume of carbon dioxide collected at regular intervals (1)\n• Repeat with different sugars, keeping the volume, concentration and temperature the same, and compare the rates (1).` },
    { q: 'In a yeast respiration experiment 24 cm³ of gas is collected in 8 minutes. Calculate the rate in cm³ per minute.', marks: 2, command: 'Calculate', markScheme: `• Rate = 24 ÷ 8 (1)\n• = 3 cm³ per minute (1).` },
    { q: 'Yeast produces 45 cm³ of carbon dioxide in 5 minutes at 30 °C and 18 cm³ in 5 minutes at 15 °C. Calculate both rates and explain the difference.', marks: 4, command: 'Calculate', markScheme: `• At 30 °C rate = 45 ÷ 5 = 9 cm³ per minute (1)\n• At 15 °C rate = 18 ÷ 5 = 3.6 cm³ per minute (1)\n• At the higher temperature the respiration enzymes and substrate molecules have more kinetic energy (1)\n• So there are more successful collisions per second and the rate of respiration is higher (1).` },
    { q: 'Explain why a layer of oil is often placed on top of the yeast mixture in a fermentation experiment.', marks: 2, command: 'Explain', markScheme: `• The oil stops oxygen from the air dissolving into the mixture (1)\n• This ensures the yeast respires anaerobically, so the results test fermentation (1).` },
    { q: 'Explain why a control containing boiled yeast should be included in a respiration investigation.', marks: 3, command: 'Explain', markScheme: `• Boiling kills the yeast and denatures its enzymes (1)\n• No gas should be produced by the control (1)\n• This shows that any gas in the other tubes is produced by living, respiring yeast rather than by a chemical reaction of the sugar (1).` },
    { q: 'Describe how you could compare the energy released by burning two different foods.', marks: 5, command: 'Describe', markScheme: `• Measure a set volume of water into a boiling tube and record its starting temperature (1)\n• Find the mass of the food sample and set it alight using a Bunsen flame (1)\n• Hold the burning food under the boiling tube until it stops burning (1)\n• Record the highest temperature reached by the water (1)\n• Repeat with the same mass of the second food, using the same volume of water and the same distance from the tube (1).` },
    { q: 'Burning 0.5 g of a food raises the temperature of 20 g of water by 25 °C. Calculate the energy released, using energy (J) = mass of water (kg) × temperature change (°C) × 4200.', marks: 3, command: 'Calculate', markScheme: `• Mass of water = 20 g = 0.020 kg (1)\n• Energy = 0.020 × 25 × 4200 (1)\n• = 2100 J (1).` },
    { q: 'Using the result above, calculate the energy released per gram of that food.', marks: 2, command: 'Calculate', markScheme: `• 2100 ÷ 0.5 (1)\n• = 4200 J per gram (1).` },
    { q: 'Suggest two reasons why the energy value measured by burning food in a school laboratory is lower than the true value.', marks: 4, command: 'Suggest', markScheme: `Any 2, 2 marks each: much of the heat is lost to the surrounding air rather than heating the water (2); the food may not burn completely, so not all its energy is released (2); heat is absorbed by the glass of the boiling tube rather than the water (2).` },
    { q: 'Explain why lipids release more energy per gram than carbohydrates.', marks: 2, command: 'Explain', markScheme: `• Lipid molecules contain a greater proportion of carbon and hydrogen atoms and less oxygen (1)\n• So more energy is released when they are oxidised during respiration (1).` },
    { q: 'Describe how you could show that germinating seeds release carbon dioxide.', marks: 4, command: 'Describe', markScheme: `• Place germinating seeds in a sealed flask connected to a tube of hydrogencarbonate indicator or limewater (1)\n• Set up an identical flask containing boiled, dead seeds as a control (1)\n• Leave both for a set time at the same temperature (1)\n• The indicator turns yellow, or the limewater turns cloudy, only in the tube connected to the living seeds (1).` },
    { q: 'Explain why germinating seeds are warmer than dead seeds in the same conditions.', marks: 3, command: 'Explain', markScheme: `• Germinating seeds are alive and respiring (1)\n• Respiration is exothermic, so it transfers energy to the surroundings as heat (1)\n• Dead seeds do not respire, so their temperature stays the same as the surroundings (1).` },
    { q: 'Explain why a plant root in a waterlogged field may die.', marks: 4, command: 'Explain', markScheme: `• Waterlogged soil contains very little oxygen (1)\n• Root cells must respire anaerobically, producing ethanol (1)\n• Anaerobic respiration yields far less ATP per glucose molecule (1)\n• There is not enough ATP for active transport and growth, and the ethanol is toxic, so the cells die (1).` },
    { q: 'Explain why bacteria in a deep puncture wound can be particularly dangerous.', marks: 3, command: 'Explain', markScheme: `• Little oxygen reaches the bottom of a deep narrow wound (1)\n• Anaerobic bacteria such as those causing tetanus can respire and multiply there (1)\n• They release toxins that damage the body, and antiseptics applied to the skin surface may not reach them (1).` },
    { q: 'Compare the rate of ATP production in a muscle cell during rest and during a short sprint.', marks: 4, command: 'Compare', markScheme: `• At rest the demand for ATP is low and is met entirely by aerobic respiration (1)\n• Oxygen supply matches demand, so no lactic acid builds up (1)\n• During a sprint the demand for ATP rises sharply and oxygen cannot be supplied fast enough (1)\n• Anaerobic respiration supplies extra ATP quickly but produces lactic acid and yields far less ATP per glucose (1).` },
    { q: 'A student claims that anaerobic respiration is "less useful" than aerobic respiration. Discuss this claim.', marks: 6, command: 'Discuss', markScheme: `Any 6: anaerobic respiration releases much less ATP per glucose molecule (1); its products, lactic acid and ethanol, are toxic and must be removed or tolerated (1); it uses glucose reserves quickly for little return (1); however it releases ATP very rapidly, which aerobic respiration cannot match (1); it allows muscles to keep contracting when oxygen supply is insufficient (1); it allows organisms to survive in oxygen-free environments such as waterlogged soil or deep wounds (1); humans exploit it in brewing and baking (1); conclusion: it is less efficient but essential in conditions where aerobic respiration is not possible (1).` },
    { q: 'Discuss the evidence that mitochondria are the site of aerobic respiration in eukaryotic cells.', marks: 6, command: 'Discuss', markScheme: `Any 6: cells with high energy demands, such as muscle and sperm cells, contain very large numbers of mitochondria (1); cells with low energy demands contain few (1); mitochondria isolated from cells take up oxygen and release carbon dioxide (1); the enzymes catalysing the reactions of aerobic respiration are found in the mitochondria (1); the folded inner membrane provides a large surface area for these enzymes (1); electron microscopy was needed before this internal structure could be seen (1); prokaryotes have no mitochondria and carry out respiration in the cytoplasm and at the cell membrane instead (1); conclusion: the correlation of structure, contents and cell type provides strong supporting evidence (1).` },
  ]},
  /* ─────────────────────────────── B4.2 Cell structures and microscopy */
  'B4.2': { name: 'How do we know about mitochondria and other cell structures?', questions: [
    { q: 'Name four structures found in an animal cell.', marks: 2, command: 'Name', markScheme: `• Nucleus and cytoplasm (1)\n• Cell membrane and mitochondria (1).` },
    { q: 'Name three structures found in a plant cell that are not found in an animal cell.', marks: 3, command: 'Name', markScheme: `• Cellulose cell wall (1)\n• Chloroplasts (1)\n• Permanent vacuole containing cell sap (1).` },
    { q: 'State the function of the nucleus.', marks: 2, command: 'State', markScheme: `• It contains the DNA, arranged as chromosomes (1)\n• It controls the activities of the cell by controlling which proteins are made (1).` },
    { q: 'State the function of the cell membrane.', marks: 2, command: 'State', markScheme: `• It holds the cell together and separates the cytoplasm from the outside (1)\n• It is partially permeable, controlling which substances enter and leave the cell (1).` },
    { q: 'State the function of the ribosomes.', marks: 1, command: 'State', markScheme: `• They are the site of protein synthesis (1).` },
    { q: 'Compare the structure of a eukaryotic cell with that of a prokaryotic cell.', marks: 4, command: 'Compare', markScheme: `• A eukaryotic cell has a nucleus; a prokaryotic cell does not (1)\n• In a prokaryotic cell the DNA is a single loop free in the cytoplasm, often with extra plasmids (1)\n• Eukaryotic cells contain membrane-bound organelles such as mitochondria; prokaryotic cells do not (1)\n• Prokaryotic cells are much smaller, typically 1-5 μm compared with 10-100 μm (1).` },
    { q: 'Name two examples of eukaryotic organisms and one example of a prokaryotic organism.', marks: 3, command: 'Name', markScheme: `• Any two of: animals, plants, fungi, protists (1 each, max 2)\n• Bacteria (1).` },
    { q: 'Describe the function of a plasmid in a bacterial cell.', marks: 2, command: 'Describe', markScheme: `• A plasmid is a small circular loop of DNA separate from the main chromosome (1)\n• It carries extra genes, such as those for antibiotic resistance, and can be transferred between bacteria (1).` },
    { q: 'Explain the difference between magnification and resolution.', marks: 3, command: 'Explain', markScheme: `• Magnification is how many times larger the image is than the actual object (1)\n• Resolution is the smallest distance between two points that can still be seen as separate (1)\n• Increasing magnification beyond the limit of resolution produces a larger but blurred image with no extra detail (1).` },
    { q: 'State the equation linking magnification, image size and actual size.', marks: 1, command: 'State', markScheme: `• magnification = size of image ÷ size of actual object (1).` },
    { q: 'An image of a cell is 60 mm across and the cell is actually 0.03 mm across. Calculate the magnification.', marks: 2, command: 'Calculate', markScheme: `• Magnification = 60 ÷ 0.03 (1)\n• = ×2000 (1).` },
    { q: 'A mitochondrion is drawn 40 mm long at a magnification of ×20 000. Calculate its actual length in micrometres.', marks: 3, command: 'Calculate', markScheme: `• Actual size = image size ÷ magnification = 40 ÷ 20 000 = 0.002 mm (1)\n• 1 mm = 1000 μm (1)\n• 0.002 × 1000 = 2 μm (1).` },
    { q: 'Convert 0.000004 m into micrometres and write it in standard form in metres.', marks: 2, command: 'Calculate', markScheme: `• 0.000004 m = 4 μm (1)\n• = 4 × 10⁻⁶ m (1).` },
    { q: 'State how many micrometres there are in a millimetre and how many nanometres in a micrometre.', marks: 2, command: 'State', markScheme: `• 1000 μm in 1 mm (1)\n• 1000 nm in 1 μm (1).` },
    { q: 'A bacterium is 2 μm long. Express this length in metres in standard form.', marks: 2, command: 'Calculate', markScheme: `• 1 μm = 1 × 10⁻⁶ m (1)\n• 2 μm = 2 × 10⁻⁶ m (1).` },
    { q: 'A virus particle is 80 nm across. Express this in micrometres.', marks: 2, command: 'Calculate', markScheme: `• 1 μm = 1000 nm, so divide by 1000 (1)\n• 80 ÷ 1000 = 0.08 μm (1).` },
    { q: 'Explain why an estimate of cell size is sometimes more appropriate than a precise measurement.', marks: 3, command: 'Explain', markScheme: `• Cells of the same type vary in size, so a single precise value would be misleading (1)\n• An estimate to an order of magnitude is enough to compare cell types or to check a calculation is sensible (1)\n• It is also quicker than measuring many cells individually (1).` },
    { q: 'Estimate how many times larger a typical animal cell (20 μm) is than a typical bacterium (2 μm).', marks: 2, command: 'Calculate', markScheme: `• 20 ÷ 2 (1)\n• The animal cell is about 10 times larger in diameter (1).` },
    { q: 'State the approximate maximum resolution of a light microscope and of an electron microscope.', marks: 2, command: 'State', markScheme: `• Light microscope: about 200 nm (0.2 μm) (1)\n• Electron microscope: about 0.2 nm (1).` },
    { q: 'Explain why an electron microscope has a much higher resolution than a light microscope.', marks: 3, command: 'Explain', markScheme: `• An electron microscope uses a beam of electrons rather than light (1)\n• Electrons have a much shorter wavelength than visible light (1)\n• The shorter the wavelength, the smaller the detail that can be resolved (1).` },
    { q: 'State two sub-cellular structures that can only be seen using an electron microscope.', marks: 2, command: 'State', markScheme: `Any 2 of: ribosomes; the internal membranes of mitochondria; the internal membranes of chloroplasts; plasmids; the structure of the cell membrane (1 each).` },
    { q: 'Explain how the invention of the electron microscope changed scientists\' understanding of mitochondria.', marks: 4, command: 'Explain', markScheme: `• Under a light microscope mitochondria appeared only as small dots with no visible detail (1)\n• The electron microscope revealed their internal structure, including the folded inner membrane (1)\n• This large surface area suggested a site where many enzyme-controlled reactions take place (1)\n• Scientists could then develop and test the explanation that mitochondria are the site of aerobic respiration (1).` },
    { q: 'Explain what this example shows about how scientific explanations develop.', marks: 3, command: 'Explain', markScheme: `• New technology allows observations that could not be made before (1)\n• Scientists use these new observations to develop and improve their explanations (1)\n• So progress in science often depends on progress in technology (1).` },
    { q: 'Suggest why scientists could not explain the function of ribosomes before the 1950s.', marks: 2, command: 'Suggest', markScheme: `• Ribosomes are far too small to be resolved by a light microscope (1)\n• They could not be observed until the electron microscope was developed, so no explanation could be based on evidence (1).` },
    { q: 'State two disadvantages of an electron microscope compared with a light microscope.', marks: 2, command: 'State', markScheme: `Any 2 of: it is very expensive to buy and maintain (1); it is large and must be kept in a special room (1); specimens must be dead, as they are placed in a vacuum (1); images are not in natural colour (1); preparing specimens is complex and can create artefacts (1).` },
    { q: 'Explain why living cells cannot be observed with an electron microscope.', marks: 2, command: 'Explain', markScheme: `• The specimen chamber must be a vacuum so the electrons are not scattered by air particles (1)\n• No living cell can survive in a vacuum, and specimens must also be chemically fixed and dehydrated (1).` },
    { q: 'State one advantage of a light microscope over an electron microscope for a school laboratory.', marks: 2, command: 'State', markScheme: `Any 1, 2 marks: it is cheap and small enough for classroom use (2); living specimens can be observed moving (2); specimens are quick and simple to prepare (2).` },
    { q: 'Describe how to prepare a slide of onion epidermis cells for a light microscope.', marks: 5, command: 'Describe', markScheme: `• Peel a thin layer of epidermis from the inner surface of an onion scale (1)\n• Place it flat on a clean microscope slide (1)\n• Add a drop of iodine solution to stain the cells (1)\n• Lower a coverslip slowly using a mounted needle to avoid trapping air bubbles (1)\n• Blot away any excess liquid with filter paper (1).` },
    { q: 'Explain why a specimen for a light microscope must be very thin.', marks: 2, command: 'Explain', markScheme: `• Light must pass through the specimen to reach the eye (1)\n• A thick specimen would appear dark and the layers of cells would overlap, so no detail would be visible (1).` },
    { q: 'Describe how to focus a light microscope on a specimen.', marks: 4, command: 'Describe', markScheme: `• Select the lowest power objective lens and clip the slide onto the stage (1)\n• Use the coarse focus to move the stage and objective close together while watching from the side (1)\n• Look through the eyepiece and turn the coarse focus to move them apart until the image appears (1)\n• Use the fine focus to sharpen the image, then switch to a higher power lens and refocus using the fine focus only (1).` },
    { q: 'Explain why the coarse focus should not be used at high magnification.', marks: 2, command: 'Explain', markScheme: `• At high magnification the objective lens is very close to the slide (1)\n• The coarse focus moves the stage a long way, so the lens could crash into and break the slide (1).` },
    { q: 'Explain why a stain such as iodine or methylene blue is used when preparing a slide.', marks: 2, command: 'Explain', markScheme: `• Many cell structures are transparent and have little contrast (1)\n• The stain colours particular structures, such as the nucleus, so they can be distinguished (1).` },
    { q: 'Explain why a coverslip is lowered slowly at an angle.', marks: 2, command: 'Explain', markScheme: `• To avoid trapping air bubbles under the coverslip (1)\n• Air bubbles appear as dark circles that obscure the cells (1).` },
    { q: 'A field of view is 1.8 mm across and contains 12 cells side by side. Estimate the mean diameter of one cell in micrometres.', marks: 3, command: 'Calculate', markScheme: `• 1.8 mm = 1800 μm (1)\n• 1800 ÷ 12 (1)\n• = 150 μm (1).` },
    { q: 'Explain how a graticule and stage micrometer are used to measure the size of a cell.', marks: 3, command: 'Explain', markScheme: `• The stage micrometer is a slide with a scale of known divisions (1)\n• It is used to calibrate the eyepiece graticule, finding the real distance represented by one graticule division at that magnification (1)\n• The cell is then measured in graticule divisions and multiplied by this value (1).` },
    { q: 'Explain why a scale bar is included on an electron micrograph.', marks: 2, command: 'Explain', markScheme: `• The magnification of a printed image changes if it is enlarged or reduced (1)\n• A scale bar is enlarged by the same amount, so the actual size can always be worked out (1).` },
    { q: 'Explain why sperm cells contain many mitochondria in the mid-piece.', marks: 3, command: 'Explain', markScheme: `• The tail must beat continuously to propel the sperm towards the egg (1)\n• This requires a large and continuous supply of ATP (1)\n• Mitochondria carry out aerobic respiration, so placing many of them next to the tail supplies that ATP (1).` },
    { q: 'Explain why a root hair cell has no chloroplasts but many mitochondria.', marks: 3, command: 'Explain', markScheme: `• Root hair cells are underground where there is no light, so photosynthesis is impossible (1)\n• Chloroplasts would serve no purpose (1)\n• Many mitochondria supply the ATP needed for the active transport of mineral ions into the cell (1).` },
    { q: 'Suggest how a scientist could use an electron micrograph to decide whether a cell is from a leaf or from a muscle.', marks: 4, command: 'Suggest', markScheme: `• Look for a cell wall and a large permanent vacuole, which would indicate a plant cell (1)\n• Look for chloroplasts, which are present only in photosynthetic plant cells (1)\n• A muscle cell would have no cell wall or chloroplasts (1)\n• A muscle cell would contain a very high density of mitochondria and protein fibres for contraction (1).` },
    { q: 'Discuss how far the statement "seeing is believing" applies to the discovery of cell organelles.', marks: 6, command: 'Discuss', markScheme: `Any 6: direct observation with the electron microscope gave strong evidence that organelles exist (1); images allowed structures to be linked to proposed functions (1); however an image alone does not show what a structure does (1); function was established by further experiments, e.g. isolating mitochondria and measuring oxygen uptake (1); preparation can create artefacts that are not present in the living cell (1); electron micrographs are not in natural colour and require interpretation (1); explanations were accepted only after independent scientists made the same observations (1); conclusion: observation was necessary but not sufficient, and had to be combined with experiment and peer review (1).` },
  ]},
  /* ─────────────────────────────── B4.3 Growth and development */
  'B4.3': { name: 'How do organisms grow and develop?', questions: [
    { q: 'Explain what growth means in a multicellular organism.', marks: 2, command: 'Explain', markScheme: `• An increase in the number of body cells by cell division (1)\n• Together with cell enlargement and differentiation to form tissues and organs (1).` },
    { q: 'Name the two main stages of the cell cycle.', marks: 2, command: 'Name', markScheme: `• Interphase (1)\n• Mitosis, followed by division of the cytoplasm (1).` },
    { q: 'Describe what happens during interphase.', marks: 3, command: 'Describe', markScheme: `• The cell grows larger (1)\n• The number of organelles, such as mitochondria and ribosomes, increases (1)\n• Each chromosome is copied, so the DNA content doubles (1).` },
    { q: 'Describe what happens during mitosis.', marks: 3, command: 'Describe', markScheme: `• The chromosome copies separate and move to opposite ends of the cell (1)\n• The nucleus divides into two (1)\n• The cytoplasm and cell membrane then divide to form two new cells (1).` },
    { q: 'State two ways in which the two cells produced by mitosis are related to the parent cell.', marks: 2, command: 'State', markScheme: `• They contain the same number of chromosomes as the parent cell (1)\n• They are genetically identical to the parent cell and to each other (1).` },
    { q: 'State three roles of mitosis in a multicellular organism.', marks: 3, command: 'State', markScheme: `• Growth by increasing the number of cells (1)\n• Repair of damaged tissues and replacement of worn-out cells (1)\n• Asexual reproduction in some organisms (1).` },
    { q: 'Describe how you would prepare and observe a slide showing stages of mitosis.', marks: 5, command: 'Describe', markScheme: `• Cut the tip from a growing onion root, where cells are dividing rapidly (1)\n• Place it in warm hydrochloric acid to break down the tissue and separate the cells (1)\n• Rinse, place on a slide and add a stain such as acetic orcein to colour the chromosomes (1)\n• Gently squash under a coverslip to spread the cells into a single layer (1)\n• Observe under a light microscope, starting at low power, and identify cells in different stages (1).` },
    { q: 'Explain why the tip of a root is chosen for observing mitosis.', marks: 2, command: 'Explain', markScheme: `• The root tip contains a meristem where cells are dividing rapidly (1)\n• So a large proportion of the cells will be in mitosis at any moment (1).` },
    { q: 'In a field of view of 80 cells, 12 are in mitosis. Calculate the percentage of cells in mitosis.', marks: 2, command: 'Calculate', markScheme: `• (12 ÷ 80) × 100 (1)\n• = 15 % (1).` },
    { q: 'A cell cycle lasts 20 hours and mitosis occupies 5 % of it. Calculate the time spent in mitosis in minutes.', marks: 3, command: 'Calculate', markScheme: `• 5 % of 20 hours = 0.05 × 20 = 1 hour (1)\n• 1 hour = 60 minutes (1)\n• Mitosis lasts 60 minutes (1).` },
    { q: 'Describe cancer in terms of cell division.', marks: 3, command: 'Describe', markScheme: `• Changes in the DNA of a cell cause it to lose control of cell division (1)\n• The cell divides repeatedly by mitosis when it should not (1)\n• The mass of cells produced forms a tumour (1).` },
    { q: 'Explain the difference between a benign and a malignant tumour.', marks: 3, command: 'Explain', markScheme: `• A benign tumour stays in one place, usually within a membrane, and does not invade other tissues (1)\n• A malignant tumour invades surrounding tissue (1)\n• Cells can break off, spread in the blood and form secondary tumours elsewhere in the body (1).` },
    { q: 'State three factors that increase the risk of developing cancer.', marks: 3, command: 'State', markScheme: `Any 3 of: smoking; exposure to ultraviolet radiation; exposure to ionising radiation; certain chemicals (carcinogens); some viral infections, e.g. HPV; inherited genetic variants such as BRCA1 (1 each).` },
    { q: 'Explain why a carcinogen increases the risk of cancer.', marks: 3, command: 'Explain', markScheme: `• A carcinogen causes mutations in the DNA of cells (1)\n• A mutation in a gene controlling cell division may stop the cell responding to signals to stop dividing (1)\n• The cell then divides uncontrollably, forming a tumour (1).` },
    { q: 'Name the type of cell division that produces gametes.', marks: 1, command: 'Name', markScheme: `• Meiosis (1).` },
    { q: 'Describe the main events of meiosis.', marks: 4, command: 'Describe', markScheme: `• During interphase the chromosomes are copied, doubling the DNA content (1)\n• The first meiotic division separates the pairs of chromosomes (1)\n• The second meiotic division separates the chromosome copies (1)\n• Four cells are produced, each with half the chromosome number of the parent cell (1).` },
    { q: 'Explain why gametes must contain half the normal number of chromosomes.', marks: 3, command: 'Explain', markScheme: `• At fertilisation two gametes fuse to form a zygote (1)\n• The maternal and paternal chromosomes pair up (1)\n• So the zygote has the full, normal chromosome number for the species, and this stays constant between generations (1).` },
    { q: 'A human body cell contains 46 chromosomes. State how many chromosomes are in a human sperm cell and in a zygote.', marks: 2, command: 'State', markScheme: `• Sperm cell: 23 chromosomes (1)\n• Zygote: 46 chromosomes (1).` },
    { q: 'Compare mitosis and meiosis.', marks: 4, command: 'Compare', markScheme: `• Mitosis produces two cells; meiosis produces four (1)\n• Mitosis produces cells with the full chromosome number; meiosis halves the chromosome number (1)\n• Cells from mitosis are genetically identical; cells from meiosis are genetically different from each other (1)\n• Mitosis is used for growth and repair; meiosis produces gametes for sexual reproduction (1).` },
    { q: 'Explain how meiosis contributes to variation between offspring.', marks: 3, command: 'Explain', markScheme: `• The chromosomes of each pair are separated independently, so gametes receive different combinations of maternal and paternal chromosomes (1)\n• Every gamete is therefore genetically different (1)\n• Which two gametes fuse at fertilisation is also random, adding further variation (1).` },
    { q: 'Define the term "stem cell".', marks: 2, command: 'Define', markScheme: `• An undifferentiated cell that can divide repeatedly (1)\n• And can become specialised into different types of cell (1).` },
    { q: 'Explain the difference between an embryonic stem cell and an adult stem cell.', marks: 3, command: 'Explain', markScheme: `• An embryonic stem cell comes from an early embryo and can become any type of cell (1)\n• An adult stem cell is found in certain tissues of a developed organism, such as bone marrow (1)\n• It can only become a limited range of cell types, e.g. blood cells (1).` },
    { q: 'Explain why most cells in a human embryo become specialised after the eight-cell stage.', marks: 2, command: 'Explain', markScheme: `• Up to that point all the cells are identical and unspecialised (1)\n• After it, different genes are switched on and off in different cells so that they differentiate into particular types (1).` },
    { q: 'Explain how a cell becomes specialised during differentiation.', marks: 3, command: 'Explain', markScheme: `• Every cell contains the same genes (1)\n• Different genes are switched on and off in different cells (1)\n• So each cell makes a different set of proteins, giving it a structure suited to a particular function (1).` },
    { q: 'Explain why differentiation is important in a multicellular organism.', marks: 3, command: 'Explain', markScheme: `• Specialised cells are adapted to carry out one function efficiently (1)\n• Similar cells work together as tissues, and tissues form organs (1)\n• This division of labour allows the organism to carry out complex processes that a single cell type could not (1).` },
    { q: 'Name the region of a plant where cells divide, and state what makes it different from most plant tissue.', marks: 2, command: 'Name', markScheme: `• The meristem, found at root and shoot tips (1)\n• It is the only region where mitosis occurs, and its cells are unspecialised and can become any type of plant cell (1).` },
    { q: 'Explain why plants can be cloned from cuttings much more easily than animals can be cloned.', marks: 3, command: 'Explain', markScheme: `• Plants keep unspecialised meristem cells throughout their lives (1)\n• These can differentiate into any type of plant cell (1)\n• Most animal cells differentiate permanently early in development and cannot form other cell types (1).` },
    { q: 'Describe two medical conditions that stem cells could potentially be used to treat.', marks: 4, command: 'Describe', markScheme: `Any 2, 2 marks each: type 1 diabetes, by producing new insulin-secreting pancreatic cells (2); paralysis, by replacing damaged nerve cells in the spinal cord (2); blindness caused by retinal damage, by replacing the damaged retinal cells (2); leukaemia, using bone marrow stem cells to produce healthy blood cells (2).` },
    { q: 'Explain why treating a disease with stem cells could be better than treating the symptoms.', marks: 3, command: 'Explain', markScheme: `• Stem cells could replace the damaged or missing cells causing the disease (1)\n• This tackles the cause rather than managing the effects (1)\n• So the patient may not need lifelong medication such as daily insulin injections (1).` },
    { q: 'Describe two risks of using stem cells in medicine.', marks: 4, command: 'Describe', markScheme: `Any 2, 2 marks each: the transplanted cells may divide uncontrollably and form a tumour (2); the cells may carry a viral infection that is passed to the patient (2); the patient\'s immune system may reject cells from a donor, requiring immunosuppressant drugs (2).` },
    { q: 'Explain why some people object to the use of embryonic stem cells.', marks: 3, command: 'Explain', markScheme: `• Embryonic stem cells are obtained from early embryos, which are destroyed in the process (1)\n• Some people believe an embryo is a potential human life with the same right to life as a person (1)\n• They therefore regard destroying it as unacceptable, whatever the medical benefit (1).` },
    { q: 'Explain why the use of stem cells in research and medicine is regulated by governments.', marks: 3, command: 'Explain', markScheme: `• The issues are ethically contested, so society needs agreed limits rather than individual decisions (1)\n• Regulation ensures embryos are used only where there is a strong justification and with consent (1)\n• It also protects patients from unsafe or untested treatments (1).` },
    { q: 'Suggest one advantage of using a patient\'s own adult stem cells rather than embryonic stem cells.', marks: 3, command: 'Suggest', markScheme: `• The cells are genetically identical to the patient\'s own cells (1)\n• So they will not be rejected by the immune system and no immunosuppressants are needed (1)\n• No embryo is destroyed, so the main ethical objection does not apply (1).` },
    { q: 'Explain why damage to the nervous system is difficult to treat.', marks: 3, command: 'Explain', markScheme: `• Once differentiated, neurones do not undergo mitosis (1)\n• So lost or damaged neurones cannot be replaced by the body (1)\n• The loss of function is therefore usually permanent, which is why stem cell research is being pursued (1).` },
    { q: 'A percentile growth chart shows a baby on the 50th percentile for mass. Explain what this means.', marks: 2, command: 'Explain', markScheme: `• 50 % of babies of that age have a lower mass and 50 % have a higher mass (1)\n• So the baby is at the median mass for its age (1).` },
    { q: 'A baby\'s mass moves from the 50th percentile to the 9th percentile over three months. Suggest why a doctor would investigate.', marks: 3, command: 'Suggest', markScheme: `• The baby is growing more slowly than most babies of the same age (1)\n• Crossing down through percentile lines suggests a change rather than simply being a small baby (1)\n• It could indicate a feeding problem, malabsorption or an underlying illness that needs treatment (1).` },
    { q: 'Explain why a single measurement of a baby\'s mass is less useful than a series of measurements plotted on a chart.', marks: 3, command: 'Explain', markScheme: `• Babies vary widely in size, so one measurement cannot show whether growth is normal (1)\n• A series shows the pattern of growth over time (1)\n• A change in the percentile a baby follows is what indicates a possible problem (1).` },
    { q: 'Explain why growth charts use percentiles rather than a single "normal" mass for each age.', marks: 3, command: 'Explain', markScheme: `• There is a wide natural range of mass at any given age (1)\n• A single value would wrongly suggest that most healthy babies are abnormal (1)\n• Percentiles show where a child sits within the range of the whole population (1).` },
    { q: 'Suggest why cancer becomes more common as people get older.', marks: 3, command: 'Suggest', markScheme: `• Mutations accumulate in cells over a lifetime (1)\n• The longer a person lives, the more cell divisions occur and the greater the exposure to carcinogens (1)\n• Several mutations in the same cell are usually needed before control of division is lost (1).` },
    { q: 'Discuss whether research using embryonic stem cells should be allowed.', marks: 6, command: 'Discuss', markScheme: `Any 6: embryonic stem cells can become any cell type, so have the widest medical potential (1); they could treat conditions such as paralysis and diabetes that have no cure (1); embryos used are often spare ones from fertility treatment that would otherwise be destroyed (1); however obtaining the cells destroys the embryo (1); some believe an embryo has the moral status of a person from fertilisation (1); adult stem cells and reprogrammed cells offer alternatives that avoid this objection (1); regulation with informed consent can address some concerns (1); conclusion: a justified judgement weighing the potential to relieve suffering against the moral status of the embryo (1).` },
  ]},
  /* ─────────────────────────────── B5.1 Substances in, out and around the body */
  'B5.1': { name: 'How do substances get into, out of, and around our bodies?', questions: [
    { q: 'Name three substances that must be transported into the human body and two waste products that must be removed.', marks: 3, command: 'Name', markScheme: `• Into the body: oxygen, water and dissolved food molecules (1 for any two, 2 for all three)\n• Out of the body: carbon dioxide and urea (1).` },
    { q: 'Explain why carbon dioxide and urea must be removed from the body.', marks: 2, command: 'Explain', markScheme: `• They are waste products of metabolism that are toxic if they build up (1)\n• Carbon dioxide lowers blood pH and urea damages cells, so both would disrupt enzyme activity (1).` },
    { q: 'Name the four organ systems involved in moving substances into, around and out of the body.', marks: 4, command: 'Name', markScheme: `• The circulatory system (1)\n• The gaseous exchange system (1)\n• The digestive system (1)\n• The excretory system (1).` },
    { q: 'Explain the need for exchange surfaces in a large multicellular organism.', marks: 4, command: 'Explain', markScheme: `• As an organism gets larger, its surface area to volume ratio decreases (1)\n• Its outer surface is too small to supply the needs of all the cells inside (1)\n• Diffusion distances from the surface to internal cells are also too great (1)\n• Specialised exchange surfaces with a large surface area are therefore needed (1).` },
    { q: 'Calculate the surface area to volume ratio of a cube of side 2 cm.', marks: 3, command: 'Calculate', markScheme: `• Surface area = 6 × 2 × 2 = 24 cm² (1)\n• Volume = 2 × 2 × 2 = 8 cm³ (1)\n• Ratio = 24 : 8 = 3 : 1 (1).` },
    { q: 'Calculate the surface area to volume ratio of a cube of side 4 cm and compare it with a cube of side 2 cm.', marks: 4, command: 'Calculate', markScheme: `• Surface area = 6 × 4 × 4 = 96 cm² (1)\n• Volume = 4 × 4 × 4 = 64 cm³ (1)\n• Ratio = 96 : 64 = 1.5 : 1 (1)\n• The larger cube has a smaller surface area to volume ratio (1).` },
    { q: 'Describe how you could use agar cubes to model the effect of surface area to volume ratio on diffusion.', marks: 4, command: 'Describe', markScheme: `• Cut cubes of different sizes from agar containing an indicator such as phenolphthalein in alkali (1)\n• Place them in dilute acid and start a stopwatch (1)\n• Record the time for each cube to lose its colour completely (1)\n• The smallest cube, with the largest surface area to volume ratio, changes fastest (1).` },
    { q: 'State four features of an efficient exchange surface.', marks: 4, command: 'State', markScheme: `• A large surface area (1)\n• A thin surface, giving a short diffusion pathway (1)\n• A good blood supply, or ventilation, to maintain a steep concentration gradient (1)\n• A moist, partially permeable surface (1).` },
    { q: 'Explain how the alveoli are adapted for efficient gas exchange.', marks: 4, command: 'Explain', markScheme: `• There are millions of alveoli, giving a very large total surface area (1)\n• Their walls are one cell thick, so the diffusion distance is very short (1)\n• They are surrounded by a dense capillary network which removes oxygen and brings carbon dioxide, maintaining steep concentration gradients (1)\n• They are moist, so gases dissolve before diffusing across (1).` },
    { q: 'Describe the movement of oxygen and carbon dioxide at an alveolus.', marks: 3, command: 'Describe', markScheme: `• Oxygen is at a higher concentration in the alveolus than in the blood, so it diffuses into the capillary (1)\n• Carbon dioxide is at a higher concentration in the blood, so it diffuses into the alveolus (1)\n• It is then removed from the lungs when the person breathes out (1).` },
    { q: 'Explain how the small intestine is adapted for absorbing digested food.', marks: 4, command: 'Explain', markScheme: `• It is very long and its lining is folded and covered in villi and microvilli, giving a huge surface area (1)\n• The wall of each villus is one cell thick, so the diffusion distance is short (1)\n• Each villus has a good blood supply which carries absorbed molecules away, maintaining the concentration gradient (1)\n• Villus cells contain many mitochondria to supply ATP for active transport of glucose and amino acids (1).` },
    { q: 'Explain why glucose is sometimes absorbed from the small intestine by active transport rather than diffusion.', marks: 3, command: 'Explain', markScheme: `• Towards the end of a meal the glucose concentration in the gut may be lower than in the blood (1)\n• Diffusion would then move glucose out of the blood rather than into it (1)\n• Active transport uses ATP to absorb the remaining glucose against the concentration gradient (1).` },
    { q: 'Describe the function of the kidneys in removing urea.', marks: 3, command: 'Describe', markScheme: `• Urea is produced in the liver from excess amino acids and carried in the blood (1)\n• The kidneys filter urea and water out of the blood (1)\n• Urea is removed from the body dissolved in urine (1).` },
    { q: 'Explain why the cell membrane is described as partially permeable and name the three processes by which substances cross it.', marks: 4, command: 'Explain', markScheme: `• It allows some substances through but not others (1)\n• Gases and small molecules cross by diffusion (1)\n• Water crosses by osmosis (1)\n• Other substances, including ions and glucose against a gradient, cross by active transport (1).` },
    { q: 'Describe the path of blood through the heart, starting at the vena cava.', marks: 5, command: 'Describe', markScheme: `• Deoxygenated blood enters the right atrium from the vena cava (1)\n• It passes into the right ventricle and is pumped out through the pulmonary artery to the lungs (1)\n• Oxygenated blood returns from the lungs in the pulmonary vein to the left atrium (1)\n• It passes into the left ventricle (1)\n• It is pumped out through the aorta to the rest of the body (1).` },
    { q: 'Explain why the human circulatory system is described as a double circulatory system.', marks: 3, command: 'Explain', markScheme: `• Blood passes through the heart twice for each complete circuit of the body (1)\n• One circuit carries blood to the lungs and back (1)\n• The other carries blood to the rest of the body and back (1).` },
    { q: 'Explain the advantage of a double circulatory system.', marks: 3, command: 'Explain', markScheme: `• Blood returning from the lungs is pumped again before going to the body (1)\n• This restores the blood pressure, so blood travels faster to the tissues (1)\n• Oxygen and glucose are delivered more quickly, supporting a high metabolic rate (1).` },
    { q: 'Explain why the wall of the left ventricle is thicker than that of the right ventricle.', marks: 3, command: 'Explain', markScheme: `• The left ventricle pumps blood all the way around the body (1)\n• The right ventricle pumps only to the lungs, which are nearby (1)\n• A thicker muscular wall contracts with more force to generate the higher pressure needed (1).` },
    { q: 'Explain the function of the valves in the heart.', marks: 2, command: 'Explain', markScheme: `• They open in one direction only and close when pressure builds behind them (1)\n• This prevents the backflow of blood, so it flows in one direction through the heart (1).` },
    { q: 'Explain why cardiac muscle must contract continuously throughout life and how it is supplied.', marks: 3, command: 'Explain', markScheme: `• The heart must pump blood constantly to keep every organ supplied (1)\n• Cardiac muscle therefore has a very high demand for oxygen and glucose (1)\n• It is supplied by the coronary arteries, which branch from the aorta over the heart\'s surface (1).` },
    { q: 'Explain how the structure of an artery is adapted to its function.', marks: 4, command: 'Explain', markScheme: `• It has a thick wall containing muscle and elastic fibres (1)\n• This withstands the high pressure of blood leaving the heart (1)\n• The elastic fibres stretch and recoil, smoothing out the surges of pressure (1)\n• The lumen is narrow, which helps maintain the high pressure (1).` },
    { q: 'Explain how the structure of a vein is adapted to its function.', marks: 4, command: 'Explain', markScheme: `• It has a thin wall because the blood is at low pressure (1)\n• It has a wide lumen, which reduces resistance to flow (1)\n• It contains valves along its length (1)\n• These prevent backflow, so blood returns to the heart even against gravity (1).` },
    { q: 'Explain how a capillary is adapted for exchange.', marks: 3, command: 'Explain', markScheme: `• Its wall is only one cell thick, giving a very short diffusion distance (1)\n• Capillary networks are extensive, so every cell is close to a capillary (1)\n• The lumen is very narrow, so blood flows slowly, allowing time for exchange (1).` },
    { q: 'Explain how a red blood cell is adapted to its function.', marks: 4, command: 'Explain', markScheme: `• It contains haemoglobin, which binds oxygen (1)\n• It has no nucleus, leaving more room for haemoglobin (1)\n• Its biconcave disc shape gives a large surface area to volume ratio for diffusion (1)\n• It is small and flexible, so it can squeeze through narrow capillaries (1).` },
    { q: 'Describe how oxygen is carried from the lungs to a respiring muscle cell.', marks: 4, command: 'Describe', markScheme: `• Oxygen diffuses from the alveolus into the blood in the capillary (1)\n• It binds to haemoglobin in red blood cells to form oxyhaemoglobin (1)\n• The blood is carried to the muscle, where the oxygen concentration is low (1)\n• Oxyhaemoglobin releases the oxygen, which diffuses into the muscle cell (1).` },
    { q: 'State four substances transported by blood plasma.', marks: 2, command: 'State', markScheme: `Any 4 of: carbon dioxide; urea; dissolved food molecules such as glucose and amino acids; hormones; heat; antibodies; mineral ions (1 for two, 2 for four).` },
    { q: 'Explain why a person with anaemia becomes breathless during exercise.', marks: 3, command: 'Explain', markScheme: `• Anaemia means too few red blood cells or too little haemoglobin (1)\n• Less oxygen can be carried to the respiring muscles (1)\n• The person breathes faster to try to take in more oxygen, and muscles respire anaerobically sooner (1).` },
    { q: 'Explain the effect of carbon monoxide on oxygen transport in the blood.', marks: 3, command: 'Explain', markScheme: `• Carbon monoxide binds to haemoglobin much more strongly than oxygen does (1)\n• The binding is effectively irreversible, so that haemoglobin can no longer carry oxygen (1)\n• Less oxygen reaches the tissues, so respiration is reduced (1).` },
    { q: 'Explain why blood flow to the muscles increases during exercise.', marks: 3, command: 'Explain', markScheme: `• Muscles respire faster and need more oxygen and glucose (1)\n• Arterioles supplying the muscles widen, increasing blood flow to them (1)\n• More carbon dioxide and heat are also removed from the muscles (1).` },
    { q: 'Explain how fatty deposits in a coronary artery can cause a heart attack.', marks: 4, command: 'Explain', markScheme: `• Fatty plaques build up in the artery wall, narrowing the lumen (1)\n• Less blood, and therefore less oxygen, reaches part of the heart muscle (1)\n• If the artery becomes blocked, usually by a clot, that region of muscle is starved of oxygen (1)\n• The muscle cells cannot respire aerobically and die, which is a heart attack (1).` },
    { q: 'Describe how you could investigate the presence of valves in a vein of the arm.', marks: 3, command: 'Describe', markScheme: `• Place a tourniquet around the upper arm so the surface veins stand out (1)\n• Gently press a finger along the vein towards the hand and then towards the heart (1)\n• Blood moves easily towards the heart but not away from it, showing the valves only allow one-way flow (1).` },
    { q: 'Describe what can be observed by dissecting a lamb\'s heart.', marks: 4, command: 'Describe', markScheme: `• The four chambers: two thin-walled atria above and two thicker-walled ventricles below (1)\n• The left ventricle wall is visibly thicker than the right (1)\n• Valves between the atria and ventricles, and at the base of the arteries (1)\n• The major vessels: vena cava, pulmonary artery, pulmonary vein and aorta, and the coronary arteries on the surface (1).` },
    { q: 'Explain why a person breathes more deeply as well as more frequently during exercise.', marks: 3, command: 'Explain', markScheme: `• Deeper breaths increase the volume of air exchanged with each breath (1)\n• More alveoli are ventilated, maintaining a steep concentration gradient for oxygen (1)\n• So more oxygen enters the blood and more carbon dioxide is removed per minute (1).` },
    { q: 'A person\'s heart beats 72 times a minute and pumps 70 cm³ per beat. Calculate the cardiac output in dm³ per minute.', marks: 3, command: 'Calculate', markScheme: `• Cardiac output = 72 × 70 = 5040 cm³ per minute (1)\n• 1 dm³ = 1000 cm³ (1)\n• = 5.04 dm³ per minute (1).` },
    { q: 'During exercise the same person\'s heart rate rises to 150 beats per minute and stroke volume to 100 cm³. Calculate the new cardiac output in dm³ per minute.', marks: 2, command: 'Calculate', markScheme: `• 150 × 100 = 15 000 cm³ per minute (1)\n• = 15 dm³ per minute (1).` },
    { q: 'Explain why the concentration of urea in blood leaving the kidney is lower than in blood entering it.', marks: 2, command: 'Explain', markScheme: `• The kidney filters urea out of the blood into the kidney tubules (1)\n• The urea is excreted in urine rather than being returned to the blood (1).` },
    { q: 'Explain why the concentration of oxygen in blood leaving an active muscle is lower than in blood entering it.', marks: 2, command: 'Explain', markScheme: `• The muscle cells use oxygen rapidly in aerobic respiration (1)\n• Oxygen therefore diffuses out of the blood into the muscle cells as the blood passes through (1).` },
    { q: 'Suggest why a person living at high altitude produces more red blood cells than a person living at sea level.', marks: 3, command: 'Suggest', markScheme: `• Air at high altitude contains a lower concentration of oxygen (1)\n• Less oxygen diffuses into the blood at the alveoli (1)\n• Producing more red blood cells increases the total haemoglobin available, so more oxygen can be carried to the tissues (1).` },
    { q: 'Explain why an insect the size of a mouse would struggle to survive using only diffusion through its body surface.', marks: 4, command: 'Explain', markScheme: `• As size increases, surface area to volume ratio decreases (1)\n• Its outer surface would be too small relative to its volume to absorb enough oxygen (1)\n• The distance from the surface to the innermost cells would be too great for diffusion to be fast enough (1)\n• A specialised exchange surface and a transport system would be needed instead (1).` },
    { q: 'Discuss why multicellular organisms need both exchange surfaces and a transport system.', marks: 6, command: 'Discuss', markScheme: `Any 6: a large organism has a small surface area to volume ratio, so its outer surface cannot supply all its cells (1); exchange surfaces such as alveoli and villi provide the large surface area needed (1); they are thin, giving short diffusion distances (1); however substances absorbed at these surfaces are still far from most cells (1); diffusion alone over such distances would be far too slow (1); the circulatory system carries substances quickly to within a short distance of every cell (1); blood flow also maintains steep concentration gradients at the exchange surfaces (1); conclusion: the two work together, the exchange surface for uptake and the transport system for distribution (1).` },
  ]},
  /* ─────────────────────────────── B5.2 The nervous system */
  'B5.2': { name: 'How does the nervous system help us respond to changes?', questions: [
    { q: 'Explain why organisms need to detect and respond to changes in their environment.', marks: 2, command: 'Explain', markScheme: `• To avoid danger, find food and mates, and keep internal conditions within safe limits (1)\n• Organisms that respond appropriately are more likely to survive and reproduce (1).` },
    { q: 'Define the term "stimulus".', marks: 1, command: 'Define', markScheme: `• A change in the internal or external environment that is detected by a receptor (1).` },
    { q: 'Name the five components of the nervous pathway from stimulus to response, in order.', marks: 3, command: 'Name', markScheme: `• Receptor, sensory neurone (1)\n• Central nervous system / relay neurone (1)\n• Motor neurone, effector (1).` },
    { q: 'Name the two organs that make up the central nervous system.', marks: 1, command: 'Name', markScheme: `• The brain and the spinal cord (1).` },
    { q: 'State the function of a receptor and give two examples.', marks: 3, command: 'State', markScheme: `• A receptor detects a stimulus and converts it into an electrical impulse (1)\n• Any 2 of: light receptors in the retina; sound receptors in the ear; temperature receptors in the skin; taste receptors on the tongue; pressure receptors in the skin (1 each, max 2).` },
    { q: 'Name the two types of effector and state how each responds.', marks: 2, command: 'Name', markScheme: `• A muscle, which responds by contracting (1)\n• A gland, which responds by secreting a hormone or other substance (1).` },
    { q: 'Describe the function of a sensory neurone and a motor neurone.', marks: 2, command: 'Describe', markScheme: `• A sensory neurone carries impulses from a receptor to the central nervous system (1)\n• A motor neurone carries impulses from the central nervous system to an effector (1).` },
    { q: 'Explain how the structure of a neurone is adapted to its function.', marks: 4, command: 'Explain', markScheme: `• It is very long, so impulses can be carried over large distances in one cell (1)\n• The axon is insulated by a fatty sheath (1)\n• This increases the speed at which the impulse travels (1)\n• Branched endings connect it to many other neurones or effector cells (1).` },
    { q: 'Describe what happens in a stimulated neurone.', marks: 2, command: 'Describe', markScheme: `• An electrical impulse passes along the axon (1)\n• It travels in one direction, from the cell body towards the axon endings (1).` },
    { q: 'Define the term "synapse".', marks: 2, command: 'Define', markScheme: `• The junction between two neurones (1)\n• Where there is a small gap between the end of one neurone and the start of the next (1).` },
    { q: 'Describe how an impulse is transmitted across a synapse.', marks: 4, command: 'Describe', markScheme: `• The impulse arrives at the end of the first neurone (1)\n• This causes the release of a transmitter substance into the gap (1)\n• The transmitter diffuses across the gap (1)\n• It binds to receptor molecules on the next neurone, starting a new electrical impulse (1).` },
    { q: 'Explain why transmission across a synapse is slower than transmission along an axon.', marks: 2, command: 'Explain', markScheme: `• Diffusion of the transmitter substance across the gap takes time (1)\n• An electrical impulse along the axon travels much faster than diffusion (1).` },
    { q: 'Explain why synapses ensure that impulses travel in one direction only.', marks: 2, command: 'Explain', markScheme: `• Only the neurone before the synapse can release the transmitter substance (1)\n• Only the neurone after the synapse has the receptor molecules that bind it (1).` },
    { q: 'Explain how some drugs affect the nervous system at synapses.', marks: 3, command: 'Explain', markScheme: `• Some drugs have a similar shape to the natural transmitter substance (1)\n• They bind to the receptors on the next neurone, either triggering impulses or blocking them (1)\n• So the transmission of impulses is increased or prevented, changing sensation or behaviour (1).` },
    { q: 'Define the term "reflex action".', marks: 2, command: 'Define', markScheme: `• A rapid, automatic response to a stimulus (1)\n• That does not involve conscious thought (1).` },
    { q: 'Describe the pathway of a reflex arc in order.', marks: 5, command: 'Describe', markScheme: `• The stimulus is detected by a receptor (1)\n• An impulse passes along a sensory neurone to the spinal cord (1)\n• It crosses a synapse to a relay neurone (1)\n• It crosses a second synapse to a motor neurone (1)\n• The motor neurone carries the impulse to the effector, which produces the response (1).` },
    { q: 'Explain why reflex actions are important for survival.', marks: 3, command: 'Explain', markScheme: `• They are very fast because the impulse does not travel to the conscious areas of the brain (1)\n• This reduces the time between stimulus and response (1)\n• So the body is protected from damage, e.g. pulling the hand away from a hot object before it burns (1).` },
    { q: 'State three examples of reflex actions in humans.', marks: 3, command: 'State', markScheme: `Any 3 of: the withdrawal reflex when touching something hot or sharp (1); the pupil reflex in bright light (1); blinking when something approaches the eye (1); the knee-jerk reflex (1); coughing or sneezing (1).` },
    { q: 'Explain the role of the relay neurone in a reflex arc.', marks: 2, command: 'Explain', markScheme: `• It connects the sensory neurone to the motor neurone within the spinal cord (1)\n• This allows the response to be produced without the impulse having to travel to the brain (1).` },
    { q: 'Explain how the brain can modify a reflex response, using the example of holding a hot plate.', marks: 3, command: 'Explain', markScheme: `• The brain receives impulses about the stimulus at the same time as the reflex occurs (1)\n• It can send impulses along a neurone to the motor neurone of the reflex arc (1)\n• This can override the reflex so the plate is put down rather than dropped (1).` },
    { q: 'Describe how you could measure a person\'s reaction time using a metre ruler.', marks: 4, command: 'Describe', markScheme: `• One person holds a ruler vertically with the zero mark between the other person\'s open thumb and finger (1)\n• The ruler is dropped without warning and caught as quickly as possible (1)\n• The distance fallen is read from the ruler and converted to a time using a conversion table (1)\n• Repeat several times and calculate a mean, keeping the catching hand and starting position the same (1).` },
    { q: 'Suggest two variables that must be controlled in a reaction time investigation.', marks: 2, command: 'Suggest', markScheme: `Any 2 of: the same person catches the ruler each time (1); the same hand is used (1); the starting position of the fingers is the same (1); no caffeine or other stimulant is taken beforehand (1); the same absence of warning or distraction (1).` },
    { q: 'Explain why a mean of several readings is used in a reaction time investigation.', marks: 2, command: 'Explain', markScheme: `• Reaction times vary between attempts because of concentration and anticipation (1)\n• A mean reduces the effect of anomalous results and gives a more reliable value (1).` },
    { q: 'Name the three main regions of the brain covered in the specification.', marks: 3, command: 'Name', markScheme: `• The cerebral cortex (1)\n• The cerebellum (1)\n• The brain stem / medulla (1).` },
    { q: 'State the functions of the cerebral cortex.', marks: 2, command: 'State', markScheme: `• It is responsible for intelligence, memory and language (1)\n• And for consciousness (1).` },
    { q: 'State the function of the cerebellum and of the brain stem.', marks: 2, command: 'State', markScheme: `• The cerebellum controls conscious movement, including balance and coordination (1)\n• The brain stem regulates unconscious activities such as heart rate and breathing rate (1).` },
    { q: 'Explain why damage to the brain stem is usually more immediately life-threatening than damage to the cerebral cortex.', marks: 3, command: 'Explain', markScheme: `• The brain stem controls heart rate and breathing rate (1)\n• Damage to it can stop these unconscious processes (1)\n• Without them oxygen supply to all tissues fails within minutes, whereas cortex damage affects memory or movement but not the basic life processes (1).` },
    { q: 'Describe three methods scientists use to investigate the function of different regions of the brain.', marks: 3, command: 'Describe', markScheme: `• Studying patients with damage to a particular area and recording which functions are lost (1)\n• Stimulating regions electrically during surgery and recording the effect (1)\n• Using functional magnetic resonance imaging (fMRI) to show which regions are active during a task (1).` },
    { q: 'Explain how an fMRI scan shows which part of the brain is active.', marks: 3, command: 'Explain', markScheme: `• An active region of the brain respires faster and needs more oxygen and glucose (1)\n• Blood flow to that region increases (1)\n• The scanner detects this change in blood flow and displays it as an image of brain activity (1).` },
    { q: 'Explain why fMRI is an example of a technological development leading to new scientific explanations.', marks: 3, command: 'Explain', markScheme: `• Before fMRI, brain activity in a living, conscious person could not be observed directly (1)\n• fMRI made these observations possible (1)\n• Scientists could then develop and test explanations about which regions carry out which functions (1).` },
    { q: 'Explain three reasons why investigating brain function is difficult.', marks: 3, command: 'Explain', markScheme: `Any 3 of: the brain is extremely complex, with billions of neurones and connections (1); most regions are involved in many different functions rather than one (1); it is encased in the skull and easily damaged, so investigation is risky (1); results from damaged brains may not show normal function (1); ethical limits restrict experiments on healthy people (1).` },
    { q: 'Discuss the ethical issues raised by studying patients with brain damage.', marks: 4, command: 'Discuss', markScheme: `• The patient may be unable to give informed consent because of their injury (1)\n• Testing may be distressing or tiring for someone already ill (1)\n• The patient gains no direct benefit, although future patients may (1)\n• Their privacy must be protected when results are published (1).` },
    { q: 'Name the structures of the eye that focus light onto the retina.', marks: 2, command: 'Name', markScheme: `• The cornea (1)\n• The lens (1).` },
    { q: 'Describe the function of the retina and the optic nerve.', marks: 2, command: 'Describe', markScheme: `• The retina contains light receptor cells that detect light and convert it into electrical impulses (1)\n• The optic nerve carries these impulses to the brain (1).` },
    { q: 'Explain how the iris controls the amount of light entering the eye in bright light.', marks: 3, command: 'Explain', markScheme: `• Light receptors detect the bright light and impulses pass to the brain (1)\n• The circular muscles of the iris contract and the radial muscles relax (1)\n• The pupil becomes smaller, so less light enters and the retina is not damaged (1).` },
    { q: 'Explain why the pupil reflex is described as a reflex action.', marks: 2, command: 'Explain', markScheme: `• The response is rapid and automatic (1)\n• It happens without conscious thought and protects the retina from damage (1).` },
    { q: 'Explain how the ciliary muscles and suspensory ligaments focus the eye on a near object.', marks: 3, command: 'Explain', markScheme: `• The ciliary muscles contract (1)\n• The suspensory ligaments slacken (1)\n• The lens becomes thicker and more curved, refracting light more strongly to focus it on the retina (1).` },
    { q: 'Explain the cause of short-sightedness and how it is corrected.', marks: 3, command: 'Explain', markScheme: `• The lens is too curved or the eyeball too long, so light is focused in front of the retina (1)\n• Distant objects appear blurred (1)\n• A concave (diverging) lens spreads the light out before it enters the eye so that it focuses on the retina (1).` },
    { q: 'Explain the cause of long-sightedness and how it is corrected.', marks: 3, command: 'Explain', markScheme: `• The lens is too flat or the eyeball too short, so light would focus behind the retina (1)\n• Near objects appear blurred (1)\n• A convex (converging) lens brings the light together before it enters the eye so that it focuses on the retina (1).` },
    { q: 'Describe what a cataract is and how it is treated.', marks: 3, command: 'Describe', markScheme: `• The lens becomes cloudy or opaque (1)\n• Less light reaches the retina, so vision becomes blurred and colours appear faded (1)\n• It is treated by surgically removing the lens and replacing it with an artificial one (1).` },
  ]},
  /* ─────────────────────────────── B5.3 Hormonal control */
  'B5.3': { name: 'How do hormones control responses in the human body?', questions: [
    { q: 'Define the term "hormone".', marks: 3, command: 'Define', markScheme: `• A chemical messenger, usually a protein (1)\n• Secreted by an endocrine gland into the blood (1)\n• That travels to a target organ where it produces an effect (1).` },
    { q: 'Explain how a hormone affects only its target organ even though it travels all over the body.', marks: 2, command: 'Explain', markScheme: `• Cells of the target organ have receptor molecules complementary to the hormone (1)\n• Only cells with these receptors can bind the hormone and respond to it (1).` },
    { q: 'Compare nervous and hormonal coordination.', marks: 4, command: 'Compare', markScheme: `• Nervous responses use electrical impulses along neurones; hormonal responses use chemicals in the blood (1)\n• Nervous responses are very fast; hormonal responses are slower (1)\n• Nervous responses are short-lived; hormonal responses are longer-lasting (1)\n• Nervous responses act on a precise target; hormones may affect several organs (1).` },
    { q: 'Name four endocrine glands and one hormone secreted by each.', marks: 4, command: 'Name', markScheme: `Any 4, 1 mark each for gland with correct hormone: pituitary – FSH/LH/ADH; thyroid – thyroxine; adrenal gland – adrenaline; pancreas – insulin/glucagon; ovary – oestrogen/progesterone; testis – testosterone.` },
    { q: 'Explain why the pituitary gland is sometimes called the "master gland".', marks: 2, command: 'Explain', markScheme: `• It secretes several hormones in response to conditions in the body (1)\n• Many of these act on other endocrine glands, causing them to release their own hormones (1).` },
    { q: 'Describe the role of thyroxine in the body.', marks: 3, command: 'Describe', markScheme: `• Thyroxine is secreted by the thyroid gland (1)\n• It controls the basal metabolic rate, the rate at which chemical reactions occur in cells (1)\n• It is also important for growth and development (1).` },
    { q: 'Define the term "negative feedback".', marks: 3, command: 'Define', markScheme: `• A control mechanism in which a change in a level is detected (1)\n• A response is produced that acts in the opposite direction to the change (1)\n• So the level is returned towards its normal value (1).` },
    { q: 'Explain how the level of thyroxine in the blood is controlled by negative feedback.', marks: 4, command: 'Explain', markScheme: `• A fall in blood thyroxine is detected by the pituitary gland (1)\n• The pituitary secretes more thyroid stimulating hormone (TSH) (1)\n• TSH causes the thyroid gland to release more thyroxine, raising its level back to normal (1)\n• The rising thyroxine level then inhibits the release of TSH, so thyroxine production falls again (1).` },
    { q: 'Suggest two symptoms a person might show if their thyroid gland produced too little thyroxine.', marks: 4, command: 'Suggest', markScheme: `Any 2, 2 marks each: they feel tired and lack energy, because the metabolic rate is low so less energy is released (2); they gain mass, because fewer food molecules are broken down in respiration (2); they feel cold, because less heat is released by metabolic reactions (2).` },
    { q: 'Name the gland that secretes adrenaline and state the situation in which it is released.', marks: 2, command: 'Name', markScheme: `• The adrenal glands, found above the kidneys (1)\n• Released when a person is frightened, stressed or excited (1).` },
    { q: 'Describe four effects of adrenaline on the body.', marks: 4, command: 'Describe', markScheme: `Any 4 of: heart rate and breathing rate increase (1); blood glucose concentration rises as the liver converts glycogen to glucose (1); blood is diverted from the digestive system to the muscles (1); the pupils dilate (1); muscles become more ready to contract (1).` },
    { q: 'Explain why the effects of adrenaline are useful in a dangerous situation.', marks: 3, command: 'Explain', markScheme: `• More oxygen and glucose are delivered to the muscles (1)\n• So the muscles can respire faster and release more energy (1)\n• This prepares the body for "fight or flight", either fighting the danger or running from it (1).` },
    { q: 'Explain why adrenaline acts more quickly than thyroxine even though both are hormones.', marks: 2, command: 'Explain', markScheme: `• Adrenaline triggers immediate changes in target organs such as the heart (1)\n• Thyroxine acts by changing the rate of metabolic reactions throughout the body, which develops gradually over a longer period (1).` },
    { q: 'Name the organ that monitors and controls blood glucose concentration.', marks: 1, command: 'Name', markScheme: `• The pancreas (1).` },
    { q: 'Explain why blood glucose concentration must be controlled.', marks: 3, command: 'Explain', markScheme: `• Glucose is the substrate for respiration, so cells need a constant supply (1)\n• Too little glucose means cells cannot respire and release enough energy, and brain cells are damaged (1)\n• Too much glucose lowers the water potential of the blood, so water leaves cells by osmosis (1).` },
    { q: 'Describe how the body responds to a rise in blood glucose concentration after a meal.', marks: 4, command: 'Describe', markScheme: `• The pancreas detects the rise in blood glucose (1)\n• It secretes insulin into the blood (1)\n• Insulin causes body cells, particularly liver and muscle cells, to take up glucose (1)\n• The liver converts the excess glucose into glycogen for storage, so blood glucose falls back to normal (1).` },
    { q: 'Describe how the body responds to a fall in blood glucose concentration.', marks: 4, command: 'Describe', markScheme: `• The pancreas detects the fall in blood glucose (1)\n• It secretes glucagon into the blood (1)\n• Glucagon causes the liver to convert stored glycogen back into glucose (1)\n• Glucose is released into the blood, raising the concentration back to normal (1).` },
    { q: 'Explain what is meant by insulin and glucagon acting antagonistically.', marks: 2, command: 'Explain', markScheme: `• They have opposite effects on blood glucose concentration (1)\n• Insulin lowers it and glucagon raises it, allowing precise control in both directions (1).` },
    { q: 'Explain why the control of blood glucose is an example of negative feedback.', marks: 3, command: 'Explain', markScheme: `• A change in blood glucose away from the normal level is detected by the pancreas (1)\n• A hormone is released that produces the opposite change (1)\n• As the level returns to normal, the secretion of that hormone falls (1).` },
    { q: 'Describe the cause of type 1 diabetes.', marks: 2, command: 'Describe', markScheme: `• The pancreas stops producing enough insulin, or any insulin at all (1)\n• So blood glucose concentration cannot be lowered and rises to dangerous levels (1).` },
    { q: 'Describe the cause of type 2 diabetes.', marks: 2, command: 'Describe', markScheme: `• Body cells stop responding properly to the insulin that is produced (1)\n• The pancreas may also produce insufficient insulin, so blood glucose stays high (1).` },
    { q: 'Compare the treatment of type 1 and type 2 diabetes.', marks: 4, command: 'Compare', markScheme: `• Type 1 is treated with insulin injections, matched to meals and exercise (1)\n• Type 2 is usually controlled first by diet and exercise (1)\n• A type 2 diet is high in complex carbohydrates and low in simple sugars (1)\n• Medication or insulin injections may be added for type 2 if diet and exercise are not enough (1).` },
    { q: 'Explain why insulin must be injected rather than taken as a tablet.', marks: 2, command: 'Explain', markScheme: `• Insulin is a protein (1)\n• It would be digested by protease enzymes in the stomach and small intestine before it could be absorbed (1).` },
    { q: 'Explain why a person with type 1 diabetes must adjust their insulin dose before exercise.', marks: 3, command: 'Explain', markScheme: `• Exercise increases the rate at which muscles take up and respire glucose (1)\n• Blood glucose therefore falls more quickly than usual (1)\n• Without a reduced dose, the blood glucose could fall dangerously low (1).` },
    { q: 'Explain why obesity is a risk factor for type 2 diabetes.', marks: 3, command: 'Explain', markScheme: `• Excess body fat makes cells less sensitive to insulin (1)\n• More insulin is needed to produce the same fall in blood glucose (1)\n• Eventually the pancreas cannot produce enough and blood glucose stays high (1).` },
    { q: 'Explain why glucose appears in the urine of an untreated diabetic.', marks: 3, command: 'Explain', markScheme: `• Blood glucose concentration is much higher than normal (1)\n• The kidneys cannot reabsorb all the glucose filtered from the blood (1)\n• The excess is therefore excreted in the urine (1).` },
    { q: 'Name the four hormones that control the menstrual cycle.', marks: 2, command: 'Name', markScheme: `• FSH and LH (1)\n• Oestrogen and progesterone (1).` },
    { q: 'Describe the role of FSH in the menstrual cycle.', marks: 2, command: 'Describe', markScheme: `• FSH is released by the pituitary gland and causes a follicle containing an egg to mature in the ovary (1)\n• It also stimulates the ovary to produce oestrogen (1).` },
    { q: 'Describe the role of oestrogen in the menstrual cycle.', marks: 2, command: 'Describe', markScheme: `• It causes the lining of the uterus to thicken and repair (1)\n• At a high level it inhibits FSH and stimulates the release of LH (1).` },
    { q: 'Describe the role of LH in the menstrual cycle.', marks: 2, command: 'Describe', markScheme: `• A surge of LH from the pituitary causes the mature follicle to release its egg (1)\n• This is ovulation, at about day 14 of a 28-day cycle (1).` },
    { q: 'Describe the role of progesterone in the menstrual cycle.', marks: 3, command: 'Describe', markScheme: `• It is secreted by the remains of the follicle after ovulation (1)\n• It maintains the thickened uterus lining ready for implantation of a fertilised egg (1)\n• It also inhibits the release of FSH and LH (1).` },
    { q: 'Explain what happens to the uterus lining if the egg is not fertilised.', marks: 3, command: 'Explain', markScheme: `• The remains of the follicle break down, so progesterone levels fall (1)\n• The thickened uterus lining can no longer be maintained (1)\n• It breaks down and is lost as menstruation, and FSH is no longer inhibited so a new cycle begins (1).` },
    { q: 'Explain how the interaction of the four menstrual hormones is an example of negative feedback.', marks: 4, command: 'Explain', markScheme: `• FSH stimulates the ovary to produce oestrogen (1)\n• Rising oestrogen and later progesterone inhibit the release of FSH from the pituitary (1)\n• So FSH production falls and no further follicles mature during that cycle (1)\n• When progesterone falls at the end of the cycle the inhibition is removed and FSH rises again (1).` },
    { q: 'Explain how the combined oral contraceptive pill prevents pregnancy.', marks: 3, command: 'Explain', markScheme: `• It contains oestrogen and progesterone (1)\n• These inhibit the release of FSH and LH from the pituitary (1)\n• So no follicle matures and ovulation does not occur (1).` },
    { q: 'State two advantages and two disadvantages of hormonal contraception.', marks: 4, command: 'State', markScheme: `• Advantages, any 2: over 99 % effective if used correctly (1); does not interrupt intercourse (1); can reduce period pain or heavy bleeding (1)\n• Disadvantages, any 2: gives no protection against sexually transmitted infections (1); must be remembered daily or it becomes less effective (1); can cause side effects such as headaches, mood changes or raised blood pressure (1).` },
    { q: 'Compare hormonal and barrier methods of contraception.', marks: 4, command: 'Compare', markScheme: `• Hormonal methods prevent ovulation; barrier methods stop sperm reaching the egg (1)\n• Hormonal methods are more effective when used perfectly (1)\n• Barrier methods such as condoms also protect against sexually transmitted infections; hormonal methods do not (1)\n• Barrier methods have no hormonal side effects but must be used correctly every time (1).` },
    { q: 'Explain how hormones are used to treat a woman whose ovaries do not release eggs.', marks: 3, command: 'Explain', markScheme: `• She can be given FSH and LH as a fertility drug (1)\n• FSH stimulates follicles to mature in the ovary (1)\n• LH triggers the release of the eggs, so she may then become pregnant naturally (1).` },
    { q: 'Suggest two disadvantages of fertility treatment using hormones.', marks: 4, command: 'Suggest', markScheme: `Any 2, 2 marks each: it does not always work, so couples may spend a great deal of time and money without success (2); several eggs may be released, leading to multiple births which carry higher risks to mother and babies (2); the treatment can cause unpleasant side effects such as abdominal pain and nausea (2).` },
    { q: 'Explain why a doctor measures the level of a hormone in the blood rather than asking about symptoms alone.', marks: 3, command: 'Explain', markScheme: `• Symptoms such as tiredness or mass gain have many possible causes (1)\n• A measured hormone concentration gives objective, quantitative evidence (1)\n• It can be compared with the normal range to confirm the diagnosis and monitor treatment (1).` },
    { q: 'Discuss whether hormonal contraception or a non-hormonal method is the better choice for a couple.', marks: 6, command: 'Discuss', markScheme: `Any 6: hormonal methods are highly effective when used correctly (1); they do not interrupt intercourse and may relieve painful periods (1); however they can cause side effects and must be taken regularly (1); they give no protection against sexually transmitted infections (1); barrier methods protect against infection as well as pregnancy (1); barrier methods are slightly less reliable in typical use (1); the choice depends on the couple\'s health, whether they have one partner, and their plans for children (1); conclusion: a justified recommendation, e.g. using both together gives the best protection (1).` },
  ]},
  /* ─────────────────────────────── B5.4 Maintaining a constant internal environment */
  'B5.4': { name: 'Why do we need to maintain a constant internal environment?', questions: [
    { q: 'Define the term "homeostasis".', marks: 2, command: 'Define', markScheme: `• The maintenance of a constant internal environment in the body (1)\n• Despite changes in internal and external conditions (1).` },
    { q: 'Explain why homeostasis is essential for the body to function.', marks: 3, command: 'Explain', markScheme: `• Enzymes and other cell processes only work well within a narrow range of conditions (1)\n• Outside this range enzymes are denatured or work too slowly (1)\n• So metabolic reactions, and therefore the cells themselves, would fail (1).` },
    { q: 'Name three conditions controlled by homeostasis in the human body.', marks: 3, command: 'Name', markScheme: `• Body temperature (1)\n• Blood glucose concentration (1)\n• Water content of the body / blood plasma concentration (1).` },
    { q: 'Name the four components of a homeostatic control system.', marks: 4, command: 'Name', markScheme: `• Receptors that detect the change (1)\n• A processing or coordination centre (1)\n• Nerves or hormones to carry the information (1)\n• Effectors that produce the response (1).` },
    { q: 'Explain what is meant by antagonistic effectors and why they give better control.', marks: 3, command: 'Explain', markScheme: `• Two effectors that produce opposite effects (1)\n• One raises the level and the other lowers it (1)\n• So the level can be corrected from either direction, keeping it much closer to the ideal value (1).` },
    { q: 'Describe how you could model temperature control using a Bunsen burner and ice.', marks: 4, command: 'Describe', markScheme: `• Try to hold a beaker of water at 40 °C using only a Bunsen burner (1)\n• The temperature overshoots and then falls slowly, as there is only one effector (1)\n• Repeat using both a Bunsen burner and ice (1)\n• The temperature can be corrected in both directions, so it stays much closer to 40 °C, modelling antagonistic effectors (1).` },
    { q: 'State the normal core body temperature of a human and explain why it must be kept constant.', marks: 3, command: 'State', markScheme: `• About 37 °C (1)\n• This is the optimum temperature for most human enzymes (1)\n• Above about 40 °C enzymes begin to denature, and below about 35 °C reactions become too slow (1).` },
    { q: 'Name the part of the brain that monitors body temperature and state what it detects.', marks: 2, command: 'Name', markScheme: `• The hypothalamus (1)\n• It contains receptors that detect the temperature of the blood flowing through it (1).` },
    { q: 'Explain why the body has temperature receptors in the skin as well as in the hypothalamus.', marks: 3, command: 'Explain', markScheme: `• Skin receptors detect the temperature of the surroundings (1)\n• This gives early warning of a change before the core temperature alters (1)\n• So a response can begin before the blood temperature has actually changed (1).` },
    { q: 'Describe three responses the body makes when it becomes too hot.', marks: 3, command: 'Describe', markScheme: `• Sweat glands release more sweat onto the skin surface (1)\n• Blood vessels supplying the skin capillaries dilate (vasodilation) (1)\n• Hairs lie flat as the erector muscles relax (1).` },
    { q: 'Explain how sweating cools the body.', marks: 3, command: 'Explain', markScheme: `• Sweat is released onto the surface of the skin (1)\n• It evaporates, which requires energy (1)\n• This energy is taken from the skin, so the body is cooled (1).` },
    { q: 'Explain how vasodilation cools the body.', marks: 3, command: 'Explain', markScheme: `• The arterioles supplying the skin capillaries widen (1)\n• More blood flows through the capillaries near the skin surface (1)\n• More heat is therefore transferred from the blood to the surroundings by radiation (1).` },
    { q: 'Describe three responses the body makes when it becomes too cold.', marks: 3, command: 'Describe', markScheme: `• Sweat production decreases or stops (1)\n• Blood vessels supplying the skin capillaries constrict (vasoconstriction) (1)\n• Shivering begins and hairs stand up as erector muscles contract (1).` },
    { q: 'Explain how shivering helps to raise body temperature.', marks: 3, command: 'Explain', markScheme: `• Muscles contract and relax rapidly and involuntarily (1)\n• This requires ATP, so the rate of respiration in the muscle cells increases (1)\n• Respiration is exothermic, so more heat is released and warms the body (1).` },
    { q: 'Explain how vasoconstriction reduces heat loss.', marks: 3, command: 'Explain', markScheme: `• The arterioles supplying the skin capillaries narrow (1)\n• Less blood flows through the capillaries close to the skin surface (1)\n• So less heat is transferred from the blood to the surroundings (1).` },
    { q: 'Explain why hair erection is more effective at keeping a cat warm than a human.', marks: 3, command: 'Explain', markScheme: `• Raised hairs trap a layer of air next to the skin, which is a good insulator (1)\n• A cat has dense fur, so a thick insulating layer is trapped (1)\n• Humans have very little body hair, so almost no air is trapped and the effect is negligible (1).` },
    { q: 'Explain why a person feels cold and shivers when they have a fever but their temperature is high.', marks: 3, command: 'Explain', markScheme: `• During a fever the hypothalamus resets the temperature it maintains to a higher value (1)\n• The body\'s actual temperature is now below this new set point (1)\n• So the responses to cold, including shivering and vasoconstriction, are triggered (1).` },
    { q: 'Explain how the responses to a rise in body temperature are an example of negative feedback.', marks: 3, command: 'Explain', markScheme: `• The rise in temperature is detected by receptors in the skin and hypothalamus (1)\n• Responses such as sweating and vasodilation increase heat loss (1)\n• The temperature therefore falls back towards 37 °C, and the responses are reduced again (1).` },
    { q: 'Describe how you could compare skin temperature with core body temperature.', marks: 4, command: 'Describe', markScheme: `• Measure core temperature using a thermometer in the mouth or ear (1)\n• Measure skin temperature using a thermometer or probe held against the skin of the hand (1)\n• Take both readings in a warm room and again after a period in a cool room (1)\n• Compare the readings: core temperature stays almost constant while skin temperature changes considerably (1).` },
    { q: 'Explain why core temperature stays almost constant while skin temperature varies.', marks: 3, command: 'Explain', markScheme: `• Homeostasis maintains the temperature of the internal organs at about 37 °C (1)\n• The skin is the surface at which heat is exchanged with the surroundings (1)\n• Its temperature is allowed to vary so that heat loss can be controlled (1).` },
    { q: 'Explain why the water content of the blood must be controlled.', marks: 3, command: 'Explain', markScheme: `• The concentration of the blood plasma affects the movement of water into and out of cells by osmosis (1)\n• If the plasma is too dilute, water enters cells and they may burst (1)\n• If it is too concentrated, water leaves cells and they shrink, so they cannot function (1).` },
    { q: 'Explain the effect on a red blood cell of blood plasma becoming too dilute.', marks: 3, command: 'Explain', markScheme: `• The plasma has a higher water concentration than the cell contents (1)\n• Water moves into the cell by osmosis through the partially permeable membrane (1)\n• The cell swells and may burst, as it has no cell wall (1).` },
    { q: 'Explain the effect on a body cell of blood plasma becoming too concentrated.', marks: 3, command: 'Explain', markScheme: `• The plasma has a lower water concentration than the cell contents (1)\n• Water moves out of the cell by osmosis (1)\n• The cell shrinks and the concentration of its contents rises, so enzymes cannot work properly (1).` },
    { q: 'Name three ways in which water is lost from the human body.', marks: 3, command: 'Name', markScheme: `• In urine produced by the kidneys (1)\n• In sweat through the skin (1)\n• In water vapour breathed out from the lungs, and in faeces (1).` },
    { q: 'Describe the two main functions of the kidneys.', marks: 2, command: 'Describe', markScheme: `• They remove the waste product urea from the blood (1)\n• They control the water content of the body (1).` },
    { q: 'Describe how the kidneys maintain the water balance of the body.', marks: 4, command: 'Describe', markScheme: `• Blood passes through the kidney under high pressure (1)\n• Water, urea, glucose and mineral ions are filtered out of the blood into the kidney tubules (1)\n• All the glucose and as much water as the body needs is reabsorbed back into the blood (1)\n• The remaining water and urea leave the body as urine (1).` },
    { q: 'Explain why glucose is reabsorbed from the kidney tubule but urea is not.', marks: 2, command: 'Explain', markScheme: `• Glucose is a useful molecule needed for respiration, so it is reabsorbed by active transport (1)\n• Urea is a toxic waste product that must be removed from the body (1).` },
    { q: 'Name the hormone that controls the water content of the blood and the gland that releases it.', marks: 2, command: 'Name', markScheme: `• Antidiuretic hormone (ADH) (1)\n• Released by the pituitary gland (1).` },
    { q: 'Describe the effect of ADH on the kidney tubules.', marks: 2, command: 'Describe', markScheme: `• ADH increases the permeability of the kidney tubules to water (1)\n• So more water is reabsorbed back into the blood (1).` },
    { q: 'Describe the sequence of events when the blood becomes too concentrated.', marks: 5, command: 'Describe', markScheme: `• Receptors in the hypothalamus detect that the blood is too concentrated (1)\n• The hypothalamus signals the pituitary gland (1)\n• The pituitary releases more ADH into the blood (1)\n• The kidney tubules become more permeable, so more water is reabsorbed (1)\n• A small volume of concentrated urine is produced and the blood concentration returns to normal (1).` },
    { q: 'Describe the sequence of events when the blood becomes too dilute.', marks: 4, command: 'Describe', markScheme: `• Receptors in the hypothalamus detect that the blood is too dilute (1)\n• Less ADH is released from the pituitary gland (1)\n• The kidney tubules become less permeable, so less water is reabsorbed (1)\n• A large volume of dilute urine is produced, removing the excess water (1).` },
    { q: 'Explain why a person produces a small volume of dark urine on a hot day.', marks: 4, command: 'Explain', markScheme: `• A lot of water is lost in sweat, so the blood becomes more concentrated (1)\n• This is detected by receptors in the hypothalamus (1)\n• More ADH is released, making the kidney tubules more permeable to water (1)\n• More water is reabsorbed, so only a small volume of concentrated urine is produced (1).` },
    { q: 'Explain why a person produces a large volume of pale urine after drinking a lot of water.', marks: 3, command: 'Explain', markScheme: `• The blood becomes more dilute than normal (1)\n• Less ADH is released from the pituitary gland (1)\n• Less water is reabsorbed from the kidney tubules, so a large volume of dilute urine is produced (1).` },
    { q: 'Explain why the control of water content by ADH is an example of negative feedback.', marks: 3, command: 'Explain', markScheme: `• A change in blood concentration away from normal is detected by the hypothalamus (1)\n• The change in ADH release produces the opposite change in water reabsorption (1)\n• So the blood concentration returns towards normal and ADH release returns to its usual level (1).` },
    { q: 'Suggest why a person with kidney failure needs dialysis or a transplant.', marks: 3, command: 'Suggest', markScheme: `• Without working kidneys, urea is not removed and builds up to toxic levels in the blood (1)\n• The water and ion content of the blood can no longer be controlled (1)\n• Dialysis or a transplant is needed to carry out these functions, or the person would die (1).` },
    { q: 'Suggest why a drink containing salts and glucose is recommended after severe vomiting or diarrhoea.', marks: 4, command: 'Suggest', markScheme: `• Large volumes of water and mineral ions are lost from the body (1)\n• Replacing water alone would make the blood plasma too dilute (1)\n• The salts restore the ion concentration so osmotic balance is maintained (1)\n• The glucose provides a substrate for respiration and helps the absorption of water and salts in the intestine (1).` },
    { q: 'Explain why alcohol causes a person to produce more urine.', marks: 3, command: 'Explain', markScheme: `• Alcohol inhibits the release of ADH from the pituitary gland (1)\n• Less water is reabsorbed from the kidney tubules (1)\n• So more urine is produced, which can lead to dehydration (1).` },
    { q: 'A person exercising in a hot gym loses 1.2 dm³ of sweat and drinks 0.4 dm³ of water. Calculate their net water loss in cm³.', marks: 3, command: 'Calculate', markScheme: `• Net loss = 1.2 − 0.4 = 0.8 dm³ (1)\n• 1 dm³ = 1000 cm³ (1)\n• = 800 cm³ (1).` },
    { q: 'Urine output falls from 1500 cm³ to 600 cm³ per day. Calculate the percentage decrease.', marks: 3, command: 'Calculate', markScheme: `• Decrease = 1500 − 600 = 900 cm³ (1)\n• (900 ÷ 1500) × 100 (1)\n• = 60 % decrease (1).` },
    { q: 'Explain how the body responds to a long run on a hot day, referring to both temperature and water balance.', marks: 6, command: 'Explain', markScheme: `Any 6: respiring muscles release extra heat, raising body temperature (1); receptors in the skin and hypothalamus detect the rise (1); sweat production increases and skin arterioles dilate (1); evaporation of sweat and increased radiation from the skin cool the body (1); the water lost in sweat makes the blood plasma more concentrated (1); hypothalamic receptors detect this and the pituitary releases more ADH (1); the kidney tubules become more permeable so more water is reabsorbed (1); a small volume of concentrated urine is produced, conserving water while temperature is controlled (1).` },
  ]},
  /* ─────────────────────────────── B6.1 Developing the theory of evolution */
  'B6.1': { name: 'How was the theory of evolution developed?', questions: [
    { q: 'Define the term "evolution".', marks: 2, command: 'Define', markScheme: `• A change in the inherited characteristics of a population over a number of generations (1)\n• Through the process of natural selection, which may result in the formation of new species (1).` },
    { q: 'Name the two scientists who independently proposed the theory of evolution by natural selection.', marks: 2, command: 'Name', markScheme: `• Charles Darwin (1)\n• Alfred Russel Wallace (1).` },
    { q: 'State three types of observation that the theory of evolution by natural selection was developed to explain.', marks: 3, command: 'State', markScheme: `• New varieties of plants and animals produced by selective breeding (1)\n• Fossils showing both similarities to and differences from living species (1)\n• The different characteristics of isolated populations of the same species living in different ecosystems (1).` },
    { q: 'Describe the steps Darwin took in developing his explanation.', marks: 4, command: 'Describe', markScheme: `• He made detailed observations of the natural world over many years (1)\n• He suggested natural selection to explain the differences between fossils and living organisms, and between isolated populations (1)\n• He used ideas from Wallace and other scientists to improve his explanation (1)\n• He shared his explanation with the scientific community by publishing it (1).` },
    { q: 'Explain what this shows about how scientific explanations are developed.', marks: 3, command: 'Explain', markScheme: `• Scientists start from observations and propose an explanation that accounts for them (1)\n• They draw on and test the ideas of other scientists rather than working alone (1)\n• The explanation is published so that others can test it against new evidence (1).` },
    { q: 'Explain why Darwin delayed publishing his ideas for many years.', marks: 3, command: 'Explain', markScheme: `• He knew the idea contradicted the widely held religious belief that species were created unchanging (1)\n• He wanted to gather as much supporting evidence as possible before facing that opposition (1)\n• He published when he learned Wallace had reached the same conclusion independently (1).` },
    { q: 'Explain why the fact that Wallace reached the same conclusion independently strengthened the theory.', marks: 3, command: 'Explain', markScheme: `• Two scientists working separately used different observations to reach the same explanation (1)\n• This makes it less likely the conclusion was the result of one person\'s bias or error (1)\n• Independent agreement is strong evidence that an explanation fits the observations (1).` },
    { q: 'Define the term "fossil".', marks: 2, command: 'Define', markScheme: `• The preserved remains or traces of an organism that lived millions of years ago (1)\n• Found in rocks, and including bones, shells, footprints and burrows (1).` },
    { q: 'Explain how fossils provide evidence for evolution.', marks: 4, command: 'Explain', markScheme: `• Fossils in older rock layers are found deeper down than those in younger layers (1)\n• They show that the organisms living on Earth have changed over time (1)\n• Gradual changes in structure can be traced through a series of fossils of related organisms (1)\n• Fossils of extinct organisms show similarities to living species, suggesting common ancestry (1).` },
    { q: 'Describe how the fossil record shows the evolution of the modern horse.', marks: 3, command: 'Describe', markScheme: `• Early fossil ancestors were small, with several toes on each foot (1)\n• Later fossils show a gradual increase in size and a reduction in the number of toes (1)\n• The modern horse is large with a single hoof, suited to running fast on open grassland (1).` },
    { q: 'Explain why the fossil record is incomplete.', marks: 4, command: 'Explain', markScheme: `• Most organisms decay completely after death and leave no trace (1)\n• Soft-bodied organisms rarely form fossils because they have no hard parts (1)\n• Fossils that did form may have been destroyed by geological activity such as heat and pressure (1)\n• Many fossils remain buried and have not yet been found (1).` },
    { q: 'Explain why gaps in the fossil record were used to argue against Darwin\'s theory.', marks: 3, command: 'Explain', markScheme: `• Critics argued that intermediate forms between species were missing (1)\n• They claimed this showed species had not changed gradually into one another (1)\n• Later discoveries of transitional fossils, such as feathered dinosaurs, filled many of these gaps (1).` },
    { q: 'Define the term "selective breeding".', marks: 2, command: 'Define', markScheme: `• Choosing organisms with a desired characteristic and breeding them together (1)\n• Repeating this over many generations so the characteristic becomes more pronounced in the population (1).` },
    { q: 'Describe how a farmer could use selective breeding to produce cows that give more milk.', marks: 4, command: 'Describe', markScheme: `• Select the cows in the herd that produce the most milk (1)\n• Breed them with a bull from a high milk-yielding family (1)\n• Select the offspring with the highest milk yield and breed from them (1)\n• Repeat over many generations until the yield of the herd has increased (1).` },
    { q: 'State three characteristics that plants are commonly selectively bred for.', marks: 3, command: 'State', markScheme: `Any 3 of: higher crop yield; disease resistance; larger or sweeter fruit; drought or cold tolerance; attractive flowers (1 each).` },
    { q: 'Explain the impact of selective breeding on the ability to feed the human population.', marks: 4, command: 'Explain', markScheme: `• Most crops and farm animals have been selectively bred over thousands of years (1)\n• Modern varieties give far higher yields than their wild ancestors (1)\n• Disease-resistant varieties reduce losses and the need for chemical treatments (1)\n• More food is therefore produced from the same area of land, supporting a growing population (1).` },
    { q: 'Explain how observing selective breeding led Darwin towards the idea of natural selection.', marks: 3, command: 'Explain', markScheme: `• Selective breeding showed that choosing which individuals reproduce can change a population greatly over generations (1)\n• Darwin reasoned that a similar process of selection could occur in nature (1)\n• In nature the environment, rather than a breeder, determines which individuals survive to reproduce (1).` },
    { q: 'Explain why selective breeding can reduce genetic variation in a population.', marks: 3, command: 'Explain', markScheme: `• Only individuals with the desired characteristic are allowed to breed (1)\n• Alleles for other characteristics are gradually lost from the population (1)\n• Closely related individuals are often bred together, reducing variation further (1).` },
    { q: 'Suggest two problems that can result from reduced genetic variation in a selectively bred population.', marks: 4, command: 'Suggest', markScheme: `Any 2, 2 marks each: the population is vulnerable to a new disease, as few individuals have alleles giving resistance (2); harmful recessive alleles are more likely to appear as inbreeding increases (2); the population is less able to adapt if environmental conditions change (2).` },
    { q: 'Explain how isolated populations of the same species can come to look different.', marks: 4, command: 'Explain', markScheme: `• The two populations live in different environments with different conditions (1)\n• Different variants give an advantage in each environment (1)\n• Natural selection acts in a different direction in each population (1)\n• Over many generations the two populations develop different characteristics (1).` },
    { q: 'Describe how Darwin\'s observations of finches on the Galapagos Islands supported his ideas.', marks: 4, command: 'Describe', markScheme: `• Finches on different islands had beaks of different sizes and shapes (1)\n• Each beak shape suited the type of food available on that island (1)\n• The finches were otherwise very similar, suggesting they shared a common ancestor (1)\n• This supported the idea that isolated populations change over time to suit their environment (1).` },
    { q: 'Explain how antibiotic resistance in bacteria provides modern evidence for evolution.', marks: 4, command: 'Explain', markScheme: `• A random mutation makes one bacterium resistant to an antibiotic (1)\n• When the antibiotic is used, the non-resistant bacteria are killed (1)\n• The resistant bacterium survives and reproduces, passing on the resistance allele (1)\n• The population changes over generations, which is evolution by natural selection observed directly (1).` },
    { q: 'Explain why antibiotic resistance is particularly convincing evidence for evolution.', marks: 3, command: 'Explain', markScheme: `• Bacteria reproduce very rapidly, so many generations pass in a short time (1)\n• The change in the population can be observed and measured in a laboratory (1)\n• It is a prediction of the theory that has been directly confirmed, rather than inferred from fossils (1).` },
    { q: 'Explain how the development of the theory of evolution shows scientists testing an explanation.', marks: 4, command: 'Explain', markScheme: `• Once proposed, the explanation was used to make predictions about what should be found (1)\n• Scientists collected new evidence, including new fossils and later DNA evidence (1)\n• The explanation was able to account for these new observations (1)\n• It was therefore modified and refined rather than rejected, and became widely accepted (1).` },
    { q: 'Describe two kinds of evidence discovered after Darwin\'s death that support his theory.', marks: 4, command: 'Describe', markScheme: `Any 2, 2 marks each: the discovery of genes and DNA explained how characteristics are inherited and how variation arises through mutation, which Darwin could not explain (2); comparison of genomes shows that species classed as closely related do share more DNA, as the theory predicts (2); many transitional fossils have been found that fill gaps in the record (2); directly observed examples such as antibiotic resistance and peppered moths confirm natural selection in action (2).` },
    { q: 'Explain why Darwin could not explain how characteristics are passed on.', marks: 3, command: 'Explain', markScheme: `• Genes, chromosomes and DNA had not yet been discovered when he published (1)\n• Mendel\'s work on inheritance was not widely known or connected to Darwin\'s ideas at the time (1)\n• So Darwin could describe that variation was inherited but not how or why it arose (1).` },
    { q: 'Explain why most scientists now accept the theory of evolution by natural selection.', marks: 3, command: 'Explain', markScheme: `• It is the best available explanation for a very wide range of observations (1)\n• It has been tested repeatedly against new evidence from fossils, genetics and living populations (1)\n• Independent scientists have confirmed its predictions and it has not been contradicted (1).` },
    { q: 'Suggest two reasons why some people do not accept the theory of evolution.', marks: 4, command: 'Suggest', markScheme: `Any 2, 2 marks each: they are unaware of the evidence or have not had it explained to them (2); they find the evidence difficult to understand or judge (2); it conflicts with religious beliefs about how living things came to exist (2).` },
    { q: 'Explain the difference between the everyday and the scientific meaning of the word "theory".', marks: 3, command: 'Explain', markScheme: `• In everyday use a theory means a guess or an untested idea (1)\n• In science a theory is a well-tested explanation supported by a large body of evidence (1)\n• So calling evolution "only a theory" misunderstands how the word is used in science (1).` },
    { q: 'Explain the impact of the theory of evolution on modern biology.', marks: 4, command: 'Explain', markScheme: `• It provides a single framework that connects genetics, classification, ecology and medicine (1)\n• It explains why organisms are related and allows classification by common ancestry (1)\n• It explains the emergence of antibiotic resistance and new strains of pathogens (1)\n• It guides conservation by showing the importance of genetic variation in populations (1).` },
    { q: 'Explain why the theory of evolution is important in understanding infectious disease.', marks: 3, command: 'Explain', markScheme: `• Pathogens evolve rapidly because they reproduce quickly and mutate often (1)\n• This explains why new strains of influenza appear and vaccines must be changed each year (1)\n• It also explains why overuse of antibiotics selects for resistant bacteria (1).` },
    { q: 'Suggest why peer review was important in the acceptance of Darwin\'s ideas.', marks: 3, command: 'Suggest', markScheme: `• Other scientists examined the observations and the reasoning behind the explanation (1)\n• They tested it against evidence Darwin had not considered (1)\n• Acceptance by the wider scientific community, rather than by Darwin alone, gave the theory its authority (1).` },
    { q: 'Explain why a single fossil discovery is rarely enough to change an accepted scientific theory.', marks: 3, command: 'Explain', markScheme: `• One specimen may be misidentified, damaged or dated incorrectly (1)\n• An established theory is supported by a very large body of other evidence (1)\n• Scientists require the finding to be repeated or confirmed by independent work before the theory is revised (1).` },
    { q: 'Compare the work of Darwin and Wallace in developing the theory.', marks: 4, command: 'Compare', markScheme: `• Both independently proposed natural selection as the mechanism of evolution (1)\n• Both based their ideas on observations of organisms in different parts of the world (1)\n• Darwin had worked on the idea for far longer and had gathered much more supporting evidence (1)\n• Their ideas were first presented jointly, but Darwin\'s book set out the evidence in full and so is better known (1).` },
    { q: 'Explain why Darwin is given more credit than Wallace by most people today.', marks: 3, command: 'Explain', markScheme: `• Darwin published a detailed book setting out extensive supporting evidence (1)\n• He had spent decades gathering observations, so his case was far more thorough (1)\n• Wallace\'s contribution was a shorter essay, so his name became less widely known (1).` },
    { q: 'Suggest why an explanation may take many years to become widely accepted.', marks: 4, command: 'Suggest', markScheme: `• Evidence must be gathered, published and checked by other scientists (1)\n• Alternative explanations must be tested and ruled out (1)\n• The idea may conflict with strongly held existing beliefs (1)\n• Technology may not yet exist to make the observations that would settle the question (1).` },
    { q: 'Explain how the discovery of DNA supported and extended Darwin\'s theory.', marks: 4, command: 'Explain', markScheme: `• DNA provided the mechanism of inheritance that Darwin lacked (1)\n• Mutations in DNA explain how new variants arise in a population (1)\n• Comparing genomes shows that species thought to be related do share more DNA sequences (1)\n• This independent line of evidence agreed with conclusions previously based on fossils and anatomy (1).` },
    { q: 'Describe how fossils are formed when an organism is buried in sediment.', marks: 4, command: 'Describe', markScheme: `• The organism is buried quickly, so it is protected from decay by scavengers and decomposers (1)\n• Conditions such as lack of oxygen or water slow or prevent decomposition (1)\n• The soft parts decay but the hard parts remain and minerals gradually replace them (1)\n• Layers of sediment build up above and turn to rock, so the fossil is preserved and can later be exposed by erosion (1).` },
    { q: 'Suggest why so few organisms from the earliest periods of life on Earth have left fossils.', marks: 3, command: 'Suggest', markScheme: `• The earliest organisms were soft-bodied with no hard parts to preserve (1)\n• They were very small, so any traces are difficult to find and identify (1)\n• Rocks of that age have mostly been destroyed or altered by heat and pressure over billions of years (1).` },
    { q: 'Discuss the evidence for the theory of evolution by natural selection and why it is accepted by the scientific community.', marks: 6, command: 'Discuss', markScheme: `Any 6: fossils show that organisms have changed over very long periods of time (1); series of fossils show gradual change, e.g. the horse (1); selective breeding shows how quickly populations can be changed by selection (1); isolated populations such as the Galapagos finches show adaptation to local conditions (1); antibiotic resistance shows natural selection happening now and can be measured (1); DNA evidence shows relatedness that agrees with conclusions from anatomy and fossils (1); the theory has been tested against new evidence for over 150 years without being contradicted (1); conclusion: it is accepted because many independent lines of evidence support the same explanation (1).` },
  ]},
  /* ─────────────────────────────── B6.2 How evolution takes place */
  'B6.2': { name: 'How does evolution take place?', questions: [
    { q: 'Define the term "variation".', marks: 2, command: 'Define', markScheme: `• The differences in characteristics between individuals (1)\n• Between members of the same species or between different species (1).` },
    { q: 'State the two causes of variation between individuals of the same species.', marks: 2, command: 'State', markScheme: `• Genetic variation, caused by differences in the alleles inherited (1)\n• Environmental variation, caused by the conditions in which the individual has lived (1).` },
    { q: 'Explain why there is usually extensive genetic variation within a population of a species.', marks: 3, command: 'Explain', markScheme: `• Most populations contain a large number of different genetic variants (1)\n• New variants arise by mutation of the DNA (1)\n• Meiosis and the random fusion of gametes produce new combinations of these variants in each generation (1).` },
    { q: 'Define the term "mutation".', marks: 2, command: 'Define', markScheme: `• A random change in the sequence of bases in DNA (1)\n• It produces a new genetic variant, which may be inherited if it occurs in a gamete (1).` },
    { q: 'Describe the three possible effects a mutation can have on the phenotype.', marks: 3, command: 'Describe', markScheme: `• Most mutations have no effect on the phenotype at all (1)\n• Some influence the phenotype, altering a characteristic to some degree (1)\n• A very few determine the phenotype, having a large effect (1).` },
    { q: 'Explain why most mutations have no effect on an organism.', marks: 3, command: 'Explain', markScheme: `• Many mutations occur in the non-coding DNA between genes (1)\n• Even within a gene, a change may still code for the same amino acid (1)\n• The protein is therefore unchanged, so the phenotype is unaffected (1).` },
    { q: 'Explain how a mutation in a gene can change the protein it codes for.', marks: 3, command: 'Explain', markScheme: `• The sequence of bases determines the order of amino acids in the protein (1)\n• A change in a base can change one amino acid in the chain (1)\n• This may alter the shape of the protein, for example the active site of an enzyme, so it no longer works properly (1).` },
    { q: 'State two factors that increase the rate of mutation.', marks: 2, command: 'State', markScheme: `Any 2 of: ionising radiation such as X-rays, gamma rays or ultraviolet light (1); chemical mutagens such as those in tobacco smoke (1); some viruses (1).` },
    { q: 'Explain what is meant by a variant giving an organism an "advantage".', marks: 3, command: 'Explain', markScheme: `• The variant produces a phenotype better suited to the environment (1)\n• The organism competes more successfully for resources or avoids predators better (1)\n• So it is more likely to survive long enough to reproduce (1).` },
    { q: 'Describe the process of evolution by natural selection.', marks: 5, command: 'Describe', markScheme: `• There is extensive genetic variation within a population, arising from mutation (1)\n• Organisms compete for limited resources and not all survive (1)\n• Individuals with variants best suited to the environment are more likely to survive (1)\n• They are more likely to reproduce and pass on the alleles for those variants (1)\n• Over many generations the proportion of individuals with the beneficial variants increases (1).` },
    { q: 'Explain the importance of competition in natural selection.', marks: 3, command: 'Explain', markScheme: `• Resources such as food, water, territory and mates are limited (1)\n• Not every individual can obtain enough to survive and reproduce (1)\n• Competition therefore determines which variants are passed on, which is what drives natural selection (1).` },
    { q: 'Explain why natural selection acts on the phenotype rather than directly on the genotype.', marks: 3, command: 'Explain', markScheme: `• Survival depends on an organism\'s characteristics, such as speed, colour or resistance to disease (1)\n• These characteristics make up the phenotype (1)\n• Alleles are only selected indirectly, because they produce the phenotype that survives (1).` },
    { q: 'Explain how a population of beetles living on dark bark could become mostly dark coloured.', marks: 4, command: 'Explain', markScheme: `• The population contains beetles of a range of colours because of genetic variation (1)\n• Dark beetles are better camouflaged against the dark bark (1)\n• They are less likely to be seen and eaten by predators, so more survive to reproduce (1)\n• They pass on the alleles for dark colour, so over generations the proportion of dark beetles increases (1).` },
    { q: 'Explain how the peppered moth population changed during the industrial revolution.', marks: 4, command: 'Explain', markScheme: `• Soot from factories darkened tree bark in industrial areas (1)\n• Pale moths were now clearly visible against the dark bark and were eaten by birds (1)\n• Dark moths, produced by a mutation, were camouflaged and more likely to survive and reproduce (1)\n• The proportion of dark moths in industrial areas therefore increased over successive generations (1).` },
    { q: 'Explain why the proportion of pale peppered moths increased again after clean air laws were introduced.', marks: 3, command: 'Explain', markScheme: `• Less soot was produced, so tree bark and lichens became pale again (1)\n• Pale moths were now better camouflaged and dark moths more visible to predators (1)\n• Natural selection now favoured pale moths, so their proportion rose again (1).` },
    { q: 'Explain how a population of rabbits could evolve longer legs over many generations.', marks: 4, command: 'Explain', markScheme: `• Leg length varies between rabbits because of genetic variation (1)\n• Rabbits with longer legs run faster and are more likely to escape predators (1)\n• They survive to breed and pass on the alleles for longer legs (1)\n• Each generation contains a higher proportion of long-legged rabbits, so the mean leg length increases (1).` },
    { q: 'Explain how antibiotic resistance spreads through a population of bacteria.', marks: 5, command: 'Explain', markScheme: `• A random mutation in the DNA of one bacterium makes it resistant to the antibiotic (1)\n• When the antibiotic is used, non-resistant bacteria are killed (1)\n• The resistant bacterium survives and has no competition for resources (1)\n• It reproduces rapidly by binary fission, passing the resistance allele to its offspring (1)\n• The whole population soon becomes resistant, so the antibiotic no longer works (1).` },
    { q: 'Explain why resistant bacteria evolve faster than resistant insects.', marks: 3, command: 'Explain', markScheme: `• Bacteria reproduce extremely rapidly, dividing as often as every 20 minutes (1)\n• Far more generations occur in a given time (1)\n• So beneficial mutations spread through the population much more quickly (1).` },
    { q: 'Explain why MRSA is difficult to treat in hospitals.', marks: 3, command: 'Explain', markScheme: `• MRSA is resistant to several commonly used antibiotics, including methicillin (1)\n• Hospitals contain many patients whose immunity is already weakened (1)\n• Antibiotic use in hospitals creates strong selection pressure favouring resistant strains (1).` },
    { q: 'Describe three ways in which the development of antibiotic resistance can be slowed.', marks: 3, command: 'Describe', markScheme: `• Doctors should only prescribe antibiotics when they are genuinely needed, and not for viral infections (1)\n• Patients should complete the full course of any antibiotic prescribed (1)\n• The use of antibiotics in farming should be restricted (1).` },
    { q: 'Define the term "species".', marks: 2, command: 'Define', markScheme: `• A group of organisms that can breed together (1)\n• To produce fertile offspring (1).` },
    { q: 'Define the term "speciation".', marks: 2, command: 'Define', markScheme: `• The formation of a new species (1)\n• When a population becomes so different from its ancestors that they can no longer interbreed to produce fertile offspring (1).` },
    { q: 'Explain why speciation is more likely to occur when two populations are isolated.', marks: 4, command: 'Explain', markScheme: `• Isolation prevents the two populations from interbreeding (1)\n• So new variants arising in one population cannot spread to the other (1)\n• The environments differ, so natural selection acts in different directions in each (1)\n• Over many generations the populations become so different that they can no longer interbreed (1).` },
    { q: 'Describe how a mountain range could lead to the formation of two new species.', marks: 5, command: 'Describe', markScheme: `• The mountain range physically separates a population into two groups (1)\n• The two groups can no longer interbreed, so no alleles are exchanged (1)\n• Conditions on each side differ, so different variants give an advantage in each (1)\n• Natural selection changes the two populations in different directions over many generations (1)\n• Eventually they are so different that they could not produce fertile offspring even if brought back together (1).` },
    { q: 'State three ways in which populations of the same species could become isolated.', marks: 3, command: 'State', markScheme: `Any 3 of: a geographical barrier such as a river, mountain range or sea (1); separation onto different islands (1); breeding at different times of year (1); different mating behaviour so individuals no longer recognise each other as mates (1).` },
    { q: 'Explain why a mule, the offspring of a horse and a donkey, shows that horses and donkeys are separate species.', marks: 3, command: 'Explain', markScheme: `• A mule is produced when a horse and a donkey interbreed (1)\n• Mules are infertile and cannot themselves reproduce (1)\n• The definition of a species requires fertile offspring, so the two are separate species (1).` },
    { q: 'Explain the difference between continuous and discontinuous variation, giving an example of each.', marks: 4, command: 'Explain', markScheme: `• Continuous variation shows a range of values with no distinct categories, e.g. human height or mass (1)\n• It is usually controlled by several genes and influenced by the environment (1)\n• Discontinuous variation falls into distinct categories with no intermediates, e.g. human blood group (1)\n• It is usually controlled by one or a small number of genes and unaffected by the environment (1).` },
    { q: 'Explain why variation caused only by the environment cannot drive evolution.', marks: 3, command: 'Explain', markScheme: `• Environmental characteristics are not coded for in the DNA (1)\n• They cannot be passed on to offspring (1)\n• Only inherited variation can increase in frequency over generations (1).` },
    { q: 'Explain the difference between natural selection and selective breeding.', marks: 3, command: 'Explain', markScheme: `• In natural selection the environment determines which individuals survive to reproduce (1)\n• In selective breeding humans choose which individuals are allowed to breed (1)\n• Selective breeding is usually much faster because the selection pressure is stronger and deliberate (1).` },
    { q: 'Explain why a change in the environment can cause a species to become extinct.', marks: 4, command: 'Explain', markScheme: `• The characteristics that were previously an advantage may no longer suit the new conditions (1)\n• If no individuals carry variants suited to the new environment, none has an advantage (1)\n• Numbers fall as individuals fail to survive and reproduce (1)\n• If the change happens faster than the population can adapt, every individual dies and the species is extinct (1).` },
    { q: 'Explain why a population with more genetic variation is less likely to become extinct.', marks: 3, command: 'Explain', markScheme: `• A wider range of variants exists within the population (1)\n• If conditions change, some individuals are more likely to have a variant that suits the new conditions (1)\n• These individuals survive and reproduce, so the population can adapt rather than die out (1).` },
    { q: 'Explain why an individual organism cannot evolve.', marks: 3, command: 'Explain', markScheme: `• Evolution is a change in the inherited characteristics of a population (1)\n• An individual keeps the alleles it inherited throughout its life (1)\n• Change occurs only in the proportions of alleles across a population over generations (1).` },
    { q: 'Explain why the statement "giraffes stretched their necks to reach high leaves and passed this on" is incorrect.', marks: 4, command: 'Explain', markScheme: `• Characteristics acquired during an organism\'s lifetime do not change its DNA (1)\n• So a stretched neck could not be inherited by the offspring (1)\n• The correct explanation is that neck length varied because of genetic variation (1)\n• Giraffes with longer necks reached more food, survived and passed on the alleles for longer necks (1).` },
    { q: 'A pest species becomes resistant to an insecticide. Explain how this happened.', marks: 4, command: 'Explain', markScheme: `• A random mutation gave a few individuals resistance to the insecticide (1)\n• When the insecticide was sprayed, the non-resistant insects were killed (1)\n• The resistant insects survived and reproduced (1)\n• They passed on the resistance allele, so the proportion of resistant insects increased each generation (1).` },
    { q: 'Suggest why farmers are advised to alternate between different insecticides.', marks: 3, command: 'Suggest', markScheme: `• Using one insecticide continuously creates a constant selection pressure for resistance to it (1)\n• Alternating means insects resistant to the first are still killed by the second (1)\n• So resistant variants do not build up as rapidly in the population (1).` },
    { q: 'Explain why a new strain of influenza virus appears almost every year.', marks: 4, command: 'Explain', markScheme: `• The influenza virus has a very high mutation rate (1)\n• Mutations change the antigens on the surface of the virus (1)\n• Antibodies and memory cells from previous infections no longer recognise the new antigens (1)\n• The new strain therefore spreads through a population that is no longer immune (1).` },
    { q: 'Calculate the percentage increase if resistant bacteria rise from 12 % to 39 % of a population.', marks: 3, command: 'Calculate', markScheme: `• Increase = 39 − 12 = 27 percentage points (1)\n• (27 ÷ 12) × 100 (1)\n• = 225 % increase (1).` },
    { q: 'In a moth population, 340 of 800 moths are dark. Calculate the percentage that are dark.', marks: 2, command: 'Calculate', markScheme: `• (340 ÷ 800) × 100 (1)\n• = 42.5 % (1).` },
    { q: 'Suggest why an island population of birds often contains species found nowhere else.', marks: 4, command: 'Suggest', markScheme: `• The island population is isolated from the mainland, so no alleles are exchanged (1)\n• The island environment offers different food and different predators (1)\n• Natural selection therefore acts in a different direction from on the mainland (1)\n• Over many generations the isolated population becomes a separate species found only there (1).` },
    { q: 'Discuss how the evolution of antibiotic resistance demonstrates every stage of natural selection.', marks: 6, command: 'Discuss', markScheme: `Any 6: genetic variation exists in the bacterial population, created by random mutation (1); the mutation arises by chance, not in response to the antibiotic (1); the antibiotic acts as the selection pressure (1); bacteria compete and only those with the resistance variant survive (1); survivors reproduce and pass the allele to their offspring (1); the proportion of resistant bacteria increases each generation (1); the change can be measured directly because bacteria reproduce so rapidly (1); conclusion: it demonstrates variation, selection pressure, differential survival and inheritance, which are the complete mechanism (1).` },
  ]},
  /* ─────────────────────────────── B6.3 Biodiversity and human activity */
  'B6.3': { name: 'How is biodiversity affected by human activity?', questions: [
    { q: 'Define the term "biodiversity".', marks: 3, command: 'Define', markScheme: `• The variety of living organisms in an area (1)\n• Including the variety of genes those organisms have (1)\n• And the variety of ecosystems present (1).` },
    { q: 'Explain why genetic diversity within a species is part of biodiversity.', marks: 3, command: 'Explain', markScheme: `• Individuals of the same species differ in the alleles they carry (1)\n• This variation allows a population to adapt if conditions change (1)\n• A species with very little genetic variation is vulnerable even if its numbers are large (1).` },
    { q: 'State three human activities that reduce biodiversity.', marks: 3, command: 'State', markScheme: `Any 3 of: deforestation; building and urban development; farming as monoculture; pollution of air, water or land; overfishing and hunting; draining peat bogs and wetlands (1 each).` },
    { q: 'Explain why an increasing human population reduces biodiversity.', marks: 4, command: 'Explain', markScheme: `• More land is needed for housing, farming and industry (1)\n• Habitats are destroyed or fragmented, so populations lose food and shelter (1)\n• More resources are used and more waste and pollution are produced (1)\n• Species that cannot survive the changed conditions die out (1).` },
    { q: 'Explain how deforestation reduces biodiversity.', marks: 4, command: 'Explain', markScheme: `• Trees provide habitats, food and shelter for many species (1)\n• Removing them destroys these habitats, so populations fall (1)\n• Species that live only in that forest may become extinct (1)\n• The remaining fragments are too small to support large populations, reducing genetic diversity (1).` },
    { q: 'State two other environmental consequences of deforestation besides loss of habitat.', marks: 4, command: 'State', markScheme: `Any 2, 2 marks each: less photosynthesis so less carbon dioxide is removed from the atmosphere, contributing to global warming (2); burning or decay of the trees releases stored carbon dioxide (2); tree roots no longer hold the soil, so it is eroded and washed into rivers (2).` },
    { q: 'Explain why farming a single crop over a large area reduces biodiversity.', marks: 3, command: 'Explain', markScheme: `• Only one plant species is grown, so other plants are removed as weeds (1)\n• Animals that depend on those plants for food or shelter lose their habitat (1)\n• Pesticides and herbicides kill further species, so the community becomes very simple (1).` },
    { q: 'Explain how the destruction of peat bogs contributes to global warming.', marks: 4, command: 'Explain', markScheme: `• Peat is partly decayed plant material that stores a large amount of carbon (1)\n• Draining the bog allows oxygen to reach the peat (1)\n• Aerobic decomposition, or burning, then releases this carbon as carbon dioxide (1)\n• The increased carbon dioxide in the atmosphere enhances the greenhouse effect (1).` },
    { q: 'Explain why peat bogs are drained and suggest an alternative to using peat compost.', marks: 3, command: 'Explain', markScheme: `• Peat is drained and extracted for use as compost in gardening and horticulture (1)\n• Land is also drained to create farmland (1)\n• Peat-free composts made from bark, coir or garden waste can be used instead (1).` },
    { q: 'Describe how air pollution can affect the distribution of organisms.', marks: 3, command: 'Describe', markScheme: `• Sulfur dioxide and nitrogen oxides dissolve in rain water to form acid rain (1)\n• Acid rain damages the leaves of trees and lowers the pH of soils and lakes (1)\n• Species intolerant of the low pH, such as many lichens and fish, disappear from polluted areas (1).` },
    { q: 'Explain how water pollution by sewage can reduce biodiversity in a river.', marks: 4, command: 'Explain', markScheme: `• Sewage adds organic matter and nutrients to the water (1)\n• Decomposers multiply and respire aerobically as they break it down (1)\n• The dissolved oxygen concentration falls sharply (1)\n• Species needing high oxygen, such as mayfly nymphs and trout, die, so only a few tolerant species remain (1).` },
    { q: 'Explain how the use of indicator species can reveal the impact of pollution.', marks: 3, command: 'Explain', markScheme: `• Some species survive only within a narrow range of conditions (1)\n• Their presence or absence therefore indicates the level of pollution (1)\n• For example, bushy lichens indicate clean air while mayfly nymphs indicate clean water (1).` },
    { q: 'Describe how living and non-living indicators could be used to assess pollution in a stream.', marks: 4, command: 'Describe', markScheme: `• Use a net to sample the invertebrates at several points along the stream (1)\n• Identify them with a key and record which indicator species are present (1)\n• Use instruments such as an oxygen probe and a pH meter to measure abiotic factors at the same points (1)\n• Compare the results upstream and downstream of the suspected pollution source (1).` },
    { q: 'Define the term "extinction".', marks: 2, command: 'Define', markScheme: `• When no individuals of a species remain anywhere on Earth (1)\n• So the species can never be recovered (1).` },
    { q: 'Explain why a species becomes extinct when conditions change faster than it can adapt.', marks: 3, command: 'Explain', markScheme: `• Adaptation by natural selection requires many generations (1)\n• If the environment changes rapidly, no individuals may have variants suited to the new conditions (1)\n• All individuals fail to survive and reproduce, so the species dies out (1).` },
    { q: 'State four causes of extinction.', marks: 4, command: 'State', markScheme: `Any 4 of: destruction of habitat; a new predator; a new competitor; a new disease; hunting or overfishing by humans; a rapid change in climate; a catastrophic event such as a volcanic eruption (1 each).` },
    { q: 'Explain why species living only on one small island are at particular risk of extinction.', marks: 3, command: 'Explain', markScheme: `• The total population is small, so genetic diversity is low (1)\n• There is nowhere else for the species to survive if conditions change (1)\n• A single event, such as a new predator or a storm, can destroy the whole population (1).` },
    { q: 'Explain why humans depend on biodiversity for food.', marks: 3, command: 'Explain', markScheme: `• Crops and farm animals are bred from wild species (1)\n• Wild relatives are a source of new alleles for disease resistance and higher yield (1)\n• Many crops also depend on insect pollinators, so losing them would reduce food production (1).` },
    { q: 'Explain why biodiversity is important as a source of medicines.', marks: 3, command: 'Explain', markScheme: `• Many medicines were originally discovered in wild plants and microorganisms, e.g. aspirin from willow (1)\n• Most species have never been screened for useful substances (1)\n• If a species becomes extinct, any medicine it could have provided is lost forever (1).` },
    { q: 'State two other reasons, besides food and medicine, for protecting biodiversity.', marks: 4, command: 'State', markScheme: `Any 2, 2 marks each: ecosystems provide services such as clean water, pollination and nutrient cycling that humans depend on (2); forests and oceans absorb carbon dioxide, slowing climate change (2); many people believe species have a right to exist regardless of human use (2); wildlife has cultural, recreational and economic value through tourism (2).` },
    { q: 'Describe three ways in which humans interact positively with ecosystems.', marks: 3, command: 'Describe', markScheme: `Any 3 of: establishing nature reserves and protected areas (1); breeding programmes for endangered species (1); replanting hedgerows and creating field margins on farmland (1); reforestation and habitat restoration (1); recycling to reduce the demand for raw materials (1).` },
    { q: 'Define the term "sustainable" in the context of using ecosystem resources.', marks: 2, command: 'Define', markScheme: `• Using a resource at the same rate as it is replaced (1)\n• So it remains available for future generations (1).` },
    { q: 'Describe two ways in which fishing could be made more sustainable.', marks: 4, command: 'Describe', markScheme: `Any 2, 2 marks each: fishing quotas limit the mass of fish caught, so enough adults remain to breed (2); net mesh size limits allow young fish to escape and reach breeding age (2); closed seasons or protected areas allow stocks to recover during breeding (2).` },
    { q: 'Explain why fishing quotas can be difficult to agree between countries.', marks: 3, command: 'Explain', markScheme: `• Fish move between waters controlled by different countries (1)\n• Each country wants a large quota to protect its own fishing industry and jobs (1)\n• Restraint by one country brings no benefit if others continue to overfish (1).` },
    { q: 'Explain how a conservation programme can protect an endangered species.', marks: 4, command: 'Explain', markScheme: `• The remaining habitat is protected so the species has food and shelter (1)\n• Individuals may be bred in captivity to increase numbers (1)\n• Breeding records are used to pair unrelated individuals and maintain genetic diversity (1)\n• Offspring can then be released into protected areas to rebuild the wild population (1).` },
    { q: 'Explain why maintaining genetic diversity is important in a captive breeding programme.', marks: 3, command: 'Explain', markScheme: `• Captive populations are small, so closely related individuals may be bred together (1)\n• This increases the chance of harmful recessive alleles appearing (1)\n• Low genetic diversity also leaves the species less able to adapt when released into the wild (1).` },
    { q: 'Describe two ways a farmer can increase biodiversity on farmland.', marks: 4, command: 'Describe', markScheme: `Any 2, 2 marks each: replant hedgerows to provide habitats and corridors between fields (2); leave uncultivated field margins where wild flowers and insects can live (2); reduce pesticide use so that non-target species survive (2); rotate crops rather than growing the same monoculture each year (2).` },
    { q: 'Explain how controlling greenhouse gas emissions helps to protect biodiversity.', marks: 4, command: 'Explain', markScheme: `• Greenhouse gases cause global warming and climate change (1)\n• Changing temperature and rainfall alter the conditions in habitats worldwide (1)\n• Species unable to move or adapt fast enough die out (1)\n• Limiting emissions slows the change, giving species time to adapt or migrate (1).` },
    { q: 'Describe how rising temperatures can change the distribution of a species.', marks: 3, command: 'Describe', markScheme: `• A species can only live where conditions are within the range it tolerates (1)\n• As temperatures rise, that range shifts towards the poles or to higher altitude (1)\n• The species spreads into newly suitable areas and disappears from areas that have become too warm (1).` },
    { q: 'Explain how changes in atmospheric gases can affect organisms in the oceans.', marks: 3, command: 'Explain', markScheme: `• More carbon dioxide dissolves in sea water as its atmospheric concentration rises (1)\n• This lowers the pH of the ocean, making it more acidic (1)\n• Organisms with shells or skeletons made of calcium carbonate, such as corals, are damaged (1).` },
    { q: 'Explain how reduced rainfall can change the distribution of plant species in a region.', marks: 3, command: 'Explain', markScheme: `• Plants need water for photosynthesis and to remain turgid (1)\n• Species needing plenty of water cannot survive and die out in that area (1)\n• Drought-tolerant species spread into the area, so the community changes (1).` },
    { q: 'Define the term "food security".', marks: 2, command: 'Define', markScheme: `• Having enough food to feed a population (1)\n• That is reliably available, affordable and of adequate nutritional quality (1).` },
    { q: 'Describe four biological factors that threaten food security.', marks: 4, command: 'Describe', markScheme: `• The increasing human population requires more food from the same land (1)\n• Changing diets in wealthier populations mean more meat is eaten, which is a less efficient use of land (1)\n• New pests and pathogens damage crops and livestock (1)\n• Environmental change, such as drought and flooding, reduces yields (1).` },
    { q: 'Explain why eating less meat could improve global food security.', marks: 4, command: 'Explain', markScheme: `• Biomass is lost at each transfer between trophic levels (1)\n• Feeding crops to animals and then eating the animals wastes most of the biomass the crop produced (1)\n• Eating the crops directly makes humans primary consumers, so far less biomass is lost (1)\n• More people can therefore be fed from the same area of land (1).` },
    { q: 'Describe how genetic modification could be used to increase food production.', marks: 4, command: 'Describe', markScheme: `• A gene for a useful characteristic is identified in another organism (1)\n• It is cut out and inserted into the crop plant\'s DNA (1)\n• The crop then expresses that characteristic, e.g. resistance to a pest, herbicide tolerance or added vitamins (1)\n• Yields increase because less of the crop is lost or because it grows in poorer conditions (1).` },
    { q: 'Suggest two concerns people have about growing genetically modified crops.', marks: 4, command: 'Suggest', markScheme: `Any 2, 2 marks each: inserted genes might spread to wild plants, creating herbicide-resistant weeds (2); the long-term effects on human health are uncertain to some people (2); GM crops may reduce biodiversity by replacing many local varieties with a single one (2); farmers may become dependent on seed sold by a small number of companies (2).` },
    { q: 'Describe one biotechnological solution, other than GM crops, to the demands of a growing population.', marks: 3, command: 'Describe', markScheme: `• Mycoprotein is produced by growing the fungus Fusarium in a fermenter (1)\n• It is grown on cheap glucose syrup under controlled conditions of temperature, pH and oxygen (1)\n• It provides a high-protein food using far less land than livestock farming (1).` },
    { q: 'Explain why decisions about conservation involve more than scientific evidence.', marks: 4, command: 'Explain', markScheme: `• Science can show what the consequences of an action are likely to be (1)\n• It cannot decide how much value to place on a species or a habitat (1)\n• Economic factors such as jobs and the cost of protection must be weighed (1)\n• Moral and political views about our responsibility to other species also affect the decision (1).` },
    { q: 'A rare orchid grows on land where a hospital is to be built. Suggest two arguments on each side of the decision.', marks: 4, command: 'Suggest', markScheme: `• For building, any 2: the hospital will save lives and improve health (1); it will provide jobs and economic benefit (1)\n• For protecting the orchid, any 2: the species may exist nowhere else and extinction is irreversible (1); the orchid may have undiscovered uses, e.g. medicinal (1); the hospital could be built on an alternative site (1). Max 4 overall.` },
    { q: 'Discuss the benefits and challenges of maintaining biodiversity locally and globally.', marks: 6, command: 'Discuss', markScheme: `Any 6: biodiversity provides food, medicines and raw materials (1); ecosystems supply services such as pollination, clean water and nutrient cycling (1); genetic diversity in wild relatives is needed to improve crops (1); many people value wildlife for its own sake and for recreation and tourism (1); however conservation costs money that could be spent on other priorities (1); protecting habitat may prevent development that would bring jobs and housing (1); global problems such as climate change need international agreement, which is hard to reach (1); conclusion: a justified judgement, e.g. sustainable use protects biodiversity while still allowing human needs to be met (1).` },
  ]},

};

